Ceviri.ekle("fa","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["حضرموت سنجق عثمانی شد — اداره داخلی در دست سران کثیری ماند", "d80f8d20"], "d": ["حضرموت که در جریان لشکرکشی خادم سلیمان پاشا به هند به اداره عثمانی درآمد، به‌عنوان سنجقی وابسته به یمن سازمان یافت. اما درون حضرموت اداره را عملاً سران قبیلهٔ کثیری در دست داشتند؛ حاکمیت عثمانی به پیوند ساحلی و مالیاتی محدود ماند.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["امام زیدی متوکل علی‌الله حضرموت را اشغال کرد — سلطان‌نشین کثیری به امامت یمن وابسته شد", "21ad9c85"], "d": ["امامت زیدی که پس از عقب‌نشینی عثمانی از یمن در 1635 نیرومند شد، در زمان امام متوکل علی‌الله سپاهی فرستاد و حضرموت را اشغال کرد. حاکمیت کثیری‌ها در حضرموت درونی بدین‌سان نزدیک به نیم‌سده به امامت یمن تابع ماند؛ در نیمهٔ نخست سدهٔ 18 چون نفوذ امامان و کثیری‌ها سست شد، اداره دوباره به قبایل محلی گذشت.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["عبدالله بن رشید امارت حائل را از خاندان ابن علی گرفت — امارت شمر (رشیدی) تأسیس شد", "357cc1a0"], "d": ["عبدالله بن رشید از عبده، بزرگ‌ترین شاخهٔ قبیلهٔ شمر، با برادرش عبید کشمکشی را که علیه خاندان ابن علی، حاکم حائل، آغاز کرده بود در 1835 برد و امارت را گرفت. حائل با جایگاهش بر راه تجارت و حج بین‌النهرین-حجاز مرکز حاکمیت جبل شمر رشیدیان شد که تا 1921 ادامه خواهد یافت.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["تأسیس امارت عثمانی", "9f0b7c0a"], "d": ["آغاز مستقل عمل کردن عثمان غازی از تیرهٔ قایی در پیرامون سوگوت-دومانیچ، آغاز سنتی‌شده برای تأسیس دولت عثمانی شمرده می‌شود؛ برخی مورخان پیروزی باپهئوس 1302 را نقطهٔ عطف واقعی می‌دانند. امارت به برکت جایگاهش در منطقهٔ مرزی بیزانس با یورش‌های غزا به‌سرعت نیرو گرد آورد. در این فضا که میراث سلجوقی فرو می‌پاشید، عثمان غازی اخی‌ها، غازیان و ترکمانان کوچ‌نشین را گرد خود آورد؛ پیوندی که با شیخ ادب‌العلی بست بنیاد مشروعیت معنوی امارت شمرده می‌شود. سایر آبادی‌هایی که در همین تاریخ پیوستند: اینه‌گول، یارحصار.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["فتح بورسا", "98c727fa"], "d": ["بورسا که سال‌ها در محاصره نگاه داشته شده بود، به اورخان غازی که واپسین مرحلهٔ محاصره را هدایت می‌کرد تسلیم شد؛ شهر نخستین پایتخت بزرگ امارت شد. روایت شده خبر فتح به عثمان غازی که بر بستر مرگ بود رسانده شد؛ عثمان غازی بنا به وصیتش در بورسا به خاک سپرده شد. شهر در مدتی کوتاه با مسجد، عمارت و مدرسه آراسته شد و الگوی شهرسازی عثمانی آغازین گشت.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["فتح ایزنیک", "a846a811"], "d": ["ایزنیک (نیکایا) از مهم‌ترین مراکز بیزانس در آناتولی، پس از پیروزی پلکانون 1329 امید مقاومت را از دست داد و به اورخان غازی تسلیم شد. نخستین مدرسهٔ عثمانی در آنجا بنیان نهاده شد و دانشمندانی چون داود قیصری به تدریس پرداختند؛ شهر مرکز دانش دورهٔ آغازین شد. کلیسای ایاصوفیه به مسجد بدل شد و نمونه‌ای آغازین از سنت فتح را نشان داد.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["فتح ایزمیت", "06a35035"], "d": ["با سقوط ایزمیت (نیکومدیا)، واپسین قلعهٔ مهم بیزانس در سوی آناتولی نیز به اداره عثمانی درآمد؛ سراسر شبه‌جزیرهٔ کوجائلی تا کرانهٔ روبه‌روی قسطنطنیه سرزمین عثمانی شد. بدین‌سان امارت بر سراسر کرانه‌های جنوبی و شرقی مرمره چیره شد و زیرساخت گذشتن به روم‌ایلی را فراهم کرد.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["قلعهٔ چیمپه — گذشتن به روم‌ایلی", "c2f0a07d"], "d": ["سلیمان پاشا، پسر اورخان غازی، قلعهٔ چیمپه را که در جنگ داخلی بیزانس به او داده شده بود در 1352 پایگاه خود ساخته بود؛ پس از زلزلهٔ بزرگ مارس 1354 که گلیبولو را ویران کرد، قلعه‌های تخلیه‌شده به‌سرعت مستحکم شد و شبه‌جزیره به سرپل ماندگار عثمانی بدل گشت. این گام که با اسکان جمعیت ترکمان آورده‌شده از آناتولی پشتیبانی می‌شد، آغاز حضور عثمانیان در قارهٔ اروپا است که از 550 سال فراتر خواهد رفت.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["فتح ادرنه", "2f54ebb0"], "d": ["گرفته شدن ادرنه (آدریانوپولیس)، شهر کلیدی تراکیه، پایگاه اصلی و جهت فتوحات بالکان را تعیین کرد؛ تاریخ فتح در منابع میان 1361 و 1369 محل مناقشه است. شهر اندکی بعد پایتخت شد و اعلام کرد مرکز ثقل دولت به روم‌ایلی لغزیده است؛ تا فتح قسطنطنیه نزدیک به 90 سال پایتخت ماند.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["مراد یکم بر تخت نشست", "f8d48a26"], "d": ["مراد یکم (خداوندگار) که با مرگ اورخان غازی بر تخت نشست، در سلطنت 27 ساله‌اش دولت را از امارت مرزی به اسکلت امپراتوری رساند. با نظام پنجیک بنیاد اوجاق ینی‌چری نهاده شد، نظام تیمار گسترش یافت، بیلربیگی روم‌ایلی برپا شد و نهاد وزارت نیرو گرفت. فتوحات بالکان در دورهٔ او به سیاست نظام‌مند دولت بدل شد.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["نبرد نخست کوزوو — شهادت مراد یکم", "10b8ddc9"], "d": ["اتحاد بالکان به رهبری کنز لازار در دشت کوزوو قطعاً شکست خورد؛ صربستان زیر سلطهٔ عالی عثمانی درآمد. مراد یکم که میدان نبرد را می‌گشت به دست میلوش اوبیلیچ، اشراف‌زادهٔ صرب، با خنجر شهید شد — تنها سلطان عثمانی است که در میدان نبرد مرد. در اردوگاه یلدیرم بایزید به جای او نشانده شد؛ برادرش یعقوب چلبی خفه شد و این از نمونه‌های شناخته‌شدهٔ آغازین برادرکشی است.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["پیروزی نیکوپولیس", "75716e96"], "d": ["ارتش بزرگ صلیبی که به فراخوان سیگیسموند، پادشاه مجارستان، گرد آمده و شوالیه‌های فرانسوی-بورگونی نیز در آن شرکت داشتند، در برابر نیکوپولیس در کرانهٔ دانوب به دست یلدیرم بایزید سخت شکست خورد. پیروزی سلطهٔ عثمانی بر بلغارستان را قطعی کرد؛ در اروپا یک نسل جنگ صلیبی بزرگی سازمان نیافت.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["نبرد آنکارا — آغاز دورهٔ فترت", "b4a99d96"], "d": ["در شکست سنگینی که در دشت چوبوق برابر ارتش تیمور رخ داد، یلدیرم بایزید اسیر شد و چند ماه بعد در اسارت مرد. تیمور امارت‌های آناتولی را دوباره زنده کرد؛ سرزمین‌های عثمانی میان پسران بایزید پاره‌پاره شد و کشمکش 11 ساله بر سر تخت (دورهٔ فترت) آغاز گردید. این دوره که سخت‌ترین بحران دولت از آغاز تأسیس بود، اهمیت ساختار متمرکز را در حافظهٔ عثمانی حک کرد. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: داتچا، مرمریس، فتحیه (ماکری)، سؤکه، کوتاهیه، افیون، ایسپارتا، مانیسا، آیدین، دنیزلی، موغلا، آنتالیا، قونیه، قرمان، قیصریه، قسطمونی، بارتین، صافرانبولو، سامسون، سیواس، ملطیه، بی‌شهر، سیوری‌حصار، کیرشهیر، چوروم، چانقری، ینی‌شهر (بورسا)، اینه‌گول، قلعهٔ آیدوس، گیوه، کوپرو‌حصار (ینی‌شهر)، مارماراجیک، آق‌حصار (پاموکووا)، مکجه، کستل، اولوباد، هارمانکایا، آق‌یازی، جزیرهٔ ایمرالی، کاندیرا، مودانیا، یالووا، قره‌مورسل، آرموتلو، گملیک (کیوس)، سوگوت، بیلجیک، اسکی‌شهر، بورسا، ایزنیک، ایزمیت، بالیک‌اسیر، چاناق‌قلعه، پرگامون، آماسیه، توقات، چورلو، لوله‌بورگاز، مالکارا، کشان، ایپسالا، قلعهٔ کیلیدبحر، چیرمن، استارا زاگورا، تاتارپازارجیک، ایختیمان، کوستندیل، پتریچ، نوروکوپ (گوتسه دلچف)، درامه، گلیبولو، چیمپه، ادرنه، دیدیموتیخون، قرق‌کلیسه، تکیرداغ، فیلیبه، صوفیه، نیش، ویدین، ترنوو، وارنا، شومن، سیلیستره، نیکوپولیس، روسچوک، سالونیک، سرس، کاوالا، اسکوپیه، مناستیر، اوهرید، ینی‌شهر (لاریسا)، تریکالا، ایزدین (لامیا)، پلونه، گومولجینه، بیگا، دومانیچ، قلعه‌حصار (کولاجاحصار)، قراجه‌حصار، یارحصار، دیمبوس، کیته (Kete)، لفکه (عثمان‌ایلی)، لبلبی‌جی‌حصار، قره‌چپوش، قره‌تکین، آبسو (هیپسو)، آدرانوس (اورخانلی)، پلکانون (اسکی‌حصار)، گبزه، هرکه، سامانديرا، کرماستی (مصطفی‌کمال‌پاشا)، میهالیچ (قره‌جابی)، کوستنجه، گولیازی (آپولونیا).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["چلبی محمد یکپارچگی را بازگرداند", "03413dfd"], "d": ["محمد یکم که در واپسین حساب‌رسی میان برادران، موسی چلبی را در چاموردو شکست داد، سرزمین‌های کشور را زیر یک اداره یکپارچه کرد؛ از این رو «بنیان‌گذار دوم دولت» شمرده می‌شود. در سلطنت او ساختار فرسودهٔ دولت ترمیم شد، روابط با بیگ‌نشین‌های آناتولی متعادل گشت و در روم‌ایلی سیاست صلح محتاطانه‌ای پی گرفته شد. سایر سکونتگاه‌هایی که در همین تاریخ بر نقشه از دورهٔ فترت به ادارهٔ عثمانی بازگشتند: آبسو (هیپسو)، آدرانوس (اورخانلی)، آق‌حصار (پاموکووا).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["شورش شیخ بدرالدین", "e0a072ca"], "d": ["جنبش دینی-اجتماعی که پیرامون شیخ بدرالدین، فقیه و صوفی بزرگ که در دورهٔ فترت قاضی‌عسکر بوده بود شکل گرفت، همزمان با شورش‌های بورکلوجه مصطفی در قره‌بورون و تورلاق کمال در مانیسا درگرفت. شورش‌ها خونین سرکوب شد؛ بدرالدین در دلی‌اورمان دستگیر و در سرس اعدام شد. رویداد به‌عنوان نخستین شورش بزرگ اجتماعی-مهدوی تاریخ عثمانی در ادبیات و تاریخ‌نگاری اثری ژرف نهاد.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["پیروزی وارنا", "f739eedc"], "d": ["ارتش صلیبی مجار-لهستانی که با شکستن معاهدهٔ سگدین به جنوب آمده بود، به دست مراد دوم که از تخت کناره گرفته و به رأس ارتش بازگشته بود در وارنا نابود شد؛ شاه جوان لادیسلاو سوم در میدان نبرد مرد. پیروزی واپسین فرصت دخالت بزرگ خارجی برای برچیدن حضور عثمانی در بالکان را از میان برد و راه فتح قسطنطنیه را تضمین کرد.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["نبرد دوم کوزوو", "ebe0b662"], "d": ["ارتش یانوش هونیادی که می‌خواست انتقام وارنا را بگیرد، در نبردی سخت و سه‌روزه به دست مراد دوم قطعاً شکست خورد. این واپسین نبرد میدانی بزرگی است که صلیبیان در بالکان علیه عثمانی آغاز کردند؛ با این پیروزی سلطهٔ عثمانی در جنوب دانوب به‌گونه‌ای بازگشت‌ناپذیر جا افتاد.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["فتح قسطنطنیه", "583d5e3e"], "d": ["پس از محاصره‌ای پنجاه‌وچهارروزه (6 آوریل–29 مه 1453)، صبح 29 مه ارتش عثمانی از دیوارها گذشت و وارد شهر شد؛ واپسین امپراتور، کنستانتینوس یازدهم، در درگیری‌ها کشته شد و امپراتوری روم شرقی با 1100 سال تاریخ به تاریخ پیوست. سلطان جوان لقب «فاتح» گرفت، شهر را پایتخت کرد و ایاصوفیه را به مسجد بدل ساخت؛ شهر در مدتی کوتاه با اسکان و آبادانی زنده شد. بر پایهٔ TDV سیلیوری و ویزه تنها در 1453 قطعاً فتح شدند؛ بر پایهٔ مادهٔ لمنوس در TDV جزیره بی‌درنگ پس از فتح به اداره عثمانی درآمد و به شرط خراج به خاندان گاتیلوزیو واگذار شد. در اطلس سیلیوری، ویزه و لمنوس از این روز از بیزانس به عثمانی ثبت شده‌اند (لمنوس خراج‌گزار). ریختن توپ‌های عظیم، گذراندن کشتی‌ها از خشکی و نظام محاصره در برابر دیوارها اوج مهندسی نظامی زمانه شمرده می‌شود. فتح در تاریخ‌نگاری اروپایی از تاریخ‌های نمادین پایان سده‌های میانه به شمار می‌رود.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["فتح طرابزون", "15f52403"], "d": ["در پایان لشکرکشی دشوار دریای سیاه که فاتح همزمان با ارتش و ناوگان پیش برد، امپراتوری رومی طرابزون تسلیم شد؛ با برچیده شدن این واپسین بازماندهٔ جهان بیزانس در آناتولی، ساحل جنوبی دریای سیاه یکسره در سلطهٔ عثمانی درآمد. پایان دادن به خاندان کومننوس ادعای فاتح را به «فرمانروای دو دریا و دو خشکی» استوار کرد. سایر آبادی‌هایی که در همین تاریخ پیوستند: گیرسون، ریزه.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["فتح قطعی سیلیفکه — شکسته شدن آخرین مقاومت قرمان‌اوغلوها", "d988bee4"], "d": ["قلعهٔ سیلیفکه در 1472 یک‌بار به گدیک احمد پاشا تسلیم شده بود، اما در همان سال قرمان‌اوغلو قاسم بیگ با یاری ناوگان صلیبی در مدیترانه قلعه را بازپس گرفته بود. پس از پیروزی اوتلوق‌بلی، فاتح پسرش و گدیک احمد پاشا را مأمور گرفتن قطعی منطقه کرد؛ با یاری توپچیان کهن عثمانی انبار باروت آتش زده شد و قلعه به‌سرعت سقوط کرد. بدین‌سان واپسین مقاومت قرمان‌اوغلوها در کوه‌های تاشلی-ایچل شکسته شد؛ برچیدن امارت در 1474 کامل خواهد شد.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["نبرد اوتلوق‌بلی", "42c7194e"], "d": ["اوزون حسن، فرمانروای آق‌قویونلو که در شرق قدرتی بزرگ شده و با ونیز متحد گشته بود، در اوتلوق‌بلی برابر ارتش مجهز به سلاح آتشین فاتح سخت شکست خورد. پیروزی برتری عثمانی را در آناتولی قطعی کرد؛ همچنین گواهی آغازین بود بر برتری ارتش مرکزی که توپ و تفنگ به کار می‌برد بر ارتش کلاسیک. بر پایهٔ مادهٔ گوموش‌خانه در TDV شهر از 1467 زیر سلطهٔ آق‌قویونلو بود؛ این سلطه با شکست اوتلوق‌بلی پایان یافت و گوموش‌خانه قطعاً به سلطهٔ عثمانی گذشت.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["درآمدن کریمه به حمایت عثمانی", "44e3f7c8"], "d": ["ناوگان به فرماندهی گدیک احمد پاشا شهرهای ساحل جنوبی کریمه را، در رأس آنها کفه را که در دست جنوا بود، فتح کرد؛ این سواحل مستقیماً سنجق عثمانی شد. خانات کریمه با منگلی گیرای به دولت وابسته‌ای ممتاز بدل شد که سلطهٔ عالی عثمانی را می‌شناخت و سه سده سنگ بنای سیاست شمالی بود؛ دریای سیاه اکنون عملاً به دریای داخلی عثمانی بدل شد. سایر آبادی‌هایی که در همین تاریخ پیوستند: باغچه‌سرای، کرچ، آزاق.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["درگذشت فاتح — رویداد جم سلطان", "190ecf01"], "d": ["با مرگ ناگهانی فاتح در راه لشکرکشی، بایزید دوم بر تخت نشست؛ برادرش جم سلطان با ادعای سلطنت در بورسا به نام خود خطبه خواند و سکه زد. چون شکست خورد نخست به ممالیک و سپس به شوالیه‌های رودس پناه برد؛ جم که در دست شوالیه‌ها و پاپ به مهرهٔ معامله در دیپلماسی اروپا بدل شد، در 1495 در ناپل مرد. این رویداد سیاست خارجی عثمانی را پانزده سال به رفتار محتاطانه وادار کرد.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["پیروزی چالدران", "fea64ebb"], "d": ["یاوز سلطان سلیم که می‌خواست تهدید تبلیغات صفوی در آناتولی را ریشه‌ای حل کند، ارتش شاه اسماعیل را در دشت چالدران با برتری توپ و تفنگ سخت شکست داد. به تبریز وارد شدند؛ آناتولی شرقی و جنوب‌شرقی و خط موصل-دیاربکر به اداره عثمانی پیوست. پیوستن بیگ‌های کرد به عثمانی با کوشش ادریس بدلیسی، چارچوب مرز شرقی را که سده‌ها ادامه می‌یافت بنا کرد.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["پیروزی مرج دابق", "07d254d3"], "d": ["ارتش ممالیک در مرج دابق در شمال حلب در چند ساعت پراکنده شد؛ سلطان کهنسال قانصوه غوری در جریان نبرد مرد. با این پیروزی که دروازه‌های حلب و دمشق را یکسره گشود، سوریه، لبنان و فلسطین به اداره عثمانی درآمد؛ راه لشکرکشی مصر که پایان دولت ممالیک را می‌آورد گشوده شد.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["ریدانیه — فتح مصر و خلافت", "caf378d6"], "d": ["ارتش عثمانی که بیابان سینا را شتابان پیمود، خط دفاعی طومان‌بای را در ریدانیه شکافت و وارد قاهره شد؛ طومان‌بای که مقاومت می‌کرد دستگیر و اعدام شد و دولت ممالیک به تاریخ پیوست. مصر، حجاز و شهرهای مقدس زیر اداره عثمانی درآمد؛ خلیفهٔ عباسی و امانات مقدس به استانبول برده شد. با گذشتن خلافت به خاندان عثمانی، سلاطین ادعای رهبری جهان اسلام را بر عهده گرفتند؛ کنترل راه ادویه نیز درآمد بزرگی برای امپراتوری فراهم آورد. سایر آبادی‌هایی که در همین تاریخ پیوستند: عکا، معان، صیدا، کرک.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["سلطان سلیمان قانونی بر تخت نشست", "f6512269"], "d": ["سلطنت 46 ساله سلیمان یکم که با مرگ یاوز به‌عنوان تنها پسر بر تخت نشست، اوج سیاسی، نظامی، حقوقی و فرهنگی امپراتوری شمرده می‌شود. قانون‌نامه‌هایی که حقوق عرفی را نظام‌مند کرد لقب «قانونی» را برایش آورد؛ در غرب «باشکوه» (Magnificent) نامیده شد. آثار معمار سینان، عصر زرین ادبیات دیوانی و برتری ناوگان در مدیترانه نمادهای این دوره‌اند.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["فتح بلگراد", "59ef5cec"], "d": ["بلگراد که فاتح در 1456 نتوانسته بود بگیرد و «قفل اروپای مرکزی» شمرده می‌شد، در نخستین لشکرکشی قانونی با محاصره در تلاقی دانوب-ساوا سقوط کرد. خط دفاعی جنوبی مجارستان فروریخته بود؛ دروازهٔ عملیات اروپای مرکزی که پنج سال بعد به موهاچ و بیست سال بعد به الحاق بودین می‌رسید با این فتح گشوده شد.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["فتح رودس", "807bbb1e"], "d": ["رودس، پایگاه شوالیه‌های سن ژان که راه‌های دریایی مدیترانهٔ شرقی و مسیر حج را تهدید می‌کرد، پس از محاصره‌ای خونین و ماه‌ها با معاهده تسلیم شد؛ به شوالیه‌ها اجازه داده شد آزادانه از جزیره بروند (بعدها در مالت جا گرفتند). امنیت سواحل آناتولی تأمین شد و خط دریایی استانبول-مصر یکپارچه زیر کنترل عثمانی درآمد.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["نبرد میدانی موهاچ", "f3418b0d"], "d": ["ارتش مجار در دشت موهاچ در حدود دو ساعت با آتش توپ و برتری مانور نابود شد؛ شاه لایوش دوم هنگام گریز در مرداب مرد. موهاچ که از سریع‌ترین نبردهای بزرگ میدانی تاریخ عثمانی به دست آمد، پادشاهی مستقل مجارستان را عملاً پایان داد و عصر رقابت عثمانی-هابسبورگ را در اروپای مرکزی گشود.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["محاصرهٔ نخست وین", "dc49ea4f"], "d": ["در لشکرکشی‌ای که در برابر دست‌اندازی هابسبورگ‌ها بر تخت مجارستان سازمان یافت، ارتش عثمانی وین را محاصره کرد؛ به سبب بر جا ماندن توپ‌های سنگین در راه، سرمای زودرس و دشواری آذوقه، محاصره پس از سه هفته برداشته شد. شهر هرچند گرفته نشد، نفوذ عثمانی بر مجارستان نگاه داشته شد؛ پیرامون وین حد دسترسی تدارکاتی امپراتوری در اروپای مرکزی را نشان داد.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["فتح بغداد — لشکرکشی عراقین", "897092c3"], "d": ["در لشکرکشی بر «دو عراق» (عراق عرب و عراق عجم) نخست به تبریز و سپس بی‌جنگ به بغداد وارد شدند؛ گرفتن پایتخت پیشین عباسیان به فرمانروای عثمانی در جهان اسلام اعتبار بزرگی بخشید. مقبرهٔ امام اعظم ابوحنیفه احیا شد؛ با پیوستن بغداد و بصره سرزمین‌های عثمانی به خلیج فارس رسید. سایر آبادی‌هایی که در همین تاریخ پیوستند: کرکوک، کربلا.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["پیروزی دریایی پروزه", "30dc0f97"], "d": ["ناوگان صلیبی که به پیشگامی پاپ تشکیل شده بود، با وجود برتری عددی با تاکتیک بارباروس که از باد و ساحل استادانه بهره می‌برد در برابر پروزه پراکنده شد؛ آندرئا دوریا میدان نبرد را رها کرد. این پیروزی برتری بی‌چون‌وچرای دریایی عثمانی را که نزدیک 33 سال در مدیترانه ادامه می‌یافت برقرار کرد؛ در سنت دریانوردی ترک تاریخ نمادین روز ناوگان است. سایر آبادی‌هایی که در همین تاریخ پیوستند: عدن، شهر بندر (تیغینا).", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["الحاق بودین — مجارستان ایالت عثمانی", "db53b244"], "d": ["قانونی که با محاصرهٔ بودین به دست هابسبورگ‌ها به لشکرکشی رفت، پس از نجات شهر مجارستان مرکزی را مستقیماً به اداره عثمانی درآورد و بیلربیگی بودین را برپا کرد؛ ترانسیلوانیا به شاهزادگی خودمختار وابسته به عثمانی بدل شد. این نظام سه‌پاره مجارستان حدود 150 سال ادامه یافت و اسکلت ماندگار اداره عثمانی در اروپای مرکزی را ساخت.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["معاهدهٔ آماسیه", "a5afe0d1"], "d": ["نخستین معاهدهٔ صلح رسمی است که جنگ‌های سال‌ها عثمانی-صفوی را پایان داد. بغداد و عراق در دست عثمانی ماند، مرز آناتولی شرقی برای نخستین بار متقابلاً شناخته شد؛ صفویان تعهد کردند تبلیغات شیعی در سرزمین عثمانی را متوقف کنند و عثمانیان نیز امنیت گذر حاجیان ایرانی را بر عهده گرفتند. معاهده نخستین نمونهٔ چارچوب حقوقی روابط دو دولت شد.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["زیگتوار — درگذشت قانونی", "e2917ed2"], "d": ["قانونی هفتادودوساله در سیزدهمین لشکرکشی چند ساعت پیش از سقوط قلعهٔ زیگتوار که آن را محاصره کرده بود در خرگاهش درگذشت؛ صوقوللو محمد پاشا برای پراکنده نشدن ارتش مرگ را هفته‌ها پنهان نگاه داشت. قلعه گرفته شد، اما دولت درازترین و پرشکوه‌ترین سلطان خود را از دست داده بود؛ پسرش سلیم دوم بر تخت نشست و وزن وزیران بزرگ در اداره دولت رو به فزونی نهاد.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["فتح قبرس", "e364a2b3"], "d": ["در 1570 به قبرس زیر حکومت ونیز نیرو پیاده شد؛ لفکوشه به‌سرعت سقوط کرد، ماگوسا اما تنها پس از محاصرهٔ یازده‌ماهه در اوت 1571 تسلیم شد. جزیره که از نظر امنیت راه‌های تجارت و حج در مدیترانهٔ شرقی حیاتی بود، به‌عنوان یک بیلربیگی سازمان یافت و از آناتولی جمعیت اسکان داده شد؛ فتح دلیل اتحاد بزرگ صلیبی نیز شد که به اینه‌بختی می‌رسید.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["شکست اینه‌بختی (لپانتو)", "6a1d44a9"], "d": ["ناوگان صلیبی که پس از فتح قبرس متحد شده بود، ناوگان عثمانی را در خلیج اینه‌بختی گرفت و بخش بزرگ آن را نابود کرد؛ قپودان دریا مؤذن‌زاده علی پاشا شهید شد، تنها ناوگان اولوچ علی نجات یافت. پس از فاجعه، صدراعظم صوقوللو محمد پاشا اولوچ علی پاشا را به قپودان‌دریایی رساند و مأمور گردآوری ناوگان پراکنده کرد و در همهٔ کارخانه‌های کشتی‌سازی از استانبول تا آلانیا ساخت ناوگانی نو را آغاز کرد؛ اما برتری مطلق در مدیترانه از نظر روانی لرزیده بود.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["نبرد میدانی هاچوا", "da308ec5"], "d": ["در بزرگ‌ترین نبرد میدانی جنگ طولانی (1593–1606)، ارتشی که محمد سوم شخصاً در رأس آن بود، در لحظه‌ای که نزدیک به پراکنده شدن رسیده بود با تلقین خواجه سعدالدین افندی بازسازمان یافت و ارتش هابسبورگ را شکست داد. واپسین نبرد میدانی بزرگ کلاسیک عثمانیان شمرده می‌شود؛ اما اینکه سیر کلی جنگ را دگرگون نکرد، نشانهٔ فرسایش در نظام نظامی نیز شمرده شد.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["معاهدهٔ زیتواتوروک", "39c01142"], "d": ["با معاهده‌ای که جنگ فرسایشی سیزده‌ساله را پایان داد، فرمانروای هابسبورگ برای نخستین بار با عنوان «امپراتور روم» هم‌تراز سلطان شمرده شد و خراج سالانه برداشته شد. زیان سرزمینی تقریباً ناچیز بود؛ اما این دگرگونی در زبان دیپلماتیک، نماد پایان ادعای برتری مطلق عثمانی در برابر اروپا خوانده می‌شود.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["معاهدهٔ قصر شیرین", "c1acf3af"], "d": ["معاهده‌ای که پس از بازپس‌گیری بغداد به دست مراد چهارم (1638) امضا شد جنگ‌های بیش از صدسالهٔ عثمانی-صفوی را پایان داد. بغداد و عراق قطعاً در دست عثمانی ماند، ایروان به صفویان واگذار شد؛ خطی که ترسیم شد با تغییرات اندک بنیاد مرز امروزی ترکیه-ایران شد و از ماندگارترین مرزهای جهان شمرده می‌شود. معاهده بدره، جسان، مندلی، درتنگ و درنه را به عثمانی واگذاشت؛ قلعهٔ زنجیر در مرز ویران می‌شد، روستاهای غرب آن به عثمانی و روستاهای شرق آن به ایران می‌ماند. پیرامون قلعهٔ زالم نزدیک شهرزور و قزل‌جه‌قلعه در دست عثمانی، اورامان و مهربان در دست ایران ماند؛ قلعه‌های کوتور، ماکو و مغازبرد از هر دو سو ویران می‌شد.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["تکمیل فتح کرت", "e0d85604"], "d": ["محاصرهٔ کاندیه که پردهٔ آخر جنگ کرت از 1645 بود، با عملیات مصمم سه‌ساله فاضل احمد پاشا به نتیجه رسید؛ فرمانده ونیزی موروزینی شهر را با معاهده تسلیم کرد. کشمکشی که نزدیک ربع سده طول کشید به‌عنوان درازترین محاصرهٔ تاریخ عثمانی ثبت شد؛ واپسین قلعهٔ بزرگ لاتینی مدیترانهٔ شرقی نیز زیر اداره عثمانی درآمد. سه قلعهٔ صخره‌ای کوچک ساحل شمالی جزیره — سودا، اسپینالونگا و گرامبوسا — هنوز در دست ونیز ماندند؛ چون بر جزیره‌های جداگانه بنا شده‌اند در نقشه جدا از بقیهٔ کرت نشان داده نمی‌شوند.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["معاهدهٔ بوچاچ — گسترده‌ترین مرزها", "b17b6e5a"], "d": ["با معاهدهٔ بوچاچ که پس از فتح کامنیتس در لشکرکشی لهستان امضا شد، پودولیا به عثمانی پیوست و بخشی از اوکراین زیر حمایت درآمد. امپراتوری بدین‌سان به گسترده‌ترین مرزهای خود در اروپا رسید؛ این نقطه اوج عصر گسترش و همچنین واپسین حلقهٔ آن شمرده می‌شود.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["شکست محاصرهٔ دوم وین", "7d889252"], "d": ["محاصرهٔ دو ماههٔ وین به دست مرزیفونلو قره مصطفی پاشا با ضربهٔ ناگهانی یان سوبیسکی، پادشاه لهستان، که از تپه‌های کالنبرگ فرود آمد به شکست بدل شد؛ ارتش بار و بنه را رها کرد و عقب نشست، مرزیفونلو در بلگراد اعدام شد. با اتحاد مقدسی که پس از پیروزی برپا شد جنگ 16 سال ادامه یافت؛ این شکست لحظهٔ آغاز عقب‌نشینی بزرگ در تاریخ عثمانی نشان داده می‌شود.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["فتح قلعهٔ گرامبوسا — یکی از قلعه‌های صخره‌ای کرت که در دست ونیز مانده بود", "3ddf9eeb"], "d": ["هرچند با تسلیم کاندیه در 1669 فتح کرت تا حد زیادی تمام‌شده شمرده می‌شد، قلعه-جزیرهٔ صخره‌ای گرامبوسا در نوک شمال‌غربی جزیره بیست‌وسه سال دیگر در دست ونیز ماند. با گرفته شدنش در 1692 یکی از سه بازماندهٔ ونیزی در کرت پاک شد؛ سودا و اسپینالونگا اما منتظر لشکرکشی موره در 1715 می‌ماندند.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["معاهدهٔ کارلوویتس — نخستین زیان بزرگ سرزمینی", "8f7e2546"], "d": ["با کارلوویتس که جنگ‌های شانزده‌سالهٔ اتحاد مقدس را پایان داد، مجارستان و ترانسیلوانیا به اتریش، پودولیا به لهستان، موره و سواحل دالماسی به ونیز واگذار شد. در تاریخ عثمانی برای نخستین بار به این مقیاس سرزمین بر سر میز و برای همیشه از دست می‌رفت؛ معاهده سند آغاز عصر نوینی شمرده می‌شود که امپراتوری در برابر اروپا به دفاع گذشت و نقطهٔ عطف تاریخ دیپلماسی عثمانی نیز هست. آبادی‌هایی که در همان روز در اطلس دست‌به‌دست شدند: کوستایینیتسا و یاسنوواتس (از عثمانی به هابسبورگ؛ متن معاهده Castanoviz را در دست امپراتور می‌گذارد، روز تسلیم یاسنوواتس در منبع نیست، روز معاهده نوشته شد) و پروزه (از ونیز به عثمانی؛ TDV karlofca: بر پایهٔ حکم امضاشده در 24 رجب 1110 / 26 ژانویه 1699 جاهای اشغال‌شدهٔ ونیز در شمال خلیج اینه‌بختی بازگردانده شد). اطلس همچنین کوستاینیچه (Kostajnica) و یاسنوواچ را به سوی هابسبورگ، اومان و وینیتسا در اوکراین راست‌کرانه را از عثمانی به لهستان (TDV merzifonlu-kara-mustafa-pasa؛ IEU Vinnytsia: 1672-99 سلطهٔ ترک) و نادین در دالماسی را به ونیز می‌نویسد (روز تسلیم ویژهٔ آبادی در منبع نیست، روز معاهده نوشته شد؛ حدود دوره‌ای نادین با منبع تأیید نشد — تقریب اعلام‌شده). وونیتسا در شمال خلیج اینه‌بختی نیز از ونیز به عثمانی بازگردانده می‌شود (TDV karlofca)؛ در دالماسی وارانا (Urana) از جاهایی است که در دست ونیز می‌ماند (حد دوره‌ای تأیید نشد — اعلام‌شده).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["پیروزی پروت", "2583572f"], "d": ["در جنگی که بر سر مسئلهٔ شاه سوئد که پس از شکست پولتاوا به عثمانی پناه برده بود درگرفت، ارتش تزار پتر یکم در کرانهٔ پروت محاصره شد و ناگزیر تسلیم گشت. با معاهدهٔ امضاشده آزاق بازپس گرفته شد؛ اینکه ارتش نابود نشد و تزار آزاد گذاشته شد، تصمیمی است که از آن روز تاکنون محل مناقشه در تاریخ مانده است.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["فتح قلعه‌های سودا و اسپینالونگا — پاک شدن واپسین اثر ونیز در کرت", "7261f7ba"], "d": ["بیست‌وسه سال پس از سقوط گرامبوسا در 1692، با شاخه‌ای فرعی از لشکرکشی موره، سودا و اسپینالونگا، دو تکیه‌گاه آخر ونیز در کرت، نیز فتح شدند. بدین‌سان فتح کرت که از 1645 آغاز شده بود پس از چهل‌وشش سال تا آخرین سانتی‌متر جزیره تکمیل شد.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["شورش پاترونا خلیل", "100941a4"], "d": ["ناکامی در جبههٔ ایران، مالیات‌ها و خشم از تجمل پیرامون کاخ، به شورش بزرگی به رهبری پاترونا خلیل، دلاک حمام، بدل شد. صدراعظم ابراهیم پاشا کشته شد، احمد سوم از تخت فرود آمد و دورهٔ لاله پایان یافت؛ اینکه شورشیان ماه‌ها بر شهر فرمان راندند، شکنندگی اقتدار مرکزی را به‌گونه‌ای چشمگیر نشان داد.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["معاهدهٔ بلگراد — بازپس‌گیری بلگراد، سمندره و شمال صربستان", "ba7f8e46"], "d": ["در پایان جنگی که در دو جبهه علیه اتریش و روسیه پیش برده شد (1736–1739) بلگراد و شمال صربستان بازپس گرفته شد؛ روسیه پذیرفت آزاق را خلع سلاح کند و در دریای سیاه ناوگان نگه ندارد. معاهده که واپسین موفقیت بزرگ دیپلماسی و ارتش عثمانی در سدهٔ 18 شمرده می‌شود، به امپراتوری دورهٔ صلح ربع‌سده‌ای بخشید. آبادی‌های دیگری که در همان روز در اطلس از اتریش به عثمانی بازگشتند: هیسارجیک (گروتسکا) (بنا بر وابستگی به سرنوشت مرکز اصلی، بلگراد؛ TDV belgrad)، کرایووا، ریمنیکو ولچا و تورنو سورین (بازگشت افلاق کوچک به عثمانی، به دست‌نشاندگی افلاق). بوسنه برود (Bosanski Brod) و بوسنه دوبیتسا (Bosanska Dubica) در نوار ساوا اما در اطلس در 28 سپتامبر 1739 به عثمانی بازمی‌گردند (TDV bosna-hersek؛ TDV mahmud-i--osmanli: 28 سپتامبر 1739). تیرگو ژیو در افلاق کوچک نیز در همان روز به عثمانی بازمی‌گردد.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["یورش چشمه", "840b30bd"], "d": ["ناوگان روس که با پشتیبانی انگلیسی‌ها به مدیترانه آمده بود، ناوگان عثمانی را در بندر چشمه که به آن پناه برده بود با کشتی‌های آتشین زد و تقریباً یکسره سوزاند. روسیه برای نخستین بار در مدیترانه به‌عنوان قدرت بزرگ دریایی پدیدار شد؛ این فاجعه از ضربه‌هایی بود که سرنوشت جنگ منتهی به کوچک قینارجه 1774 را تعیین کرد و نیاز به اصلاح ریشه‌ای ناوگان را آشکار ساخت.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["معاهدهٔ کوچک قینارجه", "2776dcdb"], "d": ["با کوچک قینارجه که جنگ 1768–1774 را پایان داد و از سنگین‌ترین معاهدات تاریخ عثمانی شمرده می‌شود، به خانات کریمه «استقلال» داده شد — عملاً حوزهٔ نفوذ روس پدید آمد. روسیه در ساحل دریای سیاه جا گرفت، حق گذر کشتی‌های تجاری از تنگه‌ها و سفارت دائمی در استانبول را به دست آورد؛ قید مبهم حمایت از رعایای ارتدکس دروازهٔ بهانه‌های دخالت سدهٔ بعد را گشود. برای نخستین بار سرزمینی با مردم مسلمان از سلطهٔ عثمانی بیرون برده می‌شد.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["الحاق کریمه به روسیه", "bdf6faa8"], "d": ["کریمهٔ «مستقل» که کوچک قینارجه پدید آورده بود، با بهانه کردن آشفتگی‌های دورهٔ آخرین خان شاهین گیرای، با بیانیهٔ کاترین دوم به روسیه الحاق شد. شراکت سه‌صدسالهٔ عثمانی-کریمه پایان یافت؛ از دست رفتن استپ‌های شمالی عمق دفاعی استانبول را از میان برد و نخستین موج بزرگ کوچ ده‌ها هزار تاتار کریمه به سرزمین‌های عثمانی را آغاز کرد. در این روز شبه‌جزیرهٔ کریمه (آلوشتا، کفه، سوداک، یالتا، بالاکلاوا، اینکرمان، مانگوپ، آرابات) به روسیه پیوست؛ تامان و کوبان نیز در همان الحاق به روسیه گذشت (TDV Kırım: 8 آوریل 1783 ژولین = 19 آوریل گرگوری).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["سلیم سوم و نظام جدید", "d53aec21"], "d": ["سلیم سوم که در میانهٔ جنگ بر تخت نشست، با دیدن اینکه شکست‌ها ساختاری‌اند، برنامهٔ جامع اصلاحاتی به نام «نظام جدید» را آغاز کرد: ارتش نو با آموزش به شیوهٔ اروپایی، خزانهٔ جداگانه‌ای که آن را تأمین مالی می‌کرد (ایراد جدید)، تقویت مهندس‌خانه‌ها و نخستین سفارت‌های دائمی در پایتخت‌های اروپا. برنامه آغاز سنت اصلاحات نوین ترک شمرده می‌شود؛ اما با مقاومت اوجاق‌ها و اعیان در 1807 برافتاد.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["برچیده شدن شوالیه‌های مالت — ایستگاه راه ناوگان فرانسه", "d62f901d"], "d": ["ناوگان فرانسهٔ رهسپار مصر به مالت که بر سر راهش بود سر زد؛ شوالیه‌های سن ژان (مالت) بی‌مقاومت زیاد جزیره را تسلیم کردند. واپسین دژ فرقهٔ شوالیه‌هایی که در 1522 از رودس رانده شده و در اینجا جا گرفته بودند، بدین‌سان پایان یافت. مالت دو سال بعد به دست انگلستان می‌افتاد و ناپلئون از جزیره مستقیماً به اسکندریه روی می‌آورد.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["اشغال مصر به دست ناپلئون", "93fede5f"], "d": ["ارتش ژنرال بناپارت در اسکندریه پیاده شد و مصر را اشغال کرد؛ این لشکرکشی که راه هند انگلستان را هدف می‌گرفت، نخستین حملهٔ مستقیم یک قدرت اروپایی به سرزمین‌های مرکزی عثمانی بود. یورش نلسون به ابوقیر و دفاع جزار احمد پاشا از عکا پیشروی فرانسه را شکست؛ اشغال در 1801 پایان یافت، اما در خلأیی که برجا ماند، ظهور محمد علی پاشای کاوالایی و عصر «مسئلهٔ شرق» آغاز شد.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["سند اتفاق", "cce49ef5"], "d": ["سندی که به پیشگامی علمدار مصطفی پاشا، از اعیان روسچوک که محمود دوم را بر تخت نشانده بود، میان کاخ و خاندان‌های نیرومند اعیان ولایات امضا شد؛ اعیان به سلطان وفاداری و پشتیبانی نظامی متعهد شدند و دولت نیز هستی و حقوق آنان را شناخت. چون نخستین نمونهٔ محدود شدن اقتدار سلطان با سند در تاریخ عثمانی است، از سوی برخی مورخان آغاز دور سنت قانون اساسی شمرده می‌شود؛ عملاً در چند ماه بی‌اثر شد.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["آغاز شورش یونان", "a7293715"], "d": ["شورشی که سازمان فیلیکی اتریا تدارک دیده بود نخست در افلاق و سپس با نیروی اصلی در موره درگرفت؛ دولتی که با ماجرای تپه‌دلنلی علی پاشا مشغول بود در نخستین دخالت تأخیر کرد. شورش به برکت همدلی شدید افکار عمومی اروپا با یونان (فیلهلنیسم) در مدتی کوتاه به آرمانی بین‌المللی بدل شد؛ فتیلهٔ نخستین جنبش استقلال موفق عصر ناسیونالیسم در سرزمین‌های عثمانی این‌گونه آتش گرفت. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: آتن، پاتراس، ایستفه (تب)، لیوادیا، الفسیس (آتیکا)، میسولونگی.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["نخستین شورش مسلحانه در موره", "77e6250f"], "d": ["پس از گذشتن از پروت شورش به موره سرایت کرد: اقدام مسلحانهٔ آغازشده در کالاوریتا (21 مارس ژولین) را جنبش‌های پاتراس، کالاماتا و مانی دنبال کرد؛ موره در مدتی کوتاه به شورش عمومی بدل شد و اداره عثمانی بخش بزرگ شبه‌جزیره را از دست داد. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: آتن، پاتراس، ایستفه (تب)، لیوادیا، الفسیس (آتیکا)، میسولونگی.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["واقعهٔ خیریه — برچیده شدن اوجاق ینی‌چری", "08c9372a"], "d": ["ینی‌چری‌هایی که در برابر آموزش‌های اوجاق نوبنیاد اشکنجی دیگ واژگون کردند، با آتش توپ واحدهای وفاداری که محمود دوم از پیش آماده کرده بود در سربازخانه‌هایشان در اتمیدانی نابود شدند؛ اوجاق با همهٔ شعبه‌ها و تکیه‌های بکتاشی وابسته لغو شد. این عملیات که با نام «رویداد خیر» به تاریخ رفت، با برچیدن نهادی چهارصدساله راه ارتش عساکر منصورهٔ محمدیه و همهٔ اصلاحات متمرکزسازی پس از آن را گشود.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["یورش ناوارین", "ee579e7f"], "d": ["ناوگان عثمانی-مصر که شورش یونان را سرکوب می‌کرد، در ناوارین به دست ناوگان متحد انگلیس-فرانسه-روس که بی‌اعلام جنگ وارد بندر شد سوزانده شد؛ نزدیک شصت کشتی و هزاران دریانورد از دست رفت. این یورش که در دیپلماسی اروپا «رویداد ناگوار» خوانده و رد شد، استقلال یونان را عملاً تضمین کرد و راه جنگ عثمانی-روس 1828–29 را گشود.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["فرمان تنظیمات", "5042ce7b"], "d": ["با خط همایونی که در گلخانه خوانده شد، امنیت جان، مال و ناموس همهٔ رعایا بی‌توجه به دین زیر ضمانت دولت درآمد؛ اصول عدالت در مالیات، نظم در سربازی و ندادن مجازات بی‌محاکمه اعلام شد. فرمان که اثر مصطفی رشید پاشا است، نخستین سند بزرگ با ماهیت قانون اساسی در نوسازی عثمانی شمرده می‌شود و «دورهٔ تنظیمات» (1839–1876) نام عصر اصلاحات را بر خود نهاد؛ بازسازی بنیادین در اداره، حقوق، آموزش و مالیه در این چارچوب پیش رفت.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["آغاز جنگ کریمه", "3b9ca3c8"], "d": ["بحرانی که با مسئلهٔ اماکن مقدس و ادعای حمایت روسیه از رعایای ارتدکس آغاز شد، با اعلام جنگ عثمانی به درگیری آشکار بدل شد؛ پس از یورش سینوپ، انگلستان و فرانسه (و سپس پیمونت) در کنار عثمانی وارد جنگ شدند. با پیاده شدن ارتش‌های متحد در کریمه و گرفتن سواستوپول، جنگ با معاهدهٔ پاریس 1856 برده شد؛ اما نخستین وام خارجی که در سال‌های جنگ گرفته شد (1854) امپراتوری را به گردابی از وابستگی مالی انداخت که نیم‌سده ادامه یافت.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["فرمان اصلاحات", "78ff234d"], "d": ["فرمانی که پیش از مذاکرات صلح پاریس اعلام شد، اصول تنظیمات را گسترش داد و به رعایای غیرمسلمان حقوق گستردهٔ برابری، از جمله مأموریت دولتی، سربازی و گشودن مدرسه، داد؛ سازمان‌های جماعتی از نو تنظیم شد. با معاهدهٔ پاریس که سپس امضا شد، دولت عثمانی رسماً به خانوادهٔ حقوق بین‌الملل اروپایی پذیرفته شد و تمامیت ارضی‌اش در تضمین مشترک قدرت‌های بزرگ درآمد — این تضمین در عمل دروازهٔ تازهٔ دخالت‌ها می‌شد.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["قانون اساسی — مشروطیت یکم", "0fe052c1"], "d": ["در روزی که کنفرانس بین‌المللی گردآمده در استانبول برای گفتگو دربارهٔ بحران بالکان گشوده شد، با شلیک توپ نخستین قانون اساسی عثمانی اعلام شد؛ با قانون اساسی که اثر جنبش «عثمانیان جدید» به رهبری مدحت پاشا است، پارلمان دومجلسی برپا شد. مجلس مبعوثان در مارس 1877 گشوده شد؛ اما عبدالحمید دوم با بهانه کردن جنگ 93 مجلس را در فوریه 1878 به‌طور نامحدود تعطیل کرد و قانون اساسی سی سال معلق ماند.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["جنگ 93 (جنگ عثمانی-روس 1877–78)", "5bd96af7"], "d": ["در جنگی که چون با سال 1293 رومی هم‌زمان بود «جنگ 93» نام گرفت، ارتش‌های روس از دو جبهه حمله کردند؛ هرچند دفاع پلونهٔ غازی عثمان پاشا و نبردهای قفقاز احمد مختار پاشا حماسه شد، جبهه فروریخت و روس‌ها تا یشیل‌کوی (آیاستفانوس) پیش رفتند. جنگ موج‌های بزرگ کوچ مسلمانان را از بالکان و قفقاز به سوی استانبول آغاز کرد که اثرهایش تا امروز می‌رسد؛ ساختار جمعیتی و مالی امپراتوری دیگر به حالت پیشین بازنگشت.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["معاهدهٔ برلین", "47f76a49"], "d": ["کنگرهٔ برلین که «بلغارستان بزرگ» آفریدهٔ آیاستفانوس را به نام توازن قدرت‌های بزرگ بازبینی کرد، باز هم تصویری سنگین بر جا گذاشت: صربستان، مونته‌نگرو و رومانی مستقل شدند؛ شاهزادگی خودمختار بلغارستان برپا شد؛ بوسنی و هرزگوین به اشغال اتریش، قبرس به ادارهٔ بریتانیا، و قارص-اردهان-باتومی به روسیه واگذار شد. نظام پانصدسالهٔ عثمانی در روم‌ایلی عمدتاً از هم گسست؛ «مسئلهٔ شرق» به دستور کار دائمی دیپلماسی اروپا بدل شد. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: فیلیبه، ویدین، ترنوو، وارنا، شومن، سیلیستره، روسچوک، بخارست، یاش، کوستنجه. رومانی در برابر دادن بسارابیا به روسیه، تولچا و دوبروجه را گرفت: تولچا، باباداغ، ماچین، ایساکچه، هیرشووا و مانگالیا در دوبروجهٔ شمالی به رومانی رسیدند.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["اشغال تونس و دیون عمومیه", "c7e25598"], "d": ["فرانسه با بهانه کردن رویدادهای مرز الجزایر تونس را اشغال کرد و با معاهدهٔ باردو زیر حمایت گرفت؛ حضور عثمانی در شمال آفریقا به طرابلس غرب فروکاست. در همان سال با فرمان محرم برای اداره وام‌های خارجی ورشکسته، اداره دیون عمومیه که طلبکاران در آن نماینده داشتند برپا شد: درآمدهای بنیادین چون نمک، تنباکو و ابریشم مستقیماً به این اداره خارجی وابسته شد و حاکمیت مالی به‌سختی محدود گردید. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: قیروان، قابس، صفاقس، جربه (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["اشغال مصر به دست انگلیس", "f1269768"], "d": ["جنبش عرابی پاشا که علیه ورشکستگی مالی و نظارت خارجی در مصر برخاسته بود، پس از بمباران اسکندریه با پیروزی تل‌الکبیر ارتش انگلیس که پیاده شد درهم کوبیده شد و قاهره اشغال گردید. مصر هرچند از نظر حقوقی وابسته به عثمانی ماند، عملاً به اداره انگلیس درآمد؛ کنترل کانال سوئز در مرکز راهبرد امپراتوری بریتانیا جا گرفت.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["اعلام مشروطیت دوم", "95ee2fd2"], "d": ["در برابر جنبشی که با به کوه رفتن افسران وابسته به جمعیت اتحاد و ترقی در مقدونیه بزرگ شد، عبدالحمید دوم قانون اساسی را دوباره به اجرا گذاشت؛ «اعلام آزادی» با شور پذیرفته شد و به انتخابات رفتند. اما ثبات نیامد: پس از سرکوب واقعهٔ 31 مارس (آوریل 1909) عبدالحمید از تخت فرود آمد؛ استقلال بلغارستان، الحاق بوسنی و روی آوردن کرت به یونان نیز در همین ماه‌های آشفته رخ داد.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["جنگ طرابلس غرب", "ed441994"], "d": ["ایتالیا که در پی مستعمره بود به طرابلس غرب، آخرین سرزمین عثمانی در شمال آفریقا، اعلام جنگ کرد و سواحل را اشغال نمود؛ دولت که ناوگان نداشت نتوانست ارتش منظم بفرستد و افسران جوان چون مصطفی کمال و انور بیگ پنهانی به منطقه گذشتند و با قبایل سنوسی مقاومتی مؤثر سازمان دادند. با معاهدهٔ اوشی (18 اکتبر 1912) که با درگرفتن جنگ بالکان امضا شد، لیبی به ایتالیا واگذار گردید؛ ایتالیا رودس و دوازده جزیره را نیز اشغال کرد.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["معاهدهٔ لندن — از دست رفتن روم‌ایلی", "f3f976df"], "d": ["با معاهدهٔ لندن که جنگ نخست بالکان را پایان داد، همهٔ سرزمین‌های غرب خط میدیه-انز و جزایر اژه از دست رفت؛ آلبانی مستقل شد. از روم‌ایلی که بیش از پانصد سال مرکز ثقل جمعیتی، اقتصادی و فرهنگی امپراتوری بود تنها تراکیهٔ شرقی می‌ماند (ادرنه در جنگ دوم بالکان بازپس گرفته شد)؛ این زیان سیاست جنگ و اسکان دولت اتحادیون را به‌گونه‌ای ریشه‌ای سخت‌تر کرد. جاهای زیر که در غرب خط میدیه-انز ماندند از دست رفتند: اسکوپیه، کوپرولو (ولس)، ایشتیپ، استرومنیتسا، دویران، گوگلیا، مناستیر، اوهرید، دبره، پریزرن، پریشتینه، پچ، ینی‌پازار (نووی پازار)، دشت کوزوو؛ سرس، درامه، کاوالا، پتریچ، نوروکوپ، اسکیجه، گومولجینه، دده‌آغاج، دیدیموتیخون، چیرمن، فرجیک، سوفلو، اورستیادا، پراویشته (الفترئوپولی)، استرنا، تاوری، عمور فقیه (فاکیا)، مالک دربند (لالکوو)؛ در کرت خانیا، کاندیه، رتیمنو (رسمو)، سیتیه و اسفاکیه.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["ورود به جنگ جهانی اول", "05a0252e"], "d": ["اینکه رزمناوهای گوبن و برسلاو که از انگلستان گریخته بودند با خریداری‌شده نمایاندن به تنگه درآورده شدند، دولت را گام‌به‌گام به سوی آلمان کشاند؛ با بمباران بنادر روسیه به دست ناوگان به فرماندهی دریاسالار سوشون (29 اکتبر) جنگ عملاً آغاز شد و اعلام‌های متقابل در آغاز نوامبر آمد. با وجود اعلام جهاد اکبر، تأثیر انتظارشده پدید نیامد؛ امپراتوری چهار سال از قفقاز تا فلسطین در پنج جبههٔ جداگانه در جنگ هستی وارد شد.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["پیروزی چاناق‌قلعه", "95d888e8"], "d": ["ناوگان متحدان که هدفش سقوط استانبول و رسیدن به روسیه بود، در 18 مارس با آتش خطوط مین و استحکامات از تنگه عقب رانده شد؛ خطی که کشتی مین‌گذار نصرت گسترده بود سرنوشت نبرد را تعیین کرد. عملیات زمینی گلیبولو که در آوریل آغاز شد نیز در آنافارتالار و جونک‌بایری متوقف شد؛ متحدان در ژانویه 1916 شبه‌جزیره را یکسره تخلیه کردند. نام سرهنگ دوم مصطفی کمال در این جبهه شنیده شد؛ پیروزی که با نزدیک ربع میلیون شهید و مفقود به دست آمد، زادگاه کادرها و روح مبارزهٔ ملی شمرده می‌شود.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["شورش شریف حسین", "75f7c58c"], "d": ["شریف حسین، امیر مکه، پس از مکاتبات پنهانی با بریتانیایی‌ها، با وعدهٔ پادشاهی مستقل عربی قیام کرد؛ راه‌آهن حجاز هدف حمله‌ها شد. هرچند دفاع افسانه‌ای فخرالدین پاشا از مدینه که تا پس از آتش‌بس ادامه یافت نماد مقاومت ماند، این شورش در پیوند با پیشروی بریتانیا در جبههٔ فلسطین، فروپاشی حاکمیت عثمانی در ولایت‌های عربی را شتاب داد. دیگر سکونتگاه‌هایی که در همان تاریخ از دست رفتند: خرمه، تربه.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["متارکهٔ مودروس", "9e87c767"], "d": ["دولت عثمانی که با فروپاشی بلغارستان جبهه‌هایش از هم گسسته بود، با متارکه‌ای که بر زره‌پوش آگاممنون امضا شد از جنگ کنار کشید. گشوده شدن تنگه‌ها و به‌ویژه ماده 7 که امکان اشغال جاهایی را می‌داد که امنیتشان در معرض تهدید بود، در مدتی کوتاه پوشش حقوقی تقسیم عملی شد: موصل، اسکندرون و سپس ازمیر و استانبول اشغال شد. متارکه سند پایان عملی امپراتوری شمرده می‌شود. سایر آبادی‌هایی که در همین تاریخ از دست رفتند: حماه، دمشق، حمص.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["مصطفی کمال در سامسون — مبارزهٔ ملی", "09a8f784"], "d": ["در فضای خشمی که اشغال ازمیر پدید آورده بود، مصطفی کمال پاشا که با عنوان بازرس ارتش نهم در سامسون پیاده شد، مأموریت رسمی‌اش را به سازمان دادن مقاومت در آناتولی بدل کرد. بخشنامهٔ آماسیه و کنگره‌های ارزروم و سیواس ادامهٔ این گام است؛ اصل «استقلال ملت را باز هم عزم و تصمیم ملت نجات خواهد داد» هستهٔ برنامهٔ سیاسی مبارزهٔ ملی شد.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["گشایش مجلس ملی بزرگ ترکیه و سور", "2008feec"], "d": ["با اشغال رسمی استانبول و منحل شدن مجلس مبعوثان، مجلس ملی بزرگ در 23 آوریل 1920 در آنکارا گشوده شد؛ مجلس که اختیارات فوق‌العاده را در خود گرد آورد هستهٔ دولت نوین مبتنی بر ارادهٔ ملی شد. معاهدهٔ سور که دولت استانبول در اوت امضا کرد آناتولی را تقسیم می‌کرد؛ مجلس ملی امضاکنندگان را خائن به وطن اعلام کرد و سور هرگز اجرا نشد.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["نبرد میدانی ساکاریا", "f2f970a6"], "d": ["حملهٔ یونان که تا 50 کیلومتری آنکارا نزدیک شده بود، در نبرد 22 روز و 22 شبه‌ای که به فرمان مصطفی کمال پاشا با بر عهده گرفتن اختیار فرماندهی کل با «خط دفاع نیست، سطح دفاع هست» اداره شد، شکسته شد. ارتش یونان برای نخستین بار به دفاع راهبردی گذشت؛ پیروزی برای مصطفی کمال غازیگری و مشیری (مارشالی) آورد و دروازهٔ توافق‌نامهٔ آنکارا با فرانسه و شناسایی خارجی را گشود.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["حملهٔ بزرگ و آزادی ازمیر", "172a50c4"], "d": ["حمله‌ای که صبح 26 اوت از کوجه‌تپه آغاز شد، در 30 اوت با نبرد میدانی فرماندهی کل در دوملو‌پینار به نابودی نیروهای اصلی یونان رسید؛ با تعقیبی که با فرمان «ای ارتش‌ها، نخستین هدف شما مدیترانه است، پیش!» ادامه یافت، ازمیر در 9 سپتامبر آزاد شد. با متارکهٔ مودانیا (11 اکتبر) تراکیه شرقی بی‌جنگ بازپس گرفته شد؛ پیروزی نظامی قدرت دولت نوینی را که در لوزان بنیان می‌یافت بر سر میز تعیین کرد.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["لغو سلطنت", "9f36a9f6"], "d": ["با فراخوانده شدن دولت استانبول نیز به مذاکرات لوزان، مجلس ملی بزرگ در 1 نوامبر 1922 با جدا کردن سلطنت از خلافت سلطنت را لغو کرد؛ حکومت 623 ساله خاندان عثمانی از نظر حقوقی پایان یافت. محمد ششم وحیدالدین در 17 نوامبر با یک رزمناو انگلیسی از کشور رفت؛ به مقام خلافت با تصمیم مجلس ملی عبدالمجید افندی آورده شد و این مقام نیز در 3 مارس 1924 لغو خواهد شد.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["معاهدهٔ لوزان", "38c27f7d"], "d": ["با معاهدهٔ صلح لوزان که در پایان هشت ماه مذاکرات دشوار امضا شد، مرزها، استقلال کامل و حاکمیت دولت نوین ترک در عرصهٔ بین‌المللی شناخته شد؛ کاپیتولاسیون‌ها لغو شد، دیون عمومیه به فرایند برچیدن درآمد، مبادلهٔ جمعیت تنظیم گشت. لوزان که سور را عملاً بی‌اعتبار کرد، پیروزی دیپلماتیک مبارزهٔ ملی و سند خارجی بنیان‌گذار جمهوری شمرده می‌شود.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["اعلام جمهوری", "d5bfcdfb"], "d": ["با پذیرفتن حکم «شکل حکومت دولت ترکیه جمهوری است» با تغییر قانون اساسی به دست مجلس ملی بزرگ، جمهوری اعلام شد؛ مصطفی کمال پاشا نخستین رئیس‌جمهور برگزیده شد. سرگذشت 624 ساله عثمانی که در 1299 به‌عنوان امارت مرزی آغاز شده بود بدین‌سان بسته شد؛ دولت نوین که حاکمیت در آن بی‌قید و شرط از آن ملت است بر میراث امپراتوری بنیان یافته است.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["عزل تپه‌دلنلی علی پاشا و آغاز محاصرهٔ ینیه", "e8a6530b"], "d": ["سیاست محمود دوم در برچیدن قدرت‌های محلی به تپه‌دلنلی علی پاشا رسید که سی و سه سال بود ینیه را اداره می‌کرد و تسالی و اپیروس را عملاً در دست داشت. پاشا از سرداری دربندها و پسرش ولی از پاشالیق تیرحاله عزل شد؛ چون انتظار می‌رفت اطاعت نکند، نیرو به سویش گسیل شد. خورشید احمد پاشا که برای این کار گمارده شد در همان حال والی موره بود و سرعسکری روم‌ایلی نیز به او داده شد؛ همهٔ مدیران ملکی و نظامی منطقه مأمور دستگیری تپه‌دلنلی شدند. یعنی هنگامی که قیام یونان درگرفت، فرماندهٔ که باید موره را اداره می‌کرد و نیروهای زیر فرمانش قلعهٔ ینیه را محاصره کرده بودند. علی پاشا در 23 مه 1820 با رومیان در ینیه نشستی برگزار کرد، کوشید ایالتی رومی زیر ادارهٔ خود برپا کند و به آنان پول و سلاح یاری رساند. در طرف مقابل قدرتی کم‌مایه نبود: علی پاشا ارتشی 30-40.000 نفره که 7.000 نفرش دائمی بود و ناوگانی کوچک داشت؛ جمعیت زیر ادارهٔ او 1,5-2 میلیون و درآمد سالانه‌اش 4-5 میلیون قروش برآورد می‌شد.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["جنگ عثمانی-ایران آغاز شد — از دست رفتن قارص و بایزید، محاصرهٔ ارزروم", "570b27bd"], "d": ["در دومین سال قیام یونان، مرز شرقی امپراتوری به منطقهٔ جنگ بدل شد. عباس میرزا، ولیعهد قاجار، به بهانهٔ بازرسی کاروان همسر شاه که به حج می‌رفت از سوی نمایندگان عثمانی، با نیروی نظامی بزرگی از مرز گذشت؛ ولایات قارص و بایزید را گرفت و ارزروم را به محاصره درآورد. نیروی روبه‌روی او یک واحد مرزی معمولی نبود: عباس میرزا ارتش آذربایجان را به شیوه‌های اروپایی آموزش داده و در تبریز کارگاه باروت‌سازی و ریخته‌گری توپ برپا کرده بود. دولت عثمانی اما در این هنگام در غرب با قیام موره و در شمال غرب با مقاومت تپه‌دلنلی علی پاشا در ینیه دست‌به‌گریبان بود و ارتشی آموزش‌دیده به شیوهٔ اروپایی نداشت؛ ادارهٔ ینی‌چری تا 1826 برپا می‌ماند.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["اشغال سلیمانیه و بغداد به دست ایران — محاصرهٔ کرکوک", "384d74e4"], "d": ["همزمان با عملیات در شرق آناتولی، نیروهای ایران حمله‌ای گسترده به شمال عراق و ایالت بغداد که زیر اداره عثمانی بودند انجام دادند. بغداد در آن زمان را کولمن داود پاشا که از 1817 والی بود اداره می‌کرد؛ پاشا نیروی 10.000 نفری پیاده و توپخانه‌ای داشت که به دست دووو، از دستیاران پیشین ناپلئون، تعلیم داده بود. در مرکز امپراتوری هنوز چنین ارتشی نبود — واحدهای آموزش‌دیده به شیوهٔ اروپایی در آن سال‌ها تنها در دست والیان نیرومند ایالت‌ها بود. آنچه جنگ را پایان داد پیروزی عثمانی نبود: مقاومت عثمانی و بیماری همه‌گیری که آذربایجان را فرا گرفته بود نیروهای ایران را به عقب‌نشینی ناچار کرد.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["کشته شدن تپه‌دلنلی علی پاشا — پایان محاصرهٔ ینیه", "da679150"], "d": ["مقاومت در ینیه نزدیک به دو سال ادامه یافت و در همین مدت قیام رومیان همه‌گیر شد. چون خورشید پاشا به قلعه جاسوس فرستاد و به فراریان رتبه و عطیه داد، شمار سربازان پیرامون علی پاشا به چهل پنجاه نفر رسید؛ پاشا با این تضمین که در صورت تسلیم به جانش دست زده نخواهد شد به صومعهٔ پاندلئیمون بر دریاچه عقب نشست. در این هنگام خانوادهٔ خورشید پاشا به دست شورشیان رومی افتاده بود؛ او برای آنکه هرچه زودتر به موره بازگردد امان‌نامه‌ای را که داده بود نادیده گرفت و فرمان اعدامی ساختگی فراهم کرد. هنگامی که به اتاق او وارد شدند علی پاشا با سلاح پاسخ داد و در درگیری‌ای که پدید آمد کشته شد؛ سرش در 24 فوریه به استانبول آورده شد. محاصره شکاف درونی فرماندهی عثمانی را نیز آشکار کرده بود: چون قیام موره از مسئلهٔ تپه‌دلنلی خطرناک‌تر شد، سید علی پاشا به‌عنوان سرعسکر مستقل موره گمارده شد، خورشید پاشا که از این خوشش نمی‌آمد درخواست‌های کمک او را رد کرد و حتی کوشید او را در نظر دولت ناموفق جلوه دهد. در پایان سالی که علی پاشا از میان برداشته شد، نیرومندترین قلعهٔ موره، آنابولی، سقوط کرد.", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["پیمان ارزروم — عقب‌نشینی نیروهای ایران در شصت روز", "166373c3"], "d": ["جنگ دو ساله با پیمان صلحی که در ارزروم امضا شد پایان یافت. بر پایهٔ پیمان نیروهای ایران باید در شصت روز از سرزمین‌هایی که اشغال کرده بودند عقب می‌نشستند. پیمان مرز تازه‌ای نکشید، وضع پیش از جنگ را بازگرداند؛ اختلافات مرزی میان دو دولت در 1833-1842 دوباره به درگیری بدل خواهد شد و تنها در 1847 با پیمان دومی که باز در ارزروم امضا شد سامان خواهد یافت. بسته شدن جبههٔ شرق پیش‌شرط آن بود که امپراتوری بتواند همهٔ سنگینی خود را بر قیام یونان بگذارد.", "7c54983b"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["نبرد هرمزگان: اردشیر اردوان پنجم، فرمانروای اشکانی، را شکست داد — اصفهان به هستهٔ ساسانی درآمد", "3689fd45"], "d": ["اردشیر، فرمانروای محلی در فارس، در هرمزگان اردوان پنجم، فرمانروای اشکانی، را شکست داد؛ دودمان اشکانی فروپاشید و دودمان ساسانی برآمد. اطلس اصفهان را از این روز سرزمین ساسانی می‌شمارد.", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["درآمدن Veria (قره‌فریه) به سلطهٔ عثمانی", "b0ece3f3"], "d": ["در همان سال که سالونیک در 1387 تسلیم شد، Veria (قره‌فریه) در درون مقدونیه سفلی نیز به سلطهٔ عثمانی درآمد. شهر گرهگاه راه میان سالونیک و تسالی بود.", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["آلبرشت چهارم قانون ارشدیت Wittelsbach (Primogenitur) را صادر کرد — دوک‌نشین‌های باواریا یکی شد و دوک‌نشینی تقسیم‌ناپذیر پدید آمد", "86ee6f77"], "d": ["دوک آلبرشت چهارم که پس از جنگ جانشینی Landshut (1503-1505) دوک‌نشین‌های باواریا را دوباره در یک دست گرد آورده بود، در 8 ژوئیه 1506 قانون ارشدیت (Primogenitur) را صادر کرد که تقسیم‌ناپذیری کشور و رسیدن تاج‌وتخت به بزرگ‌ترین پسر را پیش می‌بیند. تقسیم‌های باواریا که از 1255 ادامه داشت بدین‌سان پایان یافت؛ باواریا با مرکزیت مونیخ در میان دولت‌های آلمانی دوک‌نشینی یگانه و تقسیم‌ناپذیر ماند.", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["عامر دوم نزدیک صنعا کشته شد — پایان دودمان طاهری", "713ae406"], "d": ["عامر دوم، واپسین فرمانروای طاهریان، در جنگی که بر اثر بدشدن روابط با ناوگان ممالیک آغاز شد، با پشتیبانی قبایل یمن و زیدیان از ممالیک، نخست نزدیک زبید شکست خورد (نوامبر 1516) و سپس در نبرد نزدیک صنعا کشته شد. دودمان طاهری که از 1454 بر یمن فرمان می‌راند بدین‌سان پایان یافت؛ شهرهای دودمان (از جمله تعز) دیگر وابسته به فرمانروایی طاهری نبود.", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["فتح قلعه‌های Lugoj و Caransebeș — ادامهٔ لشکرکشی تیمیشوارا", "1af5a2be"], "d": ["قلعهٔ تیمیشوارا پس از سه هفته مقاومت در 26 ژوئیه 1552 تسلیم شد. در اوت قلعه‌های Lugoj و Caransebeș نیز گرفته شد؛ در امتداد دره Mureș پانزده قلعه به دست آمد و بیلربیگی‌ای تازه با مرکز تیمیشوارا بنیان نهاده شد.", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["کارخانه-قلعهٔ آهن Yekaterinburg بنیان نهاده شد — مرکز منطقهٔ معدنی Ural", "c416e12e"], "d": ["در جایی که Tatishchev بر رود Iset برگزید، چکش‌گاه‌های کارخانهٔ آهنی که de Gennin به پایان رسانده بود به کار افتاد؛ Yekaterinburg تاریخ بنیان خود را از همین روز می‌شمارد. این آبادی که مرکز منطقهٔ معدن و آهن Ural خواهد شد دروازهٔ تزاریسم روسیه به راه سیبری گشت.", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["زاریا (زازائو) به نظارت اداری بریتانیا درآمد — امارت زاریا از خلافت سوکوتو به تحت‌الحمایهٔ نیجریهٔ شمالی وابسته شد", "c2e4131e"], "d": ["امارت Zaria وابسته به خلافت Sokoto در مارس 1902 زیر اداره‌ٔ بریتانیا در نیجریهٔ شمالی درآمد؛ بریتانیایی‌ها در Zaria یک Resident و پادگان نهادند. امیر Kwasau در ژوئیه 1902 تسلیم شد و در سپتامبر برکنار گردید.", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["بریتانیایی‌ها کانو را گرفتند — بزرگ‌ترین امارت خلافت سوکوتو به تحت‌الحمایهٔ نیجریهٔ شمالی رسید", "0484009d"], "d": ["نیروی سرهنگ Morland به فرمان Lugard، کمیسر عالی نیجریهٔ شمالی، از Zaria حرکت کرد و در فوریهٔ 1903 Kano را گرفت؛ امارت Kano وابسته به خلافت Sokoto به اداره‌ٔ بریتانیا درآمد. Sokoto یک ماه بعد، در 15 مارس 1903، گرفته شد.", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["درآمدن Priština به دست ارتش صرب", "2ef111c0"], "d": ["ارتش صرب که در جنگ نخست بالکان وارد کوزوو شد، Priština را گرفت و در شهر سیاست صرب‌سازی دوباره آغاز شد. سقوط Priština از نخستین حلقه‌های فروپاشی مقاومت عثمانی در ولایت کوزوو است.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["اشغال Bitola (منستیر) به دست نیروهای صرب", "db9b3353"], "d": ["Bitola (منستیر)، از مهم‌ترین مراکز اداری و نظامی مقدونیه، در جنگ نخست بالکان پس از پنج روز درگیری به دست نیروهای صرب افتاد. از دست رفتن شهر به معنای پایان عملی حضور دولت عثمانی در مقدونیه بود.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["اعلام استقلال آلبانی — اسماعیل قمالی در Vlorë", "2cdbd4d9"], "d": ["هنگامی که ارتش‌های جنگ بالکان به ولایت‌های آلبانی وارد می‌شدند، اسماعیل قمالی در آولونیا (ولوره) استقلال آلبانی را اعلام کرد. ساحل و درون کشور از دراچ، الباسان، برات، ارگیری (گیروکاسترا) و آقچه‌حصار (کرویا) تا ساراندا بدین‌سان از ادارهٔ عثمانی بیرون آمد و هستهٔ دولت نوین آلبانی را ساخت.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["پایان فرمانروایی عثمانی در Ohrid و Debar", "5273f1ec"], "d": ["یازده روز پس از سقوط Bitola ارتش صرب به منطقهٔ دریاچه‌های مقدونیهٔ غربی وارد شد؛ فرمانروایی پنج‌سدهٔ عثمانی در Ohrid پایان یافت و Debar در شمال نیز در همان عملیات از دست رفت.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["اشغال Shkodër به دست مونته‌نگرویی‌ها", "db704247"], "d": ["یکی از درازترین محاصره‌های جنگ نخست بالکان در Shkodër گذشت؛ پس از ماه‌ها مقاومت شهر به نیروهای مونته‌نگرو سپرده شد. Shkodër از واپسین دژهای عثمانی بود که تا پایان جنگ پایید.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["مونته‌نگرو Shkodër را تخلیه کرد؛ سپاه بین‌المللی قدرت‌های بزرگ وارد شهر شد", "8a6593e9"], "d": ["با فشار قدرت‌های بزرگ، مونته‌نگرو Shkodër را که در 23 آوریل 1913 گرفته بود در 14 مه 1913 تخلیه کرد؛ سپاه بین‌المللی وارد شهر شد و بخشی از اداره‌ٔ بنیادگذار آلبانی گشت.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["ابن سعود الأحساء را گرفت — پایان فرمانروایی عثمانی بر ساحل خلیج", "505f26d5"], "d": ["عبدالعزیز بن سعود، امیر نجد، پادگان عثمانی را بیرون راند و منطقهٔ الأحساء را گرفت و در الهفوف مرکز گرفت. کرانهٔ غربی خلیج همراه با بندرهای القطیف و العقیر به اداره‌ٔ سعودی رسید؛ اداره‌ٔ پنجاه‌سالهٔ دولت عثمانی در منطقه پایان یافت.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["پیمان بخارست — تراکیای غربی و حوضهٔ Kavala از بلغارستان به یونان رسید", "56123a58"], "d": ["جنگ دوم بالکان با پیمان بخارست که میان بلغارستان و صربستان، یونان و مونته‌نگرو امضا شد پایان یافت. حوضهٔ Kavala، Drama و Serres که در جنگ نخست به دست بلغارستان افتاده بود با این پیمان به یونان واگذار شد. با این پیمان Tutrakan (Turtukaya) به رومانی رسید.", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["پیاده‌شدن در شط‌العرب — سقوط بصره و گشایش جبههٔ عراق", "c0a87d5d"], "d": ["در آغاز جنگ جهانی یکم نیروی اعزامی بریتانیا از هند در فاو، در دهانهٔ شط‌العرب، پیاده شد و در زمانی کوتاه بصره را گرفت. سقوط شهر به معنای گشایش جبههٔ عراق و درآمدن انتهای شمالی خلیج به نظارت بریتانیا بود.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["گرجستان استقلال خود را اعلام کرد — سِیم ماوراءقفقاز فروپاشید", "6c79a8c7"], "d": ["گرجستان که از سِیم ماوراءقفقاز، پدیدآمده پس از برست-لیتوفسک، بیرون آمد استقلال خود را اعلام کرد و جمهوری دموکراتیک گرجستان بنیان نهاده شد. گرجستان غربی با Kutaisi به اداره‌ٔ این دولت نو درآمد. با این اعلام Sukhumi، Poti، Zugdidi، Gori، Telavi و Dusheti به جمهوری دموکراتیک گرجستان رسید.", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["جمهوری دموکراتیک آذربایجان اعلام شد", "8baecec3"], "d": ["دو روز پس از جدایی گرجستان، جمهوری دموکراتیک آذربایجان اعلام شد؛ نخستین مرکز گنجه بود. همان روز در ایروان جمهوری ارمنستان نیز بنیان نهاده شد و ماوراءقفقاز به سه دولت جدا تقسیم گشت. با این اعلام شماخی، قبله، اَرَش، شابران، سالیان، قوبا، شکی و بردع به جمهوری دموکراتیک آذربایجان رسید.", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["اشغال حلب به دست نیروهای عرب و بریتانیا", "00efb2da"], "d": ["پس از فروپاشی جبههٔ فلسطین، نیروهایی که به شمال پیش می‌رفتند وارد حلب شدند؛ شهر نخست به دست واحدهای عرب و سپس بریتانیا افتاد. این اشغال که سه روز پیش از آتش‌بس مودروس رخ داد، اداره‌ٔ چهارسدهٔ عثمانی در سوریه را عملاً پایان داد.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["ارتش سرخ آذربایجان را اشغال کرد — پایان جمهوری دموکراتیک", "ebbb4566"], "d": ["ارتش سرخ وارد آذربایجان شد و پارلمان و دولت را منحل کرد؛ جمهوری دموکراتیک آذربایجان که دو سال پایید پایان یافت. حوضهٔ نفتی باکو و گنجه بدین‌سان به ادارهٔ شوروی درآمد. با این اشغال شماخی، قبله، اَرَش، شابران، سالیان، قوبا، شکی و بردع به نظارت روسیهٔ شوروی رسید.", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["خان میسلون — دورهٔ فیصل پایان یافت، سوریه به قیمومت فرانسه رسید", "80a932b0"], "d": ["فرانسوی‌ها در خان میسلون در راه بیروت-دمشق نیروهای سوریه را به سختی شکست دادند و پادشاهی عربی فیصل در دمشق پایان یافت. فرانسه اختیار قیمومت را که در San Remo به او داده شده بود عملاً برقرار کرد؛ منطقه از حلب تا دمشق و از اسکندرون تا دیرالزور به اداره‌ٔ قیمومتی فرانسه وابسته شد.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["امارت شرق اردن بنیان نهاده شد — عبدالله بن حسین امارت خود را اعلام کرد", "5ef520c2"], "d": ["عبدالله، پسر شریف حسین، از راه معان به شمال آمد و امارت شرق اردن را اعلام کرد؛ بریتانیا اندکی بعد این اداره را در چارچوب قیمومت به رسمیت شناخت. عمان مرکز امارت شد و فلات اردن، از جمله کرک، به این اداره‌ٔ نو وابسته گشت.", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["ایتالیا ایالت Ljubljana را به پادشاهی ملحق کرد — Ljubljana از یوگسلاوی جدا شد", "c451f492"], "d": ["ایتالیا که در آوریل 1941 با فروپاشی یوگسلاوی Ljubljana و نیمهٔ غربی اسلوونی را اشغال کرده بود، با فرمان 3 مه 1941 منطقه را با نام ایالت Ljubljana به پادشاهی ملحق کرد؛ کمیسر عالی Grazioli شد. Ljubljana از یوگسلاوی بیرون آمد و به اداره‌ٔ ایتالیا درآمد (تا سپتامبر 1943).", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["هایله سلاسی به Addis Ababa بازگشت — حبشه از آفریقای شرقی ایتالیا جدا شد", "42470af3"], "d": ["پس از آنکه نیروهای بریتانیایی-حبشی در آغاز آوریل Addis Ababa را گرفتند، امپراتور هایله سلاسی در 5 مه 1941 پیروزمندانه به پایتخت بازگشت؛ پایان رسمی اشغال ایتالیا (1936-41) همین روز شمرده می‌شود. اطلس این روز را مرز بازگشت حبشه از آفریقای شرقی ایتالیا به کار می‌برد.", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["نیروهای ژاپنی جزیرهٔ بی‌دفاع لابوان را اشغال کردند — مالایای بریتانیا (مستعمرات تنگه) جزیرهٔ خود در شمال بورنئو را از دست داد", "a946e926"], "d": ["در عملیات بورنئو نیروی کوچکی از ژاپنی‌ها در جزیرهٔ بی‌دفاع لابوان پیاده شد و آن را گرفت؛ جزیره از ژانویهٔ 1942 تا سپتامبر 1945 در اشغال نظامی ژاپن ماند. روز در منابع 1 یا 3 ژانویه ذکر شده است.", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["جزایر Cocos (Keeling) از مستعمرهٔ سنگاپور بیرون آورده شد و به استرالیا واگذار گردید", "5c2d70c7"], "d": ["بر پایهٔ فرمان شورای سلطنتی که بر اساس قانون جزایر کوکوس بریتانیا (1955) صادر شد، در 23 نوامبر 1955، روز اعلان قانون جزایر کوکوس (کیلینگ) 1955 استرالیا، جزایر دیگر بخشی از مستعمرهٔ سنگاپور نبودند و زیر اختیار اتحادیهٔ مشترک‌المنافع استرالیا درآمدند. هوم آیلند (ملک خاندان کلونیز-راس و آبادی مالایی‌های کوکوس) از این روز زیر ادارهٔ استرالیاست.", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["جزیرهٔ Christmas از بریتانیا به استرالیا واگذار شد", "c971c518"], "d": ["فرمان شورای سلطنتی بریتانیا دربارهٔ واگذاری جزیرهٔ کریسمس به استرالیا (1958) در 1 اکتبر 1958 به اجرا درآمد؛ حاکمیت جزیره از مستعمرهٔ سنگاپور بریتانیا به اتحادیهٔ مشترک‌المنافع استرالیا رسید. فلایینگ فیش کوو مرکز سکونت و بندر جزیره است.", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Vukovar سقوط کرد — JNA و واحدهای صرب پس از سه ماه محاصره شهر را گرفتند", "30db2698"], "d": ["مدافعان کروات باقی‌ماندهٔ Vukovar که در محاصره بود در 18 نوامبر 1991 تسلیم شدند؛ شهر به دست ارتش خلق یوگسلاوی و نیروهای صرب افتاد. شهر بعدها از دورهٔ اداره‌ٔ انتقالی سازمان ملل در اسلاوونیای شرقی (UNTAES) گذشت.", "09aa356a"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["غیاث‌الدین کیخسرو آنتالیا را فتح کرد — سلجوقیان به مدیترانه رسیدند", "9812e629"], "d": ["آنتالیا که پس از گرفته‌شدن استانبول به دست لاتین‌ها به دست آلدوبراندینیِ ایتالیایی افتاده بود، با پشتیبانی رومیانی که از اداره لاتین ناخشنود بودند، به دست غیاث‌الدین کیخسرو یکم، سلطان سلجوقیان آناتولی، گرفته شد.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["عزالدین کیکاووس آنتالیا را از قبرسی‌ها بازپس گرفت", "ec2446f9"], "d": ["آنتالیا که در 1212 بر اثر شورشی با پشتیبانی پادشاه قبرس از دست رفته بود، دوباره به دست عزالدین کیکاووس یکم فتح شد و والی‌گری آن بار دیگر به مبارزالدین ارتقش داده شد.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["بیبرس یافا را از صلیبیان گرفت — فرمانروایی پادشاهی اورشلیم در یافا پایان یافت", "c7629d70"], "d": ["بیبرس یکم، سلطان ممالیک، به فرمانروایی صلیبیان در یافا پایان داد، شهر را ویران کرد؛ چوب و مرمر دژ درونی را برای ساختن مسجدش در قاهره فرستاد.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["بیبرس انطاکیه را گرفت — پایان شاهزاده‌نشین انطاکیه", "da2b511a"], "d": ["سپاه ممالیک با یورشی همگانی از دیوارهای انطاکیه گذشت؛ شاهزاده‌نشین صلیبی 170 ساله پایان یافت و اسکندرون نیز دوباره به سرزمین‌های اسلامی پیوست.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["قرامان‌اوغلی‌ها قونیه را از ایلخانیان بازپس گرفتند", "057ec073"], "d": ["پس از گریز دمرتاش، والی آناتولی ایلخانیان، به مصر، قونیه دوباره به دست قرامان‌اوغلی‌ها افتاد. شهر در 1350 به ارتنا خواهد رسید.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["آلفونسو یازدهم، پادشاه کاستیل، الجزیرة‌الخضراء (آلخسیراس) را گرفت: پس از محاصره‌ای بیست‌ماهه فرمانروایی مرینی پایان یافت", "5de2a877"], "d": ["پس از محاصرهٔ حدوداً بیست‌ماههٔ آلفونسو یازدهم، پادشاه کاستیل، و در پایان گفت‌وگوهایی که از 21 مارس 1344 آغاز شد، ابوالحسن، فرمانروای مرینی، به مسلمانان اعلام کرد شهر را ترک کنند؛ در 26 مارس ویلا نووا و روز بعد ویلا ویخا تخلیه شد و کاستیلی‌ها شهر را تحویل گرفتند. آلفونسو یازدهم در 28 مارس 1344 (یکشنبهٔ نخل) با مراسمی به شهر درآمد. الجزیرة‌الخضراء تا 1369 در دست کاستیل ماند.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["استفان دوشان سِرز را از بیزانس گرفت", "2cc79d36"], "d": ["استفان دوشان، پادشاه صرب، که از جنگ داخلی بیزانس بهره برد، سِرز را گرفت و شهر را پایتخت امپراتوری صرب ساخت.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["کنت‌نشین فلدکیرش به اتریش هابسبورگ فروخته شد", "fe4a0306"], "d": ["رودولف، واپسین کنت شاخهٔ مونتفورت-فلدکیرش، در 1375 همهٔ ملک خود را به دوک‌های اتریش، هابسبورگ‌ها، فروخت؛ واگذاری واقعی با مرگ او (1390) تکمیل شد. فلدکیرش نخستین پارهٔ بزرگ فورارلبرگ بود که به دست هابسبورگ‌ها افتاد.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["بالچیک و کرانهٔ دوبروجا به اداره عثمانی درآمد", "dfd348b9"], "d": ["پس از پیروزی کوزوو، بالچیک در کرانهٔ دوبروجا به اداره عثمانی درآمد. اندکی بعد ناحیه را میرچا، وویوودای والاکی، اشغال خواهد کرد و فرمانروایی عثمانی در 1393 دوباره برقرار خواهد شد.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["سادات مرعشی در ماهانسر به تیمور تسلیم شدند — مازندران به تیموریان رسید", "125dbed8"], "d": ["تیمور که در لشکرکشی پنج‌ساله به مازندران درآمد، مرعشیانی را که در کاراتوغان در برابرش ایستاده بودند، در دژ ماهانسر محصور کرد و تسلیم گرفت. در ساری و آمل کشتار بزرگی رخ داد؛ ساری به اسکندر شیخی، پسر کیا افراسیاب، داده شد.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["شیبنیک دوباره به اداره جمهوری ونیز درآمد", "9b7998bf"], "d": ["پس از آنکه لادیسلاو ناپلی حقوق خود بر دالماسیا را در 1409 به ونیز فروخت، شیبنیک که ایستادگی می‌کرد، در 1412 دوباره به اداره ونیز درآمد. شهر تا برافتادن جمهوری در 1797 به‌عنوان ملک ونیز در دالماسیا ماند.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["لشکرکشی چلبی محمد به جاندارئوغلی‌ها: چانکیری به قاسم بیگ که در حمایت عثمانی بود داده شد", "da03b919"], "d": ["چلبی محمد که بر ضد اسفندیار بیگ جاندارئوغلی، که به شیخ بدرالدین برای گذر به والاکی یاری کرده بود، لشکر کشید، به قسطمونی پیش رفت و سینوپ را که اسفندیار به آن عقب نشسته بود محاصره کرد. اسفندیار فرمانروایی عثمانی را شناخت؛ با پذیرفتن کوه ایلگاز به‌عنوان مرز، چانکیری و پیرامون آن به پسرش قاسم بیگ که به عثمانی پناه آورده بود داده شد.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["با گرفته‌شدن سمندره (اسمدرووو)، هیسارجیک (گروتسکا) نیز به عثمانی رسید", "ab724ec9"], "d": ["سمندره پس از محاصره‌ای سه‌ماهه گرفته شد. هیسارجیک (گروتسکا) که 17 کیلومتر با سمندره فاصله دارد، در اطلس سرنوشت مرکز برادر خود، سمندره، را دنبال می‌کند و در همان روز از دوک‌نشین صرب به عثمانی می‌رسد (در 1444 بازگردانده خواهد شد).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["نیمهٔ نخست کنت‌نشین برگنس به اتریش هابسبورگ فروخته شد", "3a9598db"], "d": ["الیزابت هوخبرگی، وارث مونتفورت-برگنس، در 1451 نیمی از کنت‌نشین برگنس را به هابسبورگ‌ها فروخت؛ نیم دیگر در 1523 گرفته شد. برگنس بدین‌سان جزئی از فورارلبرگ هابسبورگ شد.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["با تسلیم گوردوس (کورنت)، سیکیون نیز به عثمانی رسید", "c7b0d22d"], "d": ["فاتح در لشکرکشی موره، گوردوس (کورنت) را پس از محاصره‌ای سه‌ماهه با صلح گرفت. سیکیون که 17 کیلومتر با کورنت فاصله دارد، در اطلس سرنوشت مرکز برادر خود، گوردوس، را دنبال می‌کند و در همان روز به عثمانی می‌رسد.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["با تسلیم سمندره، هیسارجیک (گروتسکا) نیز به عثمانی رسید", "e3d76f5c"], "d": ["هلنا، بیوهٔ لازار برانکوویچ، دژ سمندره را به عثمانیان تسلیم کرد؛ دوک‌نشین صرب پایان یافت. هیسارجیک (گروتسکا) که مرکز برادرش سمندره است، در همان روز به عثمانی می‌رسد.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["تسلیم کفه و تابعیت خان کریمه — کرانهٔ چرکسیه (سوچی، توآپسه، مایکوپ) به‌عنوان حوزهٔ حمایت سست به خانات کریمه پیوست", "e99eb8e8"], "d": ["کفه پس از محاصره‌ای چهارروزه به احمد پاشا تسلیم شد، منگلی گیرای تابعیت سلطان عثمانی را پذیرفت. پیرامون سوچی، توآپسه و مایکوپ، سرزمین قبایل چرکسی که خان‌های کریمه را مرجع می‌شناختند، در اطلس از این تاریخ به‌عنوان حمایت سست به خانات کریمه وابسته نشان داده می‌شود.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["مسکو بریانسک را از دوک‌نشین بزرگ لیتوانی گرفت", "fb1c3a61"], "d": ["در جنگ مسکو و لیتوانی 1500-1503 سپاه روس بریانسک را گرفت و شهر به دولت مسکو پیوست؛ آتش‌بس 1503 این دستاورد را شناخت.", "8e507991"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["بیقلی محمد پاشا موصل، سنجار و عمادیه را از صفوی گرفت", "3039d6af"], "d": ["بیقلی محمد پاشا که در قوچ‌حصار قره‌خان را شکست داد، هنگام محاصرهٔ ماردین دژهای پیرامون را از صفویان گرفت: موصل، رها، بیره‌جیک و سنجار گرفته شد، عمادیه و دیگر حاکمان کرد تابعیت عثمانی را پذیرفتند. دژ ماردین اما پس از بازگشت پاشا از مرج دابق تحویل گرفته خواهد شد.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["گوستاو واسا در استرنگنس پادشاه برگزیده شد — پادشاهی سوئد از اتحادیهٔ کالمار جدا شد", "a6e95f4c"], "d": ["گوستاو اریکسون واسا که پس از حمام خون استکهلم (1520) بر ضد کریستیان دوم، پادشاه دانمارک، شورید، در 6 ژوئن 1523 در ریکسداگ سوئد که در مه 1523 در استرنگنس گرد آمده بود، پادشاه برگزیده شد. سوئد و فنلاند وابسته به آن بدین‌سان از اتحادیهٔ کالمار که از 1397 ادامه داشت قطعاً بیرون آمدند و دورهٔ واسای پادشاهی مستقل سوئد آغاز شد.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["طبقات سیلزیا فردیناند یکم را پادشاه شناختند — سیلزیا به اتریش هابسبورگ رسید", "a28e10c2"], "d": ["پس از آنکه تاج بوهم با مرگ لایوش دوم در موهاچ خالی ماند، فردیناند هابسبورگ در اکتبر 1526 برای آن برگزیده شد. طبقات سیلزیای بالا و پایین در 5 دسامبر 1526 در نشست همگانی، به شرط تأیید امتیازهایشان، او را پادشاه و همسرش آنا را ملکه شناختند. دوک‌نشین‌های سیلزیا بدین‌سان همراه با تاج بوهم به اداره هابسبورگ درآمد.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["گوستاو واسا، پادشاه سوئد، هلسینکی را بنیان نهاد", "43468b54"], "d": ["گوستاو واسا، پادشاه سوئد، در 1550 در دهانهٔ رود ونتا، برای رقابت با رِوال (تالین) در تجارت بالتیک، هلسینکی را به‌عنوان شهر تجاری تازه بنیان نهاد. شهر در 1640 به جای کنونی‌اش، به سوی دریا، منتقل شد.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["امام یعربی عمان ناصر بن مرشد جلفار را از پرتغال گرفت", "6ca9fb0c"], "d": ["پرتغالی‌ها که پس از سقوط هرمز در 1622 نیز در جلفار پابرجا مانده بودند، با فتح ناصر بن مرشد، امام یعربی عمان، در 1633 از ناحیه بیرون رانده شدند.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["از دست رفتن دژ سین (سینج) به ونیز — درون دالماسیا", "3af8e103"], "d": ["در جنگ موره، نیروهای ونیز در 1686 دژ سین (سینج) در درون دالماسیا را از عثمانیان گرفتند؛ دژ در برابر محاصرهٔ عثمانی در 1715 نیز ایستادگی کرد و در دست ونیز ماند.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["رسیدن وارادین و باچ به پادشاهی مجارستان (تاج هابسبورگ) — عقب‌نشینی از باچکا پس از هارشان", "6bc2b1ac"], "d": ["سپاه ساری سلیمان پاشا که از شکست هارشان عقب می‌نشست، در 1 سپتامبر 1687 از وارادین گذشت و دژ را به جعفر پاشا سپرد؛ اندکی بعد وارادین و باچ در باچکا به دست نیروهای هم‌پیمان هابسبورگ افتاد. چون در کارلوویتس ساوا مرز پذیرفته شد، وارادین در سوی اتریش ماند.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["رسیدن اوسیک به پادشاهی مجارستان (تاج هابسبورگ) — آغاز از دست رفتن اسلاونیا", "7af97ffe"], "d": ["پس از شکست هارشان، دژ پل اوسیک بر دراوا در 26 سپتامبر 1687 به نیروهای هابسبورگ رسید. حضور نظامی عثمانی و جمعیت ترک در اسلاونیا میان 1686-1688 به‌تدریج عقب نشست؛ ناحیه به اداره هابسبورگ درآمد.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["از دست رفتن هرسگ‌نووی به ونیز — دهانهٔ خلیج کوتور", "b88046d8"], "d": ["در جنگ موره، ناوگان ونیز و هم‌پیمانانش در 1687 دژ هرسگ‌نووی در دهانهٔ خلیج کوتور را محاصره و گرفتند؛ شهر تا برافتادن جمهوری ونیز در 1797 در دست ونیز ماند.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["پیوستن کورسیکا به تاج انگلیس — پادشاهی انگلیسی-کورسیکایی", "10f18bde"], "d": ["پائولی که بر ضد فرانسهٔ انقلابی شورید، با پشتیبانی ناوگان انگلیس جزیره را از پادگان‌های فرانسوی پاک کرد؛ مجمع گردآمده در کورته قانون اساسی‌ای را پذیرفت که کورسیکا را به پادشاه انگلیس وابسته می‌کرد. جزیره دو سال به‌عنوان پادشاهی انگلیسی-کورسیکایی زیر اداره فرماندار کل انگلیسی گیلبرت الیوت ماند.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["تخلیهٔ کورسیکا به دست انگلیسی‌ها — جزیره دوباره از آنِ فرانسه", "c9f986fe"], "d": ["انگلستان که با پیروزی‌های بناپارت در ایتالیا و گرویدن اسپانیا به صف فرانسه در مدیترانه در تنگنا افتاده بود، کورسیکا را تخلیه کرد. پادشاهی انگلیسی-کورسیکایی پایان یافت و جزیره دوباره به فرانسه پیوست.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["سپاه اتریش-مجارستان مقاومت را درهم شکست و بیهاچ را گرفت", "ffec53e0"], "d": ["اتریش-مجارستان که با پیمان برلین حق اشغال بوسنی و هرزگوین را گرفته بود، در بیهاچ با مقاومت مسلمانان بومی روبه‌رو شد. نیروهای تحت فرماندهی ژنرال ویلهلم فون راینلندر شهر را در 18 سپتامبر 1878 گرفتند؛ پادگان استروویتسا در دره اونا نیز در همین عملیات از دست عثمانی بیرون رفت.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["انگلیسی‌ها سوکوتو را اشغال کردند — خلافت سوکوتو پایتخت خود را از دست داد", "e744f986"], "d": ["لوگارد، فرماندار انگلستان که شمال نیجریه را در 1900 مستعمره اعلام کرده بود، پس از گرفتن یکی‌یکی امارت‌ها، سپاه سوکوتو را به شکستی سنگین دچار کرد و در 15 مارس 1903 پایتخت را اشغال کرد. با کشته‌شدن خلیفه طاهر که گریخته بود در ژوئیه در بورمی، فرمانروایی سیاسی خلافت پایان یافت.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["ابن سعود امیر رشیدی را شکست داد — قصیم از امارت شمر به سعودیان رسید", "a32201dd"], "d": ["عبدالعزیز بن سعود که ریاض را در 1902 بازپس گرفته بود، در 13 آوریل 1906 عبدالعزیز بن متعب، امیر رشیدی، را شکست داد و کشت. پس از این نبرد ناحیهٔ قصیم (بریده، عنیزه) را گرفت؛ رشیدیان از این پس تنها در حائل و پیرامون آن فرمان راندند.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["جزیرهٔ کمران به دست انگلیسی‌ها اشغال شد", "c514bb66"], "d": ["جزیرهٔ کمران در کرانهٔ یمن در دریای سرخ در جنگ جهانی اول در 1915 به دست انگلیسی‌ها اشغال شد و از عدن اداره شد.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["اشغال نابلس به دست انگلیسی‌ها — فروپاشی جبههٔ فلسطین", "b5e85950"], "d": ["در سپتامبر 1918 یورش بزرگ آلنبی در جبههٔ فلسطین، ارتش‌های 7 و 8 عثمانی را درهم شکست؛ نابلس به دست انگلیسی‌ها افتاد و فرمانروایی چهار سدهٔ عثمانی در شهر پایان یافت. شهر تا 1920 در اداره نظامی انگلیس ماند.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["ورود انگلیسی‌ها به موصل — اشغال ولایت موصل برخلاف متارکه", "ed5e8e33"], "d": ["هنگام امضای متارکهٔ مودروس، موصل در دست نیروهای ترک بود. انگلیسی‌ها با تکیه بر ماده 7 متارکه، در 8 (یا 10) نوامبر 1918 به شهر درآمدند و در 15 نوامبر یگان‌های ترک ناچار از ولایت عقب نشستند. مسئلهٔ موصل در لوزان نیز حل نشد و به پیمان آنکارای 1926 ماند.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["پیمان لوزان — پاتموس به ایتالیا واگذار شد، فرمانروایی یونان بر جزایر اژه تأیید شد", "185960b3"], "d": ["با ماده 15 لوزان، ترکیه از همهٔ حقوق و عنوان‌های خود دربارهٔ دوازده جزیره (دودکانسه)، از جمله باتنوز (پاتموس)، به سود ایتالیا گذشت؛ جزایر از 1912 عملاً در اشغال ایتالیا بود. ماده 12 فرمانروایی یونان بر لمنوس، ساموتراکی، میدیللی، ساقیز، سیسام و نیکاریا را تأیید کرد. بوزبابا (آی استراتی) و فورنوز (فورنی) از 1912 در دست یونان بودند و پس از لوزان نیز در یونان ماندند؛ نام این دو جزیره در ماده 12 لوزان نیامده است.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["قانون تونجلی — به جای سنجاق درسیم ولایت تونجلی بنیان یافت (مرکز کالان)", "1ae9ad50"], "d": ["با قانون شماره 2885 مقرر شد در ناحیهٔ درسیم ولایتی تازه به نام تونجلی بنیان نهاده شود؛ مرکز اداری ولایت سکونتگاه کالان شد و آن سکونتگاه بعدها نام تونجلی گرفت. ناحیه در جمهوری ترکیه ماند؛ آنچه دگرگون شد جایگاه اداری و نام آن است.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["استقلال مراکش: حمایت فرانسه پایان یافت، سلا و رباط به پادشاهی مراکش رسید", "a62a3fdb"], "d": ["با پیمان استقلال که در 2 مارس 1956 امضا شد، حمایت فرانسه که از 1912 ادامه داشت پایان یافت؛ سلا و رباط سرزمین پادشاهی مستقل مراکش شد. اسپانیا استقلال مراکش را در 5 آوریل 1956 شناخت.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["هبرید جدید مستقل شد: جمهوری وانواتو بنیان یافت", "cc93330f"], "d": ["کاندومینیوم هبرید جدید که زیر حاکمیت مشترک فرانسه و بریتانیا بود، در 30 ژوئیه 1980 با نام وانواتو مستقل شد. پورت ویلا، پایتخت در جزیرهٔ افاته، و سکونتگاه تئوما از اداره کاندومینیوم به وانواتو رسید.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["آفریقای جنوبی خلیج والویس (والویس بی) را به نامیبیا واگذار کرد", "96bb0184"], "d": ["جمهوری آفریقای جنوبی در 1 مارس 1994 بندر خلیج والویس و دوازده جزیرهٔ دور از ساحل را به دولت نامیبیا واگذار کرد؛ نظارت هشتادوچهارساله آفریقای جنوبی پایان یافت.", "fdd93117"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["بلگراد و ماچوا از سوی پادشاه مجارستان به دراگوتین داده شد", "a4c2c535"], "d": ["پادشاه مجارستان در 1284 ادارهٔ ماچوا و بلگراد را به استفان دراگوتین، پادشاه صرب که در 1282 از تاج‌وتخت کناره گرفته بود، سپرد؛ بلگراد بیش از سی سال در دست دراگوتین ماند (پادشاهی سرم زیر تابعیت مجارستان).", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["آلانیا (علائیه) در دورهٔ پس از سلجوقیان به کنترل بیگ‌نشینی محلی درآمد", "7b1489b3"], "d": ["با فروپاشی عملی دولت سلجوقیان روم در دهه‌های 1290، بندر علائیه (آلانیا) در ساحل مدیترانه از اقتدار مرکزی مستقل شد و به کنترل بیگ‌نشین‌های منطقه (در این دوره در حوزهٔ نفوذ قرامان‌اوغولاری) درآمد؛ تاریخ دقیق و اینکه کدام بیگ‌نشین مستقیماً حاکم بود در منابع روشن نیست.", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["مجارها بلگراد را از میلوتین پس گرفتند", "16d254a2"], "d": ["پس از مرگ دراگوتین در 1316، صربستان خواست بلگراد را نگه دارد و مجارستان بازپس‌گیری آن را خواست؛ در 1319 مجارها حمله کردند و پس از ماه‌ها درگیری سپاه صرب عقب نشست و شهر ویران به بنات ماچوای مجارستان پیوست. بلگراد تا زمان واگذاری آن به استفان لازارویچ در 1403-04 زیر فرمانروایی مجارستان ماند.", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["سینوپ به‌دست غازی چلبی گرفته شد و به نفوذ جاندارئوغولاری درآمد", "f107586a"], "d": ["با سست شدن حاکمیت ایلخانی در منطقهٔ قسطمونی و سینوپ، غازی چلبی، از خاندان بنیان‌گذار بیگ‌نشین جاندارئوغلو (اسفندیارئوغلو) که نیرومند شده بود، در حدود 1322 سینوپ را گرفت و شهر را مرکز بندری بیگ‌نشین کرد.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["شیبنیک که میان کنت‌های شوبیچ و ونیز مانده بود به ونیز وابسته شد", "99b341e0"], "d": ["شیبنیک که میان کنت‌های شوبیچِ بریبیر، فئودال‌های کروات، و ونیز مانده بود، در 1 مارس 1322 خود را به ونیز داد و تا 1357 در اداره ونیز ماند.", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["تروگیر در برابر کنت‌های بریبیر به ونیز پیوست", "4ccf9ce4"], "d": ["تروگیر که زیر فشار کنت‌های شوبیچِ بریبیر بود، برای حفظ آزادی‌های خود در 17 آوریل 1322 خود را به ونیز سپرد و تا 1357 زیر حمایت ونیز ماند.", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["حاکمیت مجارستان در اسپلیت پایان یافت — اداره ونیز آغاز شد", "4b04ca1a"], "d": ["حاکمیت مجارستان در کمون اسپلیت که از 1133 ادامه داشت در 18 سپتامبر 1327 پایان یافت؛ شهر به اداره ونیز درآمد و تا 1357 آنجا ماند.", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["فرمانروایی ونیز بر اسپلیت پایان یافت — سلطهٔ مجارستان دوباره آغاز شد", "e99628fc"], "d": ["فرمانروایی ونیز بر اسپلیت که در 1327 آغاز شده بود در 1357 پایان یافت؛ شهر دوباره مستقیماً زیر سلطهٔ مجارستان درآمد (تا 1420).", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["تروگیر از حمایت ونیز بیرون آمد — سلطهٔ مجارستان دوباره آغاز شد", "7f112aa8"], "d": ["تروگیر تا 9 ژوئیه 1357 زیر حمایت و فرمانروایی ونیز ماند؛ هنگامی که لویی آنژویی کوشید دالماسی را از ونیز جدا کند، از این حمایت بیرون آمد و به حاکمیت پادشاهی کرواسی-مجارستان بازگشت.", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["شیبنیک از ونیز جدا شد — به سلطهٔ مجارستان درآمد", "adb9d6ca"], "d": ["شیبنیک در 14 دسامبر 1357، هنگامی که لویی آنژویی دالماسی را از ونیز جدا می‌کرد، از ونیز جدا شد و زیر سلطهٔ مجارستان درآمد.", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["پیمان زادار — دوبرونیک از ونیز به حمایت مجارستان گذشت", "57fb81f9"], "d": ["پیمان زادار که در 18 فوریه 1358 امضا شد، به حاکمیت 150 ساله ونیز بر دالماسی پایان داد؛ دوبرونیک (راگوزا) بدین‌سان از اداره ونیز بیرون آمد و جایگاه جمهوری نیمه‌خودمختاری یافت که زیر حمایت لایوش یکم، پادشاه مجارستان، درآمد.", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["امتیاز ویشگراد — دوبرونیک به لویی یکم، پادشاه مجارستان، وابسته شد", "9d3d02a8"], "d": ["هنگامی که ونیز با صلح زادار (فوریه 1358) از حقوق خود بر دالماسی چشم پوشید، دوبرونیک جداگانه با لویی یکم مذاکره کرد؛ در مه 1358 با امتیاز ویشگراد به تاج مجارستان وابسته شد (وفاداری در برابر حمایت، با خراج سالانه و سرباز).", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["تورتکو یکم فرمانروایی بر شهرهای ساحلی دالماسی (از جمله شیبنیک) را به دست گرفت", "c53aad4d"], "d": ["تورتکو یکم، پادشاه بوسنی، در 1390 فرمانروایی بر شهرهای ساحلی دالماسی، به‌جز زادار، را به دست گرفت؛ شیبنیک نیز از سلطهٔ مجارستان بیرون آمد و برتری پادشاه بوسنی را پذیرفت.", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["مرگ تورتکو یکم؛ شیبنیک به سلطهٔ مجارستان بازگشت", "ef2d3b2f"], "d": ["با مرگ تورتکو یکم، پادشاه بوسنی، در 1391 برتری بوسنی بر شیبنیک پایان یافت؛ شهر زیر فرمانروایی زیگیسموند، پادشاه مجارستان، درآمد (1391-1402).", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["منطقهٔ ارزروم و اشکاله در کشمکش قره‌قویونلو-تیموری دست‌به‌دست شد", "ca64775a"], "d": ["در خلأ قدرتی که پس از مرگ تیمور در 1405 پدید آمد، قره‌یوسف، فرمانروای قره‌قویونلو، میان 1406 و 1408 علیه والیان تیموری در آناتولی خاوری به حرکت درآمد؛ ارزروم و اشکالهٔ پیرامون در این کشمکش از کنترل تیموری بیرون آمد و به نفوذ قره‌قویونلو درآمد.", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["زادار زیر فرمانروایی ونیز درآمد — «ورود مقدس» (سانتا اینترادا)", "820c9276"], "d": ["پس از آنکه لادیسلاس، پادشاه ناپل، دالماسی را به ونیز فروخت، مردم زادار سربازان ناپلی را از شهر بیرون راندند؛ در 31 ژوئیه 1409 ناظران (پرووِدیتوره‌های) ونیز وارد شهر شدند و فرمانروایی ونیز را که تا 1797 ادامه یافت برقرار کردند.", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["تروگیر زیر فرمانروایی ونیز درآمد", "fbca501f"], "d": ["در جریان جنگ ونیز با مجارستان، با رسیدن ناوگان فرمانده کل پیرو لوردان، تروگیر در 22 ژوئن 1420 به فرمانروایی ونیز درآمد؛ این شهر که آخرین شهر دالماسی بود که به ونیز پیوست تا 1797 زیر پرچم ونیز ماند.", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["اوزون حسن آق‌قویونلو شاخهٔ ایوبی حصن‌کیفا را برانداخت", "2b464a1f"], "d": ["حصن‌کیفا (حسن‌کیف) و سعرد که در دجلهٔ بالا همراه با حماه یکی از دو شاخهٔ برجای‌ماندهٔ دودمان ایوبی بود، در 1462 به‌دست اوزون حسن، فرمانروای آق‌قویونلو، الحاق شد و به حاکمیت ایوبیان پایان داده شد.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["پرتغال حاکمیت خود را بر سواحل تنگهٔ هرمز تکمیل کرد", "bef031f0"], "d": ["لشکرکشی خلیج فارس که آفونسو دو آلبوکرک در 1507 آغاز کرد، در 1515 با جزیرهٔ هرمز و قشم و بریمی در ساحل مقابل تکمیل شد؛ پادشاهی هرمز وابسته به ایران عملاً زیر حمایت پرتغال درآمد و پرتغال کنترل تجارت خلیج را به دست گرفت.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["اتحاد لوبلین — سرزمین‌های اوکراین از لیتوانی به لهستان رسید", "1881ceff"], "d": ["اتحاد لوبلین که در 1 ژوئیه 1569 امضا شد، دوک‌نشین بزرگ لیتوانی و پادشاهی لهستان را در یک دولت (Rzeczpospolita) یکی کرد. بنا بر شرط توافق، پودولیا، ولینیا و منطقهٔ کیف (از جمله بار، بردیچف، بیالیستوک، براسلاو) از نظر اداری مستقیماً از لیتوانی به پادشاهی لهستان واگذار شد.", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["ادارهٔ فیومه به کرواسی وابسته به تاج مجارستان واگذار شد", "dfedccf8"], "d": ["ماریا ترزا، امپراتریس، با فرمان 14 فوریه 1776 ادارهٔ فیومه را از طریق شورای زاگرب به مجارستان سپرد؛ دیپلم 1779 شهر را به‌صورت یک پیکر جدا (corpus separatum) مستقیماً وابسته به تاج مجارستان کرد.", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["فیومه با صلح شونبرون به فرانسه واگذار شد (ایالات ایلیریا)", "16bf1fca"], "d": ["با صلح شونبرون در 14 اکتبر 1809، فیومه از اتریش به فرانسه رسید و تا 1813 بخشی از ایالات ایلیریای ناپلئون بود.", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["بازگشت فیومه از فرمانروایی ایلیریای فرانسوی به هابسبورگ", "1b5b9954"], "d": ["در 1813، پس از شکست ناپلئون در روسیه، فیومه از ایالات ایلیریا بیرون آمد و به امپراتوری اتریش بازگشت.", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["فیومه به پادشاهی مجارستان بازگردانده شد", "aafdd0ee"], "d": ["پس از فرمان 5 ژوئیه 1822 فرانتس یکم، کنت گیورگی مایلات به نام دولت مجارستان در 15 اکتبر 1822 شهر را تحویل گرفت؛ فیومه به پادشاهی مجارستان بازگشت.", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["نیروهای مصر از منطقهٔ احساء (لحسا) عقب نشستند", "5ea75c8d"], "d": ["نیروهای مصر محمدعلی پاشا در 1836 نجد و عربستان خاوری (از جمله احساء، قطیف، عقیر، جبیل) را اشغال کرده بودند؛ با اینکه کنوانسیون تنگه‌های لندن 1840 مصر را از فتوحات در شبه‌جزیرهٔ عربستان بازداشت، نیروها در 1841 از منطقه عقب نشستند و اداره دوباره به نیروهای محلی (نفوذ سعودی/آل خلیفه) بازگشت.", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["دژ آق‌مسجد به‌دست نیروهای روس گرفته شد — خط سیردریای خانات خوقند فروپاشید", "e9f9a9c7"], "d": ["نیروهای روس به فرماندهی ژنرال واسیلی پروفسکی دژ آق‌مسجد را که از خانات خوقند در ساحل سیردریا بود در ژوئیه 1853 پس از محاصره‌ای دراز گرفتند؛ دژ بعدها با نام پروفسک پاسگاه پیشرو ترکستان روس شد.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["نبرد گوک‌تپه — ترکمنان تکهٔ آخال از روسیه شکست خوردند", "76c7a102"], "d": ["نیروهای روس به فرماندهی ژنرال میخائیل اسکوبلف در 24 ژانویه 1881 با سقوط دژ گوک‌تپه (Geok Tepe) مقاومت ترکمنان تکهٔ آخال را شکستند؛ منطقهٔ ترکمن‌نشین فراسوی خزر، از جمله دشت دهستان، ابیورد و نسا، به روند پیوستن به امپراتوری روسیه درآمد (منطقهٔ فراخزر در 1881 تأسیس شد). با این رویداد قزل‌آروات و عشق‌آباد (سرزمین ترکمنان آخال) به روسیه رسید.", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["پادشاهی رومانی اعلام شد — شاهزاده‌نشین به پادشاهی دگرگون شد", "4d413f0c"], "d": ["شاهزاده‌نشین رومانی که استقلالش در کنگرهٔ برلین پس از جنگ عثمانی-روس 1877-78 به رسمیت شناخته شد، در 26 مارس 1881 (به گاهشمار ژولینی 14 مارس) با تاج‌گذاری پادشاه کارول یکم به پادشاهی تبدیل شد؛ بابادگ، بیرلاد، بوزائو و پایتخت بخارست، همهٔ کشور از نظر اداری بخشی از پادشاهی نو شد. با اعلام پادشاهی همهٔ رومانی (یاش، گالاتس، برایلا، کنستانتا، تولچا، کالافات و دیگر شهرها) پادشاهی رومانی شد.", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["ایتالیا فلات اریتره، از جمله اسمره و کرن، را الحاق کرد", "31308dc8"], "d": ["ایتالیا که از خلأ قدرت برخاسته از مرگ یوهانس دوم، امپراتور حبشه، در 1889 بهره می‌گرفت، پس از پیمان اوچیالی (وچالِ؛ 2 مه 1889) فلات اریتره، از جمله اسمره و کرن، را عملاً الحاق کرد؛ در 1 ژانویه 1890 رسماً با نام «اریتره» مستعمره اعلام شد. با این رویداد کرنه به اداره ایتالیا گذشت.", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["منطقهٔ شمال‌خاوری کنیا (خط گاریسا-مارسابیت) به حمایت آفریقای خاوری انگلیس پیوست", "e45c6d43"], "d": ["حمایت آفریقای خاوری انگلیس که با واگذاری امتیاز شرکت آفریقای خاوری انگلیس به تاج در 1895 تأسیس شد، گسترش یافت و مناطق شمال‌خاوری چون گاریسا، کیتویی، مارسابیت و واجیر را نیز دربرگرفت؛ برقراری ادارهٔ عملی در این مناطق درونی تا نیمهٔ دوم دههٔ 1890 به درازا کشید.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["امیرنشین ایلورین به‌دست نیروهای شرکت سلطنتی نیجر گرفته شد", "b111cb7d"], "d": ["امیرنشین ایلورین وابسته به خلافت سوکوتو در لشکرکشی فوریه 1897 نیروهای شرکت سلطنتی نیجر به فرماندهی سر جورج گلدی گرفته شد؛ نیروی نظامی امیرنشین شکسته شد و منطقه عملاً به نفوذ انگلیس درآمد (الحاق رسمی با تأسیس حمایت نیجریه شمالی در 1900 تکمیل شد).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["کاباراگا، پادشاه بونیورو، اسیر شد، پادشاهی به حمایت اوگاندای انگلیس پیوست", "62bc7c64"], "d": ["کاباراگا، پادشاه بونیورو، که از 1894 در برابر نیروهای انگلیس مقاومت می‌کرد، در 9 آوریل 1899 در منطقهٔ لانگو (نزدیک دوکولو) دستگیر و به سیشل تبعید شد؛ پایتخت هویما و ماسیندی و سرزمین‌های پادشاهی به حمایت اوگاندای انگلیس پیوست.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["پیمان تورو — پادشاهی تورو بخشی خودمختار از حمایت اوگاندای انگلیس شد", "c55340a2"], "d": ["پس از سقوط بونیورو در 1899 پادشاهی همسایهٔ تورو حمایت انگلیس را که از 1896 ادامه داشت در چارچوب پیمان اوگاندا 1900 رسمی کرد؛ پادشاهی، از جمله پایتخت فورت پورتال، در حمایت اوگاندای انگلیس جایگاه اداره محلی خودمختار یافت.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["امیرنشین آداماوا میان آلمان و انگلستان تقسیم شد", "b9230d3d"], "d": ["امیرنشین آداماوا (فومبینا) وابسته به خلافت سوکوتو در پایان لشکرکشی‌های 1899-1901 نیروهای استعماری آلمان و انگلیس به دو بخش شد: بخش خاوری (از جمله گاروا، بانیو، مارووا، نگاوندر) به کامرون آلمانی و بخش باختری (پایتخت یولا) به نیجریهٔ شمالی انگلیس پیوست؛ امیر زبیر به تبعید فرستاده شد. با این رویداد ری بوبا (آداماوا (سهم آلمان)) به اداره کامرون آلمانی گذشت.", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["نبرد تیت — طوارق احگار از نیروهای فرانسه شکست خورد", "831143d6"], "d": ["در نبردی که در جریان لشکرکشی کوتنست در 7 مه 1902 نزدیک واحهٔ تیت رخ داد، نیروهای فرانسه طوارق کل احگار را قطعاً شکستند؛ مرکز احگار آبالسا و ایدلس، این بخش درونی صحرا، زیر کنترل الجزایر فرانسه درآمد.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["نیروهای فرانسه درون سرزمین اوبانگی-شاری (خط بامباری-بریا) را گرفتند", "0b9a9f72"], "d": ["لشکرکشی‌های شمالی کنگوی فرانسه در آغاز سده 1900 درون سرزمین اوبانگی-شاری شامل بامباری، باتانگافو، بوسانگوا و بریا را عملاً زیر کنترل گرفت؛ منطقه در 29 دسامبر 1903 رسماً به‌عنوان مستعمرهٔ اوبانگی-شاری سازمان یافت (بخشی از آفریقای استوایی فرانسه).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["سلطان‌نشین دارالکوتی سلطان محمد سنوسی به‌دست نیروهای فرانسه برافتاد", "644b2c3f"], "d": ["سلطان‌نشین دارالکوتی با پایتخت ندله مبتنی بر تجارت برده که در 1897 زیر حمایت فرانسه درآمده بود، چون سلطان محمد سنوسی در برابر اقتدار فرانسه همچنان مقاومت می‌کرد، با لشکرکشی 1911 عملاً برافتاد؛ سنوسی در جنگ کشته شد، سلطان‌نشین در 1912 رسماً برچیده شد.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["فرقهٔ لیوونیا قلمرو کلایپدا (ممل) را به شاخهٔ پروس فرقهٔ توتونی واگذاشت", "e61e5d50"], "d": ["فرقهٔ لیوونیا قلعهٔ کلایپدا (ممل) در دهانهٔ نمان و سرزمین‌های پیرامون آن را به شاخهٔ پروس فرقهٔ توتونی واگذاشت؛ اسقف کورلاند نیز سهم خود را در 1392 به همان شاخه واگذاشت. کلایپدا با صلح‌های 1411 تورون و 1422 ملنو در دست فرقه ماند و در 1525 به دوک‌نشین پروس رسید.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["عمر بیگ قلعهٔ بندری ازمیر را از جنوایی‌ها گرفت", "ab92d96e"], "d": ["عمر بیگ آیدین‌اوغلو قلعهٔ بندری ازمیر را که در دست لاتین‌ها مانده بود دو سال و نیم محاصره کرد. فرماندار جنوایی قلعه، مارتینو زکاریا، قلعه را تسلیم کرد و به ساقز رفت.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["ابراهیم شاه از سوتایی‌اوغولاری بر دیاربکر چیره شد", "179196cf"], "d": ["پس از فروپاشی دولت ایلخانی، ابراهیم شاه از سوتایی‌اوغولاری بر منطقهٔ دیاربکر که صحنهٔ ستیز جلایریان و چوپانیان بود چیره شد؛ فرمانروایی او تا 1353 ادامه یافت.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["برات از بیزانس به دست صرب‌ها افتاد — فتح آلبانی به دست استفان دوشان", "1eba202e"], "d": ["قلعهٔ برات که در 1281 محاصرهٔ آنژویی‌ها را شکسته بود و از آن زمان مرکز واپسین ایالت بیزانس در آدریاتیک بود، هنگام جنگ داخلی بیزانس در پیشروی استفان دوشان به آلبانی به دست صرب‌ها افتاد. پس از تسلیم کرویا در مه یا ژوئن 1343، برات، کانینا و آولونیا (ولوره) در دو سال از آن صرب‌ها شد؛ یوحنا کومننوس آسن، برادرزن دوشان، به سرپرستی ایالت گماشته شد.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["عبدالوادیان (زیانیان) در تلمسان از سلطهٔ مرینیان رهایی یافتند", "a4aa9573"], "d": ["عبدالوادیان در تلمسان به رهبری عثمان دوم و برادرش ابوثابت از سلطهٔ مرینیان رهایی یافتند. این استقلال کوتاه بود.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["بایرام خوجه استقلال خود را به دست آورد — پیدایش بیگ‌نشین قره‌قویونلو", "37964815"], "d": ["بایرام خوجه که نخستین بیگ قره‌قویونلوها شمرده می‌شود، با کشتن آق‌ساقال حسین بیگ، فرمانروای سوتایی‌ها، استقلال خود را به دست آورد. موصل را گرفت و اداره‌ٔ آن را به برادرش بردی خوجه سپرد.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["با مرگ ابراهیم شاه دیاربکر به اداره‌ٔ جلایریان درآمد", "11c338ef"], "d": ["با مرگ ابراهیم شاه سوتایی‌اوغلو که از 1343 بر منطقهٔ دیاربکر چیره بود، منطقه به اداره‌ٔ جلایریان درآمد.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["انز به ادارهٔ جنوا درآمد (خاندان گاتیلوزی)", "5dc12940"], "d": ["انز که در دورهٔ بیزانس شهر بندری مهمی بود در 1355 به ادارهٔ جنوا درآمد و خاندان گاتیلوزی آن را اداره می‌کرد.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["آلگیرداس (اولگرد)، گراندوک لیتوانی، بریانسک را گرفت", "3cad9caf"], "d": ["سپاه آلگیرداس، گراندوک لیتوانی، بریانسک را گرفت. این شهر تا 1500 وابسته به گراندوک‌نشین لیتوانی ماند.", "03107c6d"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["اینانچ‌اوغولاری سلطهٔ گرمیان‌اوغولاری را پذیرفت", "0679db27"], "d": ["بیگ‌نشین اینانچ‌اوغولاری که پیرامون دنیزلی فرمان می‌راند، احتمالاً در 1368 سلطهٔ گرمیان‌اوغولاری را پذیرفت.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["مانوئل، دسپوت سالونیک، منطقهٔ سرس و دراما را به فرمانروایی بیزانس درآورد", "abb99c3e"], "d": ["با کشته‌شدن شاه وکاشین و اوگلیشا، دسپوت سرس، در چیرمن (26 سپتامبر 1371)، فرمانروایی صرب در منطقهٔ سرس پایان یافت. مانوئل دوم پالئولوگوس، شاهزادهٔ بیزانسی که در سالونیک فرمان می‌راند، در نوامبر 1371 سرس و منطقه‌ای را که دراما نیز در آن بود به فرمانروایی بیزانس درآورد. این منطقه در سپتامبر 1383 به عثمانیان رسید.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["با مرگ پیر حسین بیگ، ارزنجان و بایبورت به مطهرتن رسید", "3269e55d"], "d": ["با مرگ پیر حسین بیگ، امیر ارزنجان، ارزنجان و بایبورت به دست مطهرتن، از امیران اِرتنا، افتاد؛ مطهرتن امیر ارزنجان شد.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["تاج‌الدین بیگ سپاه اِرتنا را در نیکسار شکست داد و مستقل عمل کرد", "42982ea7"], "d": ["تاج‌الدین بیگ نیروهای قاضی برهان‌الدین و علاءالدین علی، بیگ اِرتنا، را که در بهار 1379 به نیکسار حمله کرده بودند شکست داد. پرداخت مالیات به بیگ‌نشین اِرتنا را قطع کرد و از سال 781 (1379) مستقل عمل کرد.", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["تیمور خوارزم را قطعی به چنگ آورد", "ef76d2c9"], "d": ["تیمور پس از نخستین لشکرکشی خوارزم در 1371 سه لشکرکشی دیگر ترتیب داد. در لشکرکشی 1379 منطقه را قطعی به چنگ آورد، غارت کرد و با غنیمت فراوان بازگشت.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["تورتکو یکم، پادشاه بوسنی، هرتسگ‌نووی را بنیان نهاد", "1628221a"], "d": ["تورتکو یکم، پادشاه بوسنی، برای آنکه در تجارت نمک با دوبرونیک رقابت کند در خلیج توپلا شهرکی تازه بنیاد نهاد؛ این شهرک بعدها به نام نووی (هرتسگ‌نووی) خوانده شد.", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["تیمور قندهار را از کرت‌ها گرفت و به نوهٔ خود پیر محمد داد", "84760f70"], "d": ["قندهار که از 1281 در دست کرت‌های هرات، دست‌نشاندگان ایلخانان، بود در جریان لشکرکشی‌های تیمور به خراسان گرفته شد و به نوهٔ او پیر محمد داده شد؛ شهر از آن پس به دست والیان تیموری اداره می‌شد.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["خلیل بیگ ذوالقدراوغلو البستان را از ممالیک پس گرفت", "ee3da686"], "d": ["البستان که در 1381 به دست ممالیک افتاده بود در 1384 خلیل بیگ ذوالقدراوغلو پس گرفت.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["تیمور دیاربکر (آمد) را گرفت و غارت کرد", "f8d200a8"], "d": ["تیمور در 25 یا 26 آوریل 1394 دیاربکر را گرفت و شهر را غارت کرد.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["گراردو آپیانی پیزا را به ویسکونتی واگذاشت و سینیوری پیومبینو را بنیان نهاد", "ac45a9dd"], "d": ["گراردو آپیانی، سینیور پیزا، شهر را به 200.000 فلورین به جان گالئاتزو ویسکونتی، فرمانروای میلان، واگذاشت. سینیوری پیومبینو را که از پیومبینو، سوورتو، اسکارلینو و جزایر البا، پیانوزا و مونته‌کریستو ساخته شده بود برای خود نگه داشت.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["دیاربکر به قره‌یولوق عثمان بیگ داده شد — فرمانروایی آق‌قویونلو آغاز شد", "38262401"], "d": ["دیاربکر که تیمور در 1394 گرفته بود در 1401 به قره‌یولوق عثمان بیگ داده شد و بدین‌سان فرمانروایی آق‌قویونلو در منطقه آغاز شد.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["ارزنجان به سلطهٔ قره‌قویونلو درآمد", "5729a50b"], "d": ["پس از مطهرتن، ارزنجان به دست قره یوسف، فرمانروای قره‌قویونلو، افتاد. قره یوسف نخست پیر عمر را که از مورد اعتمادانش بود به فرمانداری شهر گماشت.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["اسکیا محمد زاغا (دیا) را گرفت", "24561a8c"], "d": ["اسکیا محمد که بر تخت سونغای نشسته بود، در پایان سال 899 هجری به‌واسطهٔ برادرش کورمینا-فاری عمر کومزاگو شهر زاغا (دیا) را در غرب دلتای درونی نیجر گرفت.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["شیبانی خان بخارا و سمرقند را گرفت", "8f8f40eb"], "d": ["محمد شیبانی خان با بهره‌گیری از آشوب میان تیموریان بخارا و سمرقند را گرفت و دودمان شیبانیان (ازبکان) را بنیان نهاد. میان 1500 و 1507 تقریباً همهٔ شهرهای ماوراءالنهر، خوارزم و خراسان را به چنگ آورد.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["اسپانیایی‌ها بجایه را اشغال کردند", "8faa0133"], "d": ["سپاه 8000 نفری اسپانیایی که با کشتی آمده بود بجایه را اشغال کرد؛ مردم شهر هراسان شده وطن خود را ترک کردند.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["آگادز به سونغای وابسته شد", "997362b0"], "d": ["آگادز، مرکز منطقهٔ آئیر، به دست اسکیا محمد، سلطان سونغای، به گائو وابسته شد؛ شهر تا نابودی سونغای در توندیبی در 1591 این وابستگی را داشت.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["سلطان‌نشین باگیرمی بنیان نهاده شد", "03829f94"], "d": ["قبیلهٔ کنگا به رهبری بیرنی بسی دولتی نیرومند با مرکزیت ماسینیا (ماسنیا) در شرق دریاچهٔ چاد بنیان نهاد. بنیان‌گذاری دودمان باگیرمی به‌طور سنتی به 1522 تاریخ‌گذاری می‌شود.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["واپسین دوک اسفورتسا درگذشت، میلان به شارل پنجم رسید", "53230b5c"], "d": ["فرانچسکو دوم اسفورتسا، دوک میلان، شب 1-2 نوامبر 1535 بی‌فرزند درگذشت. دوک‌نشین به شارل پنجم، امپراتور، رسید و با یک فرماندار اسپانیایی اداره شد.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["جنوایی‌ها در جزیرهٔ طبرقه سکنی گزیدند", "0cb474f8"], "d": ["بر پایهٔ پیمانی که شارل پنجم با فرمانروای تونس بست و ساختن قلعه در ساحل و صید مرجان را اجازه می‌داد، گروهی جنوایی از پگلی در جزیرهٔ طبرقه اسکان داده شد. جزیره پایگاهی بازرگانی شد که خاندان لوملینی آن را اداره می‌کرد.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["پس از مرگ همایون، صفویان قندهار را از بابریان گرفتند", "318eabc8"], "d": ["پس از مرگ همایون در دهلی در 1556، شاه طهماسب از اختلاف میان والیان بابری در قندهار و زمین‌داور بهره برد؛ یک واحد صفوی به دعوت والی زمین‌داور وارد قندهار شد و طهماسب پسرعمویش سلطان حسین میرزا را به والیگری شهر گماشت. شهر تا 1595 در دست صفویان ماند.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["روسیه به لیوونیا تاخت، دورپات سقوط کرد", "dcb46a8a"], "d": ["ایوان چهارم برای دستیابی به دریای بالتیک به لیوونیا تاخت و جنگ لیوونیا را آغاز کرد؛ ناروا و دورپات (تارتو) را گرفت و روال را محاصره کرد.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["قلعهٔ کارلوواتس بنیان نهاده شد", "9b28e6ad"], "d": ["برای پاسداری از کرواسی و سرزمین‌های موروثی اتریش در برابر عثمانیان، قلعهٔ کارلوواتس در دشت سیلابی میان کوپا و کورانا بنیان نهاده شد؛ قلعه را آرشیدوک کارل دوم، فرمانده مرز نظامی کرواسی، ساخت.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["سند بنیان‌گذاری (اسکان) شهر زاموشچ", "e1157f3b"], "d": ["یان زامویسکی، صدراعظم بزرگ لهستان، سند بنیان‌گذاری (اسکان) شهر زاموشچ را صادر کرد.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["آتش‌بس یام زاپولسکی — لیوونیا و دورپات به لهستان رسید", "7d02d8ad"], "d": ["میان لهستان-لیتوانی و روسیه آتش‌بس یام زاپولسکی امضا شد؛ مسکو از ادعاهای خود بر لیوونیا چشم پوشید و سرزمین‌های پولوتسک را بازگرداند. دورپات (تارتو) از 1582 در دست لهستان ماند.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["قلعهٔ تزاریتسین نخستین بار در سند یاد شد", "ddf65b06"], "d": ["فرمان 2 ژوئیهٔ 1589 تزار فئودور ایوانوویچ از قلعهٔ تزاریتسین که برای پاسداری از مرز جنوبی ولگا ساخته شده بود یاد می‌کند؛ این تاریخ روز بنیان شهر پنداشته می‌شود.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["قلعهٔ ساراتوف بنیان نهاده شد", "a3ca702c"], "d": ["ساراتوف برای پاسداری از راه ولگا و مرزهای شرقی دولت در برابر یورش کوچ‌نشینان، به‌عنوان قلعه-پاسگاه به دست شاهزاده زاسکین بنیان نهاده شد.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["قلعهٔ پلیم بنیان نهاده شد", "baf3e7eb"], "d": ["وویوود پیوتر گورچاکوف در کرانهٔ رود تاودا شهر پلیم را بنیان نهاد؛ این قلعه یکی از پایگاه‌های پیشروی روسیه در سیبری غربی شد.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["قلعهٔ ورخوتوریه بنیان نهاده شد", "81be29bb"], "d": ["در کرانهٔ تورا، به‌جای آبادی کهن نرومکار، دژ ورخوتوریه بنیان نهاده شد؛ بنیان آن با جست‌وجوی راهی کوتاه‌تر به سیبری پیوند دارد.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["قلعهٔ تورینسک در کرانهٔ تورا بنیان نهاده شد", "c1d8534e"], "d": ["در سال 1600 در منطقهٔ کنونی تورینسک قلعهٔ قزاق-یاساک (استروگ) روسی تورینسک بنیان نهاده شد؛ این قلعه از استحکامات میان‌راهی پیشروی روسیه در سیبری غربی است.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["شاه عباس یکم شهر فرح‌آباد را در مازندران بنیان نهاد", "cab4d0fe"], "d": ["عباس یکم، فرمانروای صفوی، در مازندران در جایی نزدیک ساحل خزر شهر فرح‌آباد را بنیان نهاد و مردم را از سراسر کشور در آن اسکان داد. ساخت آن در 1020/1611 آغاز شد.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["قلعهٔ روسی براتسک در کرانهٔ آنگارا بنیان نهاده شد", "e7b4be59"], "d": ["در جریان پیشروی روسیه به سیبری شرقی، قلعهٔ براتسک بر رود آنگارا بنیان نهاده شد.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["پیمان روسکیلده — اسکونه، هالاند، بلکینگه و بورنهولم به سوئد رسید", "afcae41b"], "d": ["پیمان روسکیلده که جنگ نخست کارل گوستاو را پایان داد امضا شد؛ دانمارک-نروژ اسکونه، هالاند، بلکینگه و بورنهولم را به سوئد واگذاشت.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["روسیه قلعهٔ پنزا را در کرانهٔ سورا بنیان نهاد", "49e8d90b"], "d": ["پنزا در محل پیوستگاه رودهای پنزا و سورا به‌صورت قلعه‌ای بزرگ بنیان نهاده شد؛ پس از 1684 انتهای غربی خط دفاعی سیزران را تشکیل داد.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["مارکت مأموریت فرانسوی را در سو سنت ماری بنیان نهاد", "86612bcd"], "d": ["ژاک مارکت، یسوعی، در سرچشمهٔ آبشارهای سو سنت ماری میان دریاچه‌های سوپریور و هورون یک مأموریت بنیان نهاد.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["نخستین پاسگاه شرکت خلیج هادسن (واسکاگانیش) بنیان نهاده شد", "07b32d57"], "d": ["مدار شوار دِ گروزیه در خلیج جیمز، در دهانهٔ رود روپرت، آبادی‌ای را بنیان نهاد که بعدها نخستین پاسگاه شرکت خلیج هادسن شمرده شد.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["ادارهٔ استعماری اسپانیا پیتیک (ارموسیو) را بنیان نهاد", "11e5cc04"], "d": ["ادارهٔ استعماری اسپانیا در جای یک آبادی بومی کهن شهرکی بنیان نهاد؛ این شهرک در 1828 نام خوسه ماریا گونسالس د ارموسیو را گرفت.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["قلعهٔ روسی اومسک در پیوستگاه ایرتیش و اوم بنیان نهاده شد", "13dcce5e"], "d": ["اومسک به‌صورت قلعه‌ای در انتهای شرقی خط استحکامات ایشیم میان توبول و ایرتیش بنیان نهاده شد؛ در 1804 شهر شد.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["جونغارها به لهاسا یورش بردند — لاجانگ خان کشته شد، تبت به اشغال جونغار درآمد", "65beea29"], "d": ["سپاه جونغار به فرماندهی تسرینگ دوندوب پس از نیمه‌شب از هر سو به لهاسا که لاجانگ خان، فرمانروای خوشوت، از آن دفاع می‌کرد حمله برد؛ جونغارها با یاری‌ای که از درون یافتند شهر را گرفتند و غارت کردند و پوتالا را نیز تاراج کردند. لاجانگ خان هنگام گریز کشته شد؛ جونغارها به سرپرستی تاگ‌تسه‌پا دولتی عروسکی در تبت برپا کردند.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["سپاه چینگ وارد لهاسا شد — اشغال جونغار پایان یافت، حمایت چینگ آغاز شد", "083358c1"], "d": ["از دو سپاهی که کانگشی به تبت فرستاد، ستون سیچوان به فرماندهی گالبی با راهپیمایی سخت به لهاسا رسید و شهر را بی‌مقاومت گرفت؛ جونغارها همهٔ نیروهای خود را در دام در برابر سپاه کوکونور که از شمال می‌آمد گرد آورده بودند. با عقب‌نشینی جونغارها از تبت، چینگ در لهاسا نظام حمایتی پایدار برقرار کرد.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["لشکرکشی آگوایو پرزیدیوی لوس آدائس را بنیان نهاد", "2031793a"], "d": ["لشکرکشی مارکی آگوایو در لوس آدائس یک پرزیدیو (پاسگاه نظامی) بنیان نهاد و مأموریت را دوباره اسکان داد؛ این پاسگاه در برابر لوئیزیانای فرانسوی، مرز اسپانیای نو در تگزاس شرقی شد.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["پاسگاه روسی کاینسک در دشت بارابا بنیان نهاده شد", "b14552a8"], "d": ["از سه استحکام پایدار روسی که در دشت بارابا ساخته شد، پاسگاه کاینسک در میانهٔ بستر رود اوم، جایی که جویبار کاینکا به آن می‌پیوندد، بنیان نهاده شد.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["قلعهٔ روسی تروئیتسک در کرانهٔ رود اوی بنیان نهاده شد", "623d75f2"], "d": ["تروئیتسک در جایی که اوولکا به رود اوی می‌پیوندد به‌صورت قلعه بنیان نهاده شد و در 1784 منشور شهری یافت.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["با فرمان الیزابت، گمرک تمرنیک در دهانهٔ دُن بنیان نهاده شد (هستهٔ روستوف)", "46519168"], "d": ["الیزابت پتروونا، امپراتریس، فرمان ساخت گمرکی را در دهانهٔ رود تمرنیک بر دُن صادر کرد؛ گمرک تمرنیک آغاز تاریخ اولیهٔ شهر روستوف-نا-دونو است.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["فرانسوی‌ها پاسگاه تجاری‌ای در تورنتو بر رود هامبر بنیان نهادند", "18975f4c"], "d": ["فرانسوی‌ها پاسگاه دومی بر رود هامبر بنیان نهادند؛ سال بعد قلعهٔ رویه را در محل کنونی اکسیبیشن پلیس ساختند.", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["محمدحسن خان قاجار استقلال خود را اعلام کرد؛ مازندران و گیلان را گرفت", "42fc62e8"], "d": ["با برکناری سلیمان شاه افشار، محمدحسن خان، رئیس قاجار در استرآباد، استقلال خود را اعلام کرد؛ جز استرآباد و گرگان، مازندران و گیلان را نیز زیر اداره‌ٔ خود گرفت.", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["احمدشاه درانی بلخ را به کشور خود افزود", "12c6bbf1"], "d": ["احمدشاه درانی، فرمانروای افغان، بلخ را به قلمرو حاکمیت خود افزود.", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["کریم خان زند بر اصفهان چیره شد — فرمانروایی افشاری در ایران جای خود را به اداره‌ٔ زند داد", "73cdc1e8"], "d": ["پس از مرگ نادرشاه (1747)، اصفهان و عراق عجم به نام شاهان افشار، عادل‌شاه (6 ژوئیه 1747) و ابراهیم‌شاه (8 دسامبر 1748)، اداره می‌شد. کریم خان زند در ژانویهٔ 1751 به اصفهان بازگشت و بر اوضاع چیره شد. خراسان زیر فرمان شاهرخ در دست افشاریان ماند.", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["قلعهٔ روسی پتروپاولوفسک در کرانهٔ ایشیم بنیان نهاده شد", "5d16ef42"], "d": ["پتروپاولوفسک به‌صورت قلعه‌ای روسی بنیان نهاده شد و در زمانی کوتاه به مرکز مهم تجارت میان روسیه و آسیای میانه و دشت قزاق بدل شد.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["طوارق آگادز نمکزار بیلما را از کانم-برنو گرفتند", "1a563a74"], "d": ["کانم-برنو که در سدهٔ 18 دچار فروپاشی بود، هنگامی که در 1759 طوارق آگادز نمکزار بیلما را از دستش گرفتند، بسیاری از آبادی‌های خود را در صحرا از دست داد.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["محمدحسن خان قاجار از سپاه کریم خان زند شکست خورد و کشته شد؛ استرآباد، مازندران و گیلان به اداره‌ٔ زند درآمد", "38f0a375"], "d": ["سپاه کریم خان قاجاران را به سختی شکست داد؛ محمدحسن خان هنگام گریز کشته شد و پسرش آقامحمد را به شیراز بردند. سرزمین‌های بیگ‌نشین قاجار در کرانهٔ خزر به اداره‌ٔ زند درآمد.", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["سپاه جهاد عثمان بن فودی زاریا را گرفت", "41279ca7"], "d": ["در جهادی که عثمان بن فودی آغاز کرد، نخستین حمله به الکالاوا، پایتخت گوبیر، ناکام ماند ولی در 1806 زاریا گرفته شد.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["شهر سلطان‌آباد (اراک) بنیان نهاده شد", "674237a0"], "d": ["در دورهٔ قاجار، ژنرال یوسف خان گرجی شهر کنونی اراک را بنیان نهاد و نام سلطان‌آباد بر آن نهاد.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["شهرک بوفورت (بوفورت غربی) بنیان نهاده شد", "c5cb1776"], "d": ["در مستعمرهٔ دماغهٔ امید نیک بریتانیا، بر مزرعهٔ هویفلاکته در کارو، شهرک بوفورت بنیان نهاده شد.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["بلخ به اشغال امیر بخارا درآمد", "cd255a5d"], "d": ["بلخ که زیر حاکمیت درانی افغان بود، در 1826 به اشغال امیر بخارا درآمد؛ شهر در 1841 دوباره به دست افغان‌ها گرفته شد.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["روسیه قلعهٔ آکمولا را بر رود ایشیم بنیان نهاد", "6c727ca9"], "d": ["روسیه با ساختن قلعهٔ آکمولا در کاراوتکول بر رود ایشیم، آنجا را شهر مرکزی سرزمین قرقیزهای سیبری (قزاق‌ها) کرد.", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["استحکام کوپال بنیان نهاده شد — پیوستن هفت‌رود (ژتی‌سو) شمالی به روسیه آغاز شد", "8d4c24c6"], "d": ["روسیه به درخواست قزاق‌های ژوز بزرگ، استحکام کوپال را در دامنهٔ آلاتائوی هفت‌رود بنیان نهاد. به گفتهٔ منبع، این کار پیوستن هفت‌رود شمالی تا رود ایلی را به روسیه آسان کرد.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["بازرگانان ساحلی در کازه (تابورا) سکنی گزیدند", "173223b0"], "d": ["پس از درگیری با یک فرمانروای محلی، بازرگانانی که از ساحل آفریقای شرقی آمده بودند به جنوب کوچیدند؛ فوندیکیرا، رئیس اونیانیمبه، نزدیک ایتتمیا به آنان جای سکونت داد. این آبادی هستهٔ مرکز کاروانی تابورا شد.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["فولانی‌های حاج عمر جنه را گرفتند", "aa4e37f8"], "d": ["جنه که دولت ماسینا در آن پادگان داشت در 1861 به دست فولانی‌های زیر فرمان حاج عمر افتاد.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["حاج عمر حمداللهی را گرفت — پایان دولت ماسینا", "542f1c0d"], "d": ["نیروهای متحد ماسینا که بینا علیِ گریخته از سگو به آنها پناه برده بود شکست خوردند؛ حمداللهی، مرکز ماسینا، به دست حاج عمر افتاد و بینا علی و احمدو احمدو اعدام شدند.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["برازا شهر فرانسویل را بنیان نهاد", "d28410d7"], "d": ["پیر ساورنیان دو برازا بر برآمدگی صخره‌ای مشرف بر رود امپاسا به نام فرانسه پاسگاه فرانسویل را بنیان نهاد.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["قرارداد مرزی دولت آزاد کنگو و پرتغال — کرانهٔ جنوبی دهانهٔ کنگو به پرتغال", "08a16627"], "d": ["با قراردادی که هنگام برگزاری کنفرانس برلین امضا شد، مرز میان دولت آزاد کنگو و پرتغال از دهانهٔ رود کنگو (زئیر) تا جویبار اوآنگو-اوآنگو خود رود تعیین شد؛ کرانهٔ جنوبی که سویو در آن است به پرتغال و کابیندا در شمال رود به پرتغال ماند.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["ساحل حضرموت (مکلا) به حمایت بریتانیا درآمد", "dc824725"], "d": ["میان یافعی‌ها (قعیطی‌ها) که بر ساحل حضرموت، از جمله شحر و مکلا، چیره بودند و بریتانیا پیمان حمایت امضا شد؛ بریتانیایی‌ها روابط خارجی ادارهٔ یافعی در ساحل را یکسره بر عهده گرفتند.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["فرانسوی‌ها بر سراسر جولوف چیره شدند", "c6d28eaa"], "d": ["فرانسوی‌ها که با توافق با رؤسای قبایل منطقه را مستعمره کردند در 1890 بر سراسر جولوف چیره شدند.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["جنه به اشغال فرانسوی‌ها درآمد", "b207bf62"], "d": ["جنه که در دست دولت حاج عمر بود در 1893 به دست نیروهای فرانسوی اشغال شد و به سودان فرانسه پیوست.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["گورو به‌صورت پاسگاه نظامی بنیان نهاده شد", "bd37b323"], "d": ["شهر گورو در بخش میانی زیمبابوهٔ کنونی به‌صورت پاسگاه نظامی بنیان نهاده شد؛ بعدها مرکز کشاورزی شد و در 1914 مقام شهرداری یافت.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["سلطان‌نشین باگیرمی به حمایت فرانسه درآمد", "59f20c32"], "d": ["گاوْرانگ، فرمانروای باگیرمی، در برابر تهدید رابح پیمان حمایتی اجباری با فرانسه بست. هنگامی که رابح در واکنش به این کار به اشغال باگیرمی روی آورد، گاوْرانگ پایتخت ماسینیا را با دست خود به آتش کشید.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["پادشاهی کافا به حبشه پیوست — واپسین پادشاه گاکی شروچو اسیر شد", "c03c44c5"], "d": ["نیروهای منلیک دوم به فرماندهی راس والدا گیورگیس در مارس 1897 وارد کافا شدند. پس از درگیری‌های سخت کافا فتح شد؛ واپسین پادشاه، گاکی شروچو، در اکتبر 1897 دستگیر شد و تسلیم گردید.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["گائو به اشغال فرانسوی‌ها درآمد", "01eabb4c"], "d": ["گائو، پایتخت کهن سونغای در کرانهٔ نیجر، در 1898 به دست فرانسوی‌ها اشغال شد؛ پس از اشغال شهر دوباره رشد کرد و مرکز منطقه شد.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["انبار تدارکاتی نایروبی برای راه‌آهن اوگاندا بنیان نهاده شد", "a3ce3389"], "d": ["بریتانیایی‌ها در جایی که اکنون نایروبی است و تا آن زمان بیشتر باتلاقی خالی از سکنه بود، انبار تدارکاتی راه‌آهن اوگاندا را که مومباسا را به اوگاندا می‌پیوست بنیان نهادند.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["آداماوا تقسیم شد — یولا در نیجریهٔ شمالی بریتانیا ماند", "11104686"], "d": ["آداماوا میان نیجریهٔ شمالی وابسته به بریتانیا و کامرون وابسته به آلمان تقسیم شد؛ بوبو احمدو، چهارمین پسر آداما، در بخش بریتانیایی امیر یولا شد.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["نبرد بورمی — حاکمیت سیاسی خلافت سوکوتو پایان یافت", "c7d87e2c"], "d": ["خلیفه محمد طاهر که پس از اشغال سوکوتو به دست بریتانیایی‌ها گریخته بود، در جنگی تازه با بریتانیایی‌ها کشته شد؛ حاکمیت سیاسی خلافت سوکوتو که نزدیک به یک سده پایید پایان یافت.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["ناکورو رسماً به‌صورت شهرک بنیان نهاده شد", "d82a2d76"], "d": ["ناکورو به لطف جایگاهش بر راه‌آهن اوگاندا رسماً به‌صورت شهرک بنیان نهاده شد و مرکز فرآورده‌های کشاورزی منطقه شد.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["ایستگاه دریای آرال بر راه‌آهن اورنبورگ-تاشکند گشوده شد — آبادی آرالسک بنیان نهاده شد", "85803dcb"], "d": ["هنگامی که راه‌آهن امپراتوری روسیه میان اورنبورگ و تاشکند از انتهای شمال‌شرقی دریای آرال می‌گذشت، در ساحل ایستگاه «آرالسکویه موره» گشوده شد؛ در کنار ایستگاه آبادی ماهیگیری پدید آمد. این آبادی در 1938 مقام شهری یافت و نام آرالسک گرفت.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["فرانسوی‌ها ابشه را گرفتند — پایان سلطان‌نشین وادای", "3c9b117b"], "d": ["فرانسوی‌ها که پیشروی به سوی شرق را ادامه می‌دادند ابشه، پایتخت وادای، را گرفتند و به سلطان‌نشین وادای پایان دادند؛ واپسین سلطان بی‌آنکه بتواند پایتخت را نجات دهد عقب نشست.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["اتحادیهٔ آفریقای جنوبی بنیان نهاده شد", "7434a47f"], "d": ["بر پایهٔ قانون آفریقای جنوبی مصوب 1909، مستعمره‌های کیپ، ناتال، ترانسوال و رود اورانژ در 31 مه 1910 با نام اتحادیهٔ آفریقای جنوبی وابسته به امپراتوری بریتانیا یکی شدند؛ مرکز اجرایی پرتوریا و مرکز قانون‌گذاری کیپ‌تاون شد. با این یکی‌شدن شهرهای مستعمره‌های کیپ، ناتال، ترانسوال و اورانژ (کیمبرلی، دوربان، پیترماریتسبورگ، پوچفستروم، پورت الیزابت و جز آن) به اتحادیهٔ آفریقای جنوبی رسید.", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["فرانسوی‌ها جانت را اشغال کردند", "f32997c8"], "d": ["جانت، ناحیهٔ عثمانی وابسته به غات، در 1911 به دست فرانسوی‌ها اشغال شد. مدیر ناحیه، شیخ آمود، تا این تاریخ از دولت عثمانی حقوق گرفته بود.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["انکوریج به‌عنوان مرکز راه‌آهن آلاسکا بنیان نهاده شد", "f5014711"], "d": ["پس از تصویب قانون راه‌آهن آلاسکا از سوی کنگره در 12 مارس 1914، در بهار 1915 کمیسیون مهندسی آلاسکا کارگاه راه‌آهن را در شیپ کریک برپا کرد؛ در ساحل شهری چادری پدید آمد و در آوریل 1915 ادارهٔ پست نام انکوریج را بر شهرک تازه نهاد. شهر مرکز راه‌آهن آلاسکا شد که تا فیربنکس در شمال امتداد داشت.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["پیوستن مرکز بیابانی سنوسیه، جغبوب، به نظام عثمانی — فرمان معافیت عبدالمجید", "039fce6d"], "d": ["محمد بن علی سنوسی که سال‌ها در مکه ماند، پس از بازگشت به طرابلس غرب در واحهٔ جغبوب در مرز مصر ساکن شد و بر صخره‌ای مسلط زاویه‌ای بزرگ ساخت؛ جایی که از چند آلونک بیش نبود در مدتی کوتاه به شهر بدل شد. در 1856 با فرمان سلطان عبدالمجید املاک وابسته به پیروان طریقت از مالیات معاف شد و به مریدان اختیار گردآوری زکات داده شد. این فرمان واحه‌ای را که بر سر راه کاروان‌رو متصل‌کنندهٔ غرب آفریقا و سودان به قاهره بود به بخشی از نظام مالی و اداری عثمانی بدل کرد و جغبوب را به‌عنوان مرکز تجاری نیرومند ساخت. وابستگی مردم منطقه به خلیفه با سفرنامهٔ میرالای صادق المؤید که در 1884 و 1893 از آنجا گذشت نیز تأیید می‌شود.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["آغاز کندن کانال سوئز و برپایی پورت‌سعید", "cef0be8d"], "d": ["کارهای حفاری طرح لسپس که باب عالی در 5 ژانویه 1856 تأیید کرده بود، در 25 آوریل 1859 آغاز شد؛ کانال ده سال بعد، در 16 نوامبر 1869، تکمیل می‌شد. در انتهای مدیترانه‌ای حفاری، در نوار ساحلی میان دریاچهٔ منزله و دریا، روستای آلونکی پنج‌خانه‌ای که برای کارگران برپا شد هستهٔ پورت‌سعید را ساخت. به شهر از سوی مسئولان شرکت کانال در 1860 به یاد سعید پاشا، والی وقت مصر، این نام به معنای «بندر سعید» داده شد. بدین‌سان در نقشهٔ عثمانی در نواری ساحلی که پیشتر هیچ سکونتگاهی در آن نبود بندری نو زاده شد.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["دیدار سلطان عبدالعزیز از مصر و برپایی اسماعیلیه در برزخ سوئز", "bcfacf38"], "d": ["سلطان عبدالعزیز با تشویق صدراعظم یوسف کامل پاشا در 3 آوریل 1863 به مصر رفت و با تظاهرات بزرگی پذیرفته شد؛ هدف استوار کردن وابستگی ولایتی به مرکز بود که از شورش کاواللی محمدعلی پاشا عملاً به صورت دولتی جداگانه درمی‌آمد. در همان سال در برزخ، در تپه‌های تلال‌الجسر کنار دریاچهٔ تمساح، مرکز اداری شرکت کانال برپا شد: نخست برای مهندسان روستای قریةالتمساح و سپس برای کارگران روستای قریةالعرب مستقر شد. چون خدیو اسماعیل پاشا از نزدیک به کانال آب شیرین علاقه نشان داد و در این تپه برای خود کوشکی ساخت، سکونتگاه به نام او اسماعیلیه خوانده شد. برپایی شهر به سال 1863 تاریخ می‌خورد؛ روز دقیقش معلوم نیست.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["والی‌گری مدحت پاشا در بغداد و اسکان عشایر — برپایی رمادی و ناصریه", "0fa98f06"], "d": ["مدحت پاشا که از ریاست شورای دولت برکنار و از استانبول دور شد، ولایت بغداد را که موصل و بصره را نیز دربر می‌گرفت، در 1869-1872 با اختیارات گسترده و با فرماندهی ارتش ششم نیز در دست، اداره کرد. قانون‌نامهٔ اراضی و قانون ولایت نو را در آنجا اجرا کرد، زمین‌ها را با سند ثبت (تاپو) توزیع کرد و عشایر کوچ‌نشین را به زندگی یکجانشین و اقتدار دولت پیوست. حاصل این سیاست اسکان بود که در 1869 در کنار فرات برای عشیرهٔ دلیم رمادی و در جنوب به دست متصرف منتفک ناصر پاشا سعدون ناصریه برپا شد؛ هر دو در نقطه‌هایی که تا آن روز سکونتگاهی نداشت زاده شدند و در همین تاریخ نخستین بار به نقشه آمدند.", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["کنراد دوم به پادشاهی آلمان برگزیده شد و در ماینتس تاج بر سر نهاد — سلسلهٔ سالی آغاز شد", "c88123e8"], "d": ["پس از مرگ هاینریش دوم، شاهزادگان آلمان در 4 سپتامبر 1024 در کامبا در کرانهٔ راست راین گرد آمدند؛ انتخاب را آریبو، اسقف اعظم ماینتس، رهبری کرد. کنراد بزرگ‌تر بر خواهرزادهٔ جوان خود کنراد پیروز شد و در جشن زایش مریم (8 سپتامبر) در ماینتس به دست آریبو به‌عنوان پادشاه تاج‌گذاری کرد.", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["امپراتور کنراد دوم در اوترشت درگذشت", "f967406b"], "d": ["کنراد دوم، نخستین امپراتور سلسلهٔ سالی، در 4 ژوئن 1039 پس از بیماری کوتاه و دردناک در اوترشت درگذشت.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["کنکوردات وورمس — نزاع اینوستیتور (انتصاب) پایان یافت", "8073e4a0"], "d": ["صلح میان امپراتور هاینریش پنجم و پاپ کالیکستوس دوم، با میانجی‌گری هیئت پاپی، در 23 سپتامبر 1122 در وورمس (در لوبویزن، در کنار شهر) اعلام شد. هاینریش از انتصاب با انگشتر و عصا دست کشید و انتخاب قانونی اسقفان و رؤسای دیرها را پذیرفت.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["امپراتور هاینریش پنجم در اوترشت درگذشت", "790cadc4"], "d": ["امپراتور هاینریش پنجم در 23 مه 1125 در اوترشت درگذشت؛ به‌عنوان امپراتور کنکوردات وورمس (1122) یاد می‌شود.", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["فریدریش یکم بارباروسا در فرانکفورت پادشاه آلمان برگزیده شد", "b91f29a3"], "d": ["شاهزادگان فریدریش را در 5 مارس 1152 در فرانکفورت به پادشاهی برکشیدند؛ در 9 مارس در آخن تاج‌گذاری کرد. دورهٔ بارباروسای سلسلهٔ هوهن‌اشتاوفن بدین‌سان آغاز شد.", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus — اتریش دوک‌نشین شد، بایرن به هاینریش شیر داده شد", "a64c125b"], "d": ["با حکم شاهزادگان در رگنسبورگ، اتریش به دوک‌نشین برکشیده شد و به هاینریش یاسومیرگوت حقوق ویژه داده شد؛ در همان سامان هاینریش بایرن را به امپراتور بازگرداند و امپراتور بایرن را به عنوان لِهن به هاینریش شیر داد.", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["با خاموشی تبار تسرینگن، برن شهر امپراتوری آزاد شد", "1473c219"], "d": ["چون سلسلهٔ تسرینگن در 1218 خاموش شد، برن به شهر آزادِ مستقیماً وابسته به امپراتوری بدل شد؛ در 1353 به‌عنوان هشتمین عضو به کنفدراسیون سوئیس پیوست.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["لانتگراف‌نشین هسن: هاینریش یکم برابانتی نخستین لانتگراف هسن شد، صلح با مایسن 1264", "57067f04"], "d": ["تاریخ هسن به‌عنوان سرزمینی مستقل با هاینریش یکم («کودک») آغاز می‌شود؛ صلح با مایسن در 1264 بسته شد. هاینریش در کاسل دژی ساخت و آنجا در سال‌های بعد اقامتگاه معمول او شد؛ در 1292 به شاهزادگی امپراتوری (Reichsfürstenstand) پذیرفته شد.", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["کنت‌نشین شورین با پیمان به دست آلبرشت دوم، دوک مکلنبورگ، افتاد", "013b6860"], "d": ["آلبرشت دوم با قراردادی در 1 دسامبر 1358 و پرداخت 10.000 مارک نقره به کنت نیکولاوس کنت‌نشین شورین را گرفت؛ شهر از آن تاریخ سرزمین دوک‌نشین مکلنبورگ شد (جاافتادن آن به‌عنوان پایتخت در سدهٔ 16 پایدار شد).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["لانتگراف فیلیپ «بخشنده» در کاسل درگذشت — هسن میان چهار پسرش تقسیم شد", "c0cb27ed"], "d": ["فیلیپ یکم، لانتگراف هسن، از رهبران سیاسی اصلاح دینی، در 31 مارس 1567 در کاسل درگذشت. بر پایهٔ وصیت 1562 کشور به صورت هسن-کاسل (ویلهلم چهارم)، هسن-ماربورگ (لودویگ چهارم)، هسن-راینفلس (فیلیپ دوم) و هسن-دارمشتات (گئورگ) میان چهار پسرش بخش شد؛ لانتگراف‌نشین یکپارچهٔ هسن بدین‌سان پایان یافت.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["واپسین دوک پومرانیا، بوگیسلاو چهاردهم، در اشتتین درگذشت — سلسلهٔ گریفین پایان یافت", "ab96746a"], "d": ["بوگیسلاو چهاردهم، واپسین دوک پومرانیا، در 10 مارس 1637 در اشتتین درگذشت و با او سلسلهٔ بومی پومرانیا خاموش شده است. تقسیم عملی دوک‌نشین (براندنبورگ-سوئد) با صلح وستفالی 1648 ثبت شد.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["فردیناند سوم به برمن امتیازهای شهر امپراتوری آزاد را داد", "174142ee"], "d": ["امپراتور فردیناند سوم در 1646 امتیازهای شهر امپراتوری آزاد را به برمن شناخت؛ سوئد با این مخالفت کرد و در 1666 کوشید شهر را با سلاح مطیع کند و ناکام ماند. چون انتخاب‌کنندهٔ هانوفر اسقف‌نشین اعظم را گرفت (1720)، برمن را به‌عنوان شهر آزاد شناخت.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["برمن به امپراتوری فرانسه پیوست — مرکز دپارتمان دهانه‌های وزر شد", "d5d149ae"], "d": ["برمن در 1806 به دست فرانسوی‌ها گرفته شده بود و از 1810 تا 1813 مرکز دپارتمان دهانه‌های وزر (Bouches-du-Weser) بوده است.", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["ناپلئون لوبک را به امپراتوری فرانسه پیوست", "1ca78afe"], "d": ["پس از تسلیم بلوشر در نوامبر 1806 نزدیک لوبک، شهر به دست فرانسوی‌ها غارت شده بود و در دسامبر 1810 ناپلئون شهر را به امپراتوری خود پیوست. لوبک تا این تاریخ از 1226 شهر امپراتوری آزاد بود.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["لوبک بر ضد فرمانروایی فرانسه شورید و جایگاه شهر آزاد را بازپس گرفت", "84e70d49"], "d": ["لوبک که در 1813 بر ضد اداره فرانسوی شورید، در 1815 به دست کنگرهٔ وین به‌عنوان شهر آزاد و هانزایی کنفدراسیون آلمان شناخته شده است.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["فرمانروایی فرانسه پایان یافت — برمن جایگاه شهر آزاد را بازپس گرفت", "4afa71be"], "d": ["ماندن برمن به‌عنوان مرکز دپارتمان دهانه‌های وزر زیر اداره فرانسه در 1813 پایان یافت؛ شهر در 1815 به دست کنگرهٔ وین به استقلال رسید و به کنفدراسیون آلمان پیوست.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["دوک‌نشین مکلنبورگ-شورین عنوان دوک‌نشین بزرگ گرفت", "3f5d05eb"], "d": ["فریدریش فرانتس یکم، دوک مکلنبورگ-شورین، در 1815 عنوان دوک‌نشین بزرگ («großherzogliche Würde») را گرفت؛ شناسنامهٔ دوک‌نشین مکلنبورگ (1348-1815) در این نقطه پایان می‌یابد و کشور در کنفدراسیون آلمان به‌عنوان دوک‌نشین بزرگ ادامه می‌یابد.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["قانون هامبورگ بزرگ به اجرا درآمد — جایگاه ایالت مستقل لوبک پایان یافت", "6df2f92a"], "d": ["قانون هامبورگ بزرگ که در 26 ژانویه 1937 صادر شده بود، در 1 آوریل 1937 به اجرا درآمد؛ لوبک خودمختاری بیش از 700 ساله را از دست داد و به ایالت شلزویگ-هولشتاین پروس پیوست و مرزهای هامبورگ گسترد.", "b96594d2"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["باراکوا بنیان نهاده شد — نخستین شهرک فتح اسپانیایی کوبا", "8c033cf1"], "d": ["دیه‌گو ولاسکس د کوئیار با نیرویی که از هیسپانیولا گذراند در 1511 فتح کوبا را آغاز کرد و نخستین شهرک اسپانیایی جزیره، نوئسترا سنیورا د لا آسونسیون د باراکوا، را بنیان نهاد. باراکوا در بیست سال بعد پایگاه لشکرکشی‌ها به مکزیک (ارناندس د کوردوبا، گریخالوا، کورتس) شد.", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["نبرد Centla — بیگ‌نشین مایای Potonchán سقوط کرد، Santa María de la Victoria بنیان نهاده شد", "8489a7d8"], "d": ["ناوگان Cortés که از کوبا برآمده بود در Potonchán، شهر مایای Chontal در دهانهٔ رود Grijalva، پیاده شد. اسپانیایی‌ها که در نبرد دشت Centla با برتری سواره‌نظام و سلاح گرم پیروز شدند، به‌جای شهر شهرک Santa María de la Victoria را بنیان نهادند. این نخستین آبادی پایدار اسپانیایی در سرزمین اصلی مکزیک است؛ Malintzin (doña Marina) که مترجم Cortés خواهد شد از جمله پیشکشی‌هایی بود که اینجا داده شد.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Panamá بنیان نهاده شد — نخستین شهر اروپایی در ساحل اقیانوس آرام", "c0d86c22"], "d": ["Pedrarias Dávila، فرماندار Darién، شهر Panamá را در سوی اقیانوس آرام باریکه بنیان نهاد و اداره‌ٔ استعماری را از ساحل کارائیب به اینجا برد. شهر بندر آغاز لشکرکشی‌های اکتشاف و فتح به سوی جنوب شد؛ لشکرکشی‌های Francisco Pizarro به Peru از اینجا تجهیز شد.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["گرفتن Tepeaca — نخستین فتح Cortés پس از «شب اندوه»", "a9c27711"], "d": ["Cortés که شب 30 ژوئن 1520 (Noche Triste) با خسارت سنگین از Tenochtitlan عقب نشسته بود، پس از پناه‌بردن به Tlaxcala نخستین حمله‌اش را به بیگ‌نشین Tepeaca وابسته به اتحاد سه‌گانه کرد. شهر را گرفت و شهرکی اسپانیایی به نام Segura de la Frontera بنیان نهاد؛ بدین‌سان راه میان ساحل Veracruz و Tlaxcala تأمین شد و پایگاه راهپیمایی دوم به سوی پایتخت آماده گردید.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["San Sebastián de Colima بنیان نهاده شد — گشایش Nueva España به ساحل اقیانوس آرام", "30332cab"], "d": ["Gonzalo de Sandoval، از فرماندهان Cortés، دره Colima را در غرب مکزیک مطیع ساخت و شهرک San Sebastián de Colima را بنیان نهاد. این شهرک یکی از نخستین پایگاه‌های Nueva España در ساحل اقیانوس آرام شد و در سال‌های بعد کشتی‌سازی‌های لشکرکشی‌های اکتشافی «دریای جنوب» را تأمین کرد.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["San Francisco de Quito بنیان نهاده شد — نظم اسپانیایی در پایتخت شمالی اینکا", "7bb9f316"], "d": ["Rumiñahui، ژنرال اینکا، پیش از سپردن Quito، پایتخت شمال، به اسپانیایی‌ها آن را به آتش کشید. Sebastián de Benalcázar بر ویرانه‌ها San Francisco de Quito را بنیان نهاد؛ بدین‌سان پس از Cuzco دومین مرکز دولت اینکا نیز زیر اداره‌ٔ اسپانیا درآمد و فتح در Andes شمالی از اینجا پیش برده شد.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Lima بنیان نهاده شد — پایتخت Peru اسپانیایی به دره Rimac رفت", "1f15658c"], "d": ["Francisco Pizarro چون Cuzco در کوهستان از پیوند دریایی با اسپانیا دور بود، Ciudad de los Reyes (Lima) را در دره Rimac در ساحل بنیان نهاد. شهر در زمانی کوتاه پایتخت نایب‌السلطنه‌نشین Peru و مرکز فرمانروایی اسپانیا در آمریکای جنوبی شد.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Popayán بنیان نهاده شد — پل میان Quito و سرزمین Muisca", "bf451979"], "d": ["Benalcázar که از Quito به شمال می‌رفت، Popayán را در دره Cauca بنیان نهاد. شهر انتهای شمالی پیشروی اسپانیایی‌ها از Peru شد و راه رویارویی او با Quesada در سرزمین Muisca را در سال بعد گشود.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["گرفتن Hunza — شکست zaque Quemuenchatocha", "e8c1b661"], "d": ["Gonzalo Jiménez de Quesada که از رود Magdalena به فلات برآمده بود، Hunza، مرکز zacazgo یکی از دو سر کنفدراسیون Muisca، را در هم کوبید و zaque Quemuenchatocha را اسیر کرد. طلایی که در شهر به دست آمد غنیمت اصلی شد که شایعهٔ El Dorado را دامن زد؛ نیمهٔ شمالی سرزمین Muisca بدین‌سان به سلطهٔ اسپانیا درآمد.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Asunción بنیان نهاده شد — پایگاه اسپانیایی بر رود Paraguay", "9a6dfa42"], "d": ["چون لشکرکشی Río de la Plata در Buenos Aires پایدار نماند، اسپانیایی‌ها به بالادست رود عقب نشستند و Juan de Salazar de Espinosa با تکیه بر اتحاد با جوامع Guaraní، Nuestra Señora de la Asunción را بنیان نهاد. این شهرک تا یک سده مرکز فرمانروایی اسپانیا در حوضهٔ Río de la Plata ماند.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Santa Fe de Bogotá بنیان نهاده شد — پایتخت اسپانیایی در سرزمین Muisca", "3ed6c301"], "d": ["Quesada، Santa Fe de Bogotá را کنار Bacatá، مرکز zipa، بنیان نهاد. بی‌درنگ پس از بنیان، ستون‌های فتح که از سه سو آمده بودند — Quesada، Benalcázar و فرمانده آلمانی Federmann — در همان فلات به هم رسیدند و توافق کردند که ادعاهای خود را در اسپانیا فیصله دهند. شهر پایتخت پادشاهی Nueva Granada شد.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["San Juan de la Frontera de Huamanga بنیان نهاده شد — قفل راه Lima-Cuzco", "3f1cfdbf"], "d": ["مقاومتی که Manco Inca از Vilcabamba پیش می‌برد راه میان Lima و Cuzco را می‌بست. Francisco Pizarro برای تأمین این راه San Juan de la Frontera de Huamanga را در میانهٔ دو پایتخت بنیان نهاد؛ «frontera» (مرز) در نام شهرک مستقیماً مقصود بنیان را می‌گوید.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Tunja به‌صورت شهری اسپانیایی از نو بنیان نهاده شد", "c3a12867"], "d": ["پس از بازگشت Quesada به اسپانیا، Gonzalo Suárez Rendón شهر Tunja را به شیوهٔ اسپانیایی در جای Hunza، مرکز zaque، از نو بنیان نهاد. بدین‌سان نیمهٔ شمالی سرزمین Muisca همچون Bogotá به نظام پایدار شهرداری و encomienda وابسته شد.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["San Francisco de Campeche بنیان نهاده شد — سومین و پایدارترین کوشش فتح Yucatán", "62af9901"], "d": ["Francisco de Montejo (پسر) پس از دو لشکرکشی ناکام برای گرفتن Yucatán، شهرک San Francisco de Campeche را در جای شهر مایای Can Pech بنیان نهاد. این بندر پایگاه تدارکاتی نیروهایی شد که به درون شبه‌جزیره می‌رفتند و آغازگاه لشکرکشی‌ای را ساخت که دو سال بعد به بنیان Mérida انجامید.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Santiago del Nuevo Extremo بنیان نهاده شد — فتح شیلی آغاز شد", "04cd7c3b"], "d": ["Pedro de Valdivia که از Peru به جنوب می‌رفت Santiago del Nuevo Extremo را در دره Mapocho بنیان نهاد. شهرک در سپتامبر همان سال با حملهٔ بومیان به رهبری Michimalonco سوزانده و از نو بنیان نهاده شد؛ با این‌همه فتح اسپانیایی شیلی از همین نقطه پیش برده شد.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["بیگ‌نشین Cocom در Sotuta به سلطهٔ اسپانیا درآمد", "db6a6487"], "d": ["Sotuta، از نیرومندترین بیگ‌نشین‌های مایا در درون Yucatán، زیر فرمان دودمان Cocom مدتی دراز در برابر پیشروی اسپانیایی‌ها ایستاد. در سال‌های پس از بنیان Mérida در 1542 بیگ‌نشین سلطهٔ اسپانیا را پذیرفت؛ پس از سرکوب شورش بزرگ شرق در 1546-47 این وابستگی پایدار شد.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Villa de Oropesa بنیان نهاده شد — اسکان دره غلات برای تأمین Potosí", "d6821cbf"], "d": ["به فرمان فرماندار کل Francisco de Toledo، Villa de Oropesa در دره Cochabamba بنیان نهاده شد. خاک حاصلخیز دره به‌عنوان منطقهٔ غله برای تأمین نیروی کار انبوه معادن نقرهٔ Potosí سازماندهی شد؛ شهرک به انبار Peru علیای استعماری بدل شد.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["سقوط Vilcabamba — پایان دولت مستقل اینکا", "31b5a95d"], "d": ["پس از سقوط کوسکو در 1533، مانکو اینکا و جانشینانش یک دولت مستقل اینکا را چهل سال در کوه‌های بیلکابامبا ادامه دادند. لشکرکشی‌ای که فرماندار کل فرانسیسکو د تولدو ترتیب داد پایتخت متروک را گرفت؛ واپسین فرمانروا توپاک آمارو که می‌گریخت دستگیر و به کوسکو آورده شد و در آنجا اعدام گردید. بدین‌سان هستی سیاسی دودمان اینکا که چهار سده در جهان آند ادامه داشت پایان یافت.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Monterrey بنیان نهاده شد — پایتخت Nuevo León", "ec6e44bc"], "d": ["Diego de Montemayor پس از دو کوشش ناکام، Ciudad Metropolitana de Nuestra Señora de Monterrey را کنار چشمهٔ Santa Lucía بنیان نهاد. این آبادی در مرز شمالی تکیه‌گاه گسترش پایدار Nueva España به سوی شمال‌شرق (Nuevo León) شد.", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["San Francisco de Borja بنیان نهاده شد — فرمانروایی اسپانیا در Maynas", "7ee32d19"], "d": ["Diego Vaca de Vega با بنیان San Francisco de Borja در پایین‌دست تنگهٔ Pongo de Manseriche بر رود Marañón، منطقهٔ Maynas را به اداره‌ٔ اسپانیا وابسته کرد. این شهرک آغازگاه شبکهٔ مأموریت‌های یسوعی شد که در سدهٔ بعد در آمازون علیا ادامه یافت.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["مأموریت San Antonio de Valero بنیان نهاده شد — هستهٔ تگزاس اسپانیایی", "ca9bd147"], "d": ["در برابر نفوذ فرانسوی‌ها از Louisiana به سوی غرب، اسپانیا تصمیم گرفت در تگزاس جایگاهی پایدار برپا کند. کشیش Olivares مأموریت San Antonio de Valero را کنار رود San Antonio بنیان نهاد؛ چند روز بعد فرماندار Alarcón پرزیدیوی San Antonio de Béxar را کنار آن نهاد. ساختمان مأموریت بعدها به نام Alamo خوانده خواهد شد.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Refugio (Matamoros کنونی) بنیان نهاده شد — اسکان دهانهٔ Rio Grande", "f3b86da7"], "d": ["برنامهٔ اسکان Nuevo Santander که José de Escandón از دههٔ 1740 پیش می‌برد حوضهٔ پایین Rio Grande را از مزرعه و شهرک پر کرد. Nuestra Señora del Refugio de los Esteros به‌عنوان یکی از واپسین حلقه‌های این برنامه در کرانهٔ جنوبی رود بنیان نهاده شد؛ در سدهٔ 19 نام Matamoros گرفت.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["اعلامیهٔ استقلال آمریکای مرکزی — ژنرال‌نشین Guatemala از اسپانیا جدا شد", "f998089a"], "d": ["پس از Plan de Iguala در مکزیک، مجلسی که در Guatemala گرد آمد استقلال ژنرال‌نشین را از اسپانیا اعلام کرد؛ فرماندار کل Gabino Gaínza در رأس اداره‌ٔ گذار ماند. بدین‌سان فرمانروایی اسپانیا در سرزمین‌های Guatemala، El Salvador، Honduras، Nicaragua و Costa Rica کنونی پایان یافت. منطقه پس از پیوستن کوتاه به امپراتوری مکزیک، در 1823 ایالات متحد آمریکای مرکزی را بنیان نهاد.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Nueva Helvetia بنیان نهاده شد — مکزیک دره Sacramento را به اسکان گشود", "067a1f2a"], "d": ["John Sutter، مهاجر سوئیسی، با مجوز و امتیاز زمینی که از مقامات مکزیک گرفت Nueva Helvetia را در پیوستگاه رودهای Sacramento و American بنیان نهاد. این مزرعهٔ مستحکم پیشرفته‌ترین پاسگاه مکزیک در نواحی درونی Alta California شد؛ با یافتن طلا در 1848 به مرکز مهاجرت به California بدل خواهد شد.", "1c5eab3d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["رائتیا و نوریکوم به روم پیوست: تیبریوس و دروسوس آن‌سوی آلپ را گرفتند", "be6f2a15"], "d": ["در 15 پیش از میلاد تیبریوس و دروسوس قبایل آلپ را شکست دادند و رائتیا (و الحاق نوریکوم) را کامل کردند؛ کرانهٔ بالایی دانوب مرز روم شد.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["با مرگ آمینتاس، گالاتیا ایالت رومی شد", "e4250ad7"], "d": ["چون آمینتاس، پادشاه گالاتی منصوب آنتونیوس، در کیلیکیه کشته شد (25 پیش از میلاد)، آگوستوس گالاتیا را به ایالت رومی بدل کرد و با پیسیدیا و لیکائونیا یکی ساخت. پایتخت آنکیرا (آنکارا) شد؛ کتیبهٔ Res Gestae آگوستوس (Monumentum Ancyranum) در اینجا نوشته شد.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["اکتاویانوس عنوان «آگوستوس» را برگرفت: دورهٔ پرینکیپات (امپراتوری) آغاز شد", "310297b6"], "d": ["در 16 ژانویه 27 سنا عنوان آگوستوس را به اکتاویانوس داد؛ اکتاویانوس فرماندهی (imperium) بخش بزرگ ایالت‌ها را برای مدتی طولانی به دست آورد. این تاریخ آغاز امپراتوری روم شمرده می‌شود.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["بوکوس دوم درگذشت؛ موریتانیا به نظارت اکتاویانوس درآمد", "414fa36c"], "d": ["چون بوکوس دوم در 33 بی‌فرزند درگذشت، موریتانیا با وصیت او به اکتاویانوس رسید و به فرمان روم درآمد؛ مدتی مستقیماً زیر فرمان روم ماند و در 25 به یوبا دوم داده شد.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["آنتونیوس آرخلائوس را پادشاه کاپادوکیه کرد", "1e83e691"], "d": ["آنتونیوس هنگام سامان‌دادن دوبارهٔ شرق، تخت کاپادوکیه را به آرخلائوس داد؛ آرخلائوس تا هنگامی که در 17 میلادی تیبریوس او را به روم فراخواند، فرمانروایی کرد. کاپادوکیه در 17 میلادی ایالت رومی شد (این رویداد در گاه‌شمار ماده‌ای جداگانه است).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["فیلیپی: اکتاویانوس و آنتونیوس بروتوس و کاسیوس را شکست دادند", "4386016f"], "d": ["در اکتبر 42 نزدیک فیلیپی دو نبرد جداگانه رخ داد؛ کاسیوس و بروتوس خودکشی کردند و نیروی جمهوری‌خواه از میان رفت. سه‌گانه‌فرمانروایان جهان روم را میان خود تقسیم کردند.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["ژولیوس سزار کورینت را به‌عنوان مستعمرهٔ رومی دوباره بنیان نهاد", "283a5daa"], "d": ["اندکی پیش از ترور سزار، در کورینت مستعمره‌نشینان شهروند رومی (بیشترشان آزادشدگان) اسکان یافتند؛ شهر از مراکز مهم ایالت رومی آخایا شد. تصمیم به بنیان دوبارهٔ شهر مربوط به 44 پیش از میلاد و اسکان در 44/43 پیش از میلاد است.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["بوربیستا ترور شد: پادشاهی داک‌ها پاره‌پاره شد", "9b9edb14"], "d": ["استرابون می‌نویسد که بوربیستا پیش از مرگ سزار در کودتایی داخلی کشته شد و پادشاهی او نخست به پنج و سپس به چهار پاره تقسیم گردید. اتحاد داکیه تا دکبالوس (87 میلادی) دوباره برپا نشد.", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["سزار در ایدوس ماه مارس (15 مارس) در سنا کشته شد", "18649074"], "d": ["سزار که دیکتاتور دائمی اعلام شده بود، در 15 مارس 44 در نشست سنا در تئاتر پمپه به دست گروهی از سناتورها با خنجر کشته شد. مرگ او زمینهٔ جنگ‌های داخلی تازه و قدرت‌گیری آگوستوس را فراهم کرد.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["موندا: سزار پسران پمپه را شکست داد", "e1e93362"], "d": ["در 17 مارس 45 در موندا سزار سپاه گنائوس پمپه و سکستوس پمپه را شکست داد؛ هیسپانیا در دست سزار ماند. این واپسین نبرد بزرگ جنگ داخلی است.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["تاپسوس: سزار یوبا یکم را شکست داد؛ نومیدیای شرقی ایالت آفریکا نوا شد", "77b28c50"], "d": ["سزار در بهار 46 در تاپسوس سپاه سکیپیو و یوبا یکم را درهم شکست؛ یوبا خودکشی کرد. بخش شرقی نومیدیا به ایالت آفریکا نوا که سالوستیوس اداره می‌کرد بدل شد و بخش باختری به بوکوس و سیتیوس داده شد.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["زِلا: سزار فارناکس دوم را شکست داد («آمدم، دیدم، پیروز شدم»)", "11bf082a"], "d": ["فارناکس دوم، پسر میترادات، از جنگ داخلی بهره جست و کوشید پونتوس را بازپس گیرد؛ سزار در 47 در زِلا او را شکست داد و پونتوس را زیر نظارت روم از نو سامان داد. فارناکس به بوسپوروس گریخت و همان‌جا درگذشت.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["فارسالوس: سزار پمپه را شکست داد", "e821abe8"], "d": ["سزار پس از عقب‌نشینی در دیراخیوم، در فارسالوس سپاه بزرگ‌تر پمپه را درهم شکست. پمپه به مصر گریخت و کشته شد؛ ایالت‌های شرق به روی سزار گشوده شد.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["آلزیا: سزار ورسینژتوریکس را محاصره و شکست داد؛ مقاومت گل درهم شکست", "d57cab9f"], "d": ["در 52 پیش از میلاد شورش گل به رهبری ورسینژتوریکس آرورنی با محاصرهٔ آلزیا و دفاع از خط محاصرهٔ سزار سرکوب شد؛ ورسینژتوریکس تسلیم شد. گالیا سال بعد کاملاً زیر نظارت روم درآمد.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["لشکرکشی سزار به گل آغاز شد: هلوتی‌ها شکست خوردند", "1e594bb3"], "d": ["در 58 پیش از میلاد سزار، به‌عنوان والی گل سیسالپین و ترانسالپین، مهاجرت هلوتی‌ها را نزدیک بیبراکته متوقف کرد؛ سپس ژرمن‌های آریوویستوس را شکست داد. لشکرکشی هشت سال طول کشید و گل را به روم پیوست.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["میترادات ششم در پانتیکاپایون درگذشت؛ بوسپوروس به فارناکس رسید", "0831b871"], "d": ["میترادات که از پمپه گریخته بود، با شورش پسرش فارناکس در دژ پانتیکاپایون خودکشی کرد (63). فارناکس بوسپوروس را به پمپه تسلیم کرد و به‌عنوان پادشاه دوست روم شناخته شد.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["پمپه بیتینیه و باختر پونتوس را یکی کرد و ایالت بیتینیه و پونتوس را بنیان نهاد", "b2865ea8"], "d": ["پمپه در سامان‌دادن شرق (65-63) بیتینیه را با نیمهٔ باختری پونتوس یکی کرد و ایالت بیتینیه و پونتوس را پدید آورد؛ بخش‌های درونی پونتوس در شرق به شاهزادگان محلی داده شد.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["پمپه کوماژن را دوست و هم‌پیمان روم شناخت", "a48ba55c"], "d": ["پمپه در سامان‌دهی شرق، پادشاهی آنتیوخوس یکم و بخشی از ناحیهٔ سلوکیه (زوگما) را تأیید کرد و کوماژن را سپر هم‌پیمان میان روم و اشکانی ساخت. پادشاهی در 17 میلادی و به‌طور پایدار در 72 میلادی به ایالت رومی پیوست (این رویدادها در گاه‌شمار مواد جداگانه‌اند).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["پمپه میترادات را شکست داد؛ پونتوس به روم پیوست", "8f3f50a6"], "d": ["پمپه در 66 در دشت لیکوس شبانه سپاه میترادات را درهم شکست؛ میترادات از کولخیس به بوسپوروس گریخت. شهرهای ساحلی پونتوس زیر نظارت روم درآمد و در 63 ایالت یکی‌شده با بیتینیه پدید آمد.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["آنتیوخوس یکم تئوس بر تخت کوماژن نشست", "b1680d3f"], "d": ["آنتیوخوس یکم، پادشاه کوماژن، آرامگاه-معبد نمرود داغ را که تبار پارسی و مقدونی را پیوند می‌دهد، بنا کرد. پادشاهی میان روم و اشکانی در جایگاه سپر بود.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["کورنه ایالت رومی شد (کیرنائیکا)", "f9993ffb"], "d": ["بیست سال پس از آنکه بطلمیوس آپیون پادشاهی خود را به روم وصیت کرد (96)، روم کیرنائیکا را در نظام ایالتی درآورد؛ در 67 با کرت یکی شد.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["نیکومدس چهارم پادشاهی خود را به روم وصیت کرد", "e29d9fbc"], "d": ["با مرگ نیکومدس چهارم (75/74)، بیتینیه با وصیت به مردم روم رسید؛ میترادات ششم این را نپذیرفت و جنگ سوم میتریداتی آغاز شد. بیتینیه به ایالت مستقیم روم بدل شد.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["بوربیستا قبایل داک و گت را یکپارچه کرد", "3648f92e"], "d": ["به گفتهٔ استرابون، بوربیستا گت‌ها و داک‌ها را در یک پادشاهی گرد آورد و تا مرزهای تراکیه و ایلیریا در جنوب دانوب لشکر کشید. پادشاهی در سراسر دانوب برای روم به تهدید بدل شد.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["صلح داردانوس: میترادات از آسیا و بیتینیه عقب نشست", "535818ed"], "d": ["در صلح داردانوس با سولا، میترادات پذیرفت که همهٔ فتوحاتش (آسیا، بیتینیه، کاپادوکیه، پافلاگونیا) را تخلیه کند و 70 کشتی و 2000-3000 تالنت بدهد. اما چیرگی دشمنان سولا در روم به جنگ دوم میتریداتی انجامید.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["میترادات ایالت آسیا را اشغال کرد؛ «شامگاه افسوس» (کشتار 80.000 رومی)", "3986833b"], "d": ["در آغاز جنگ نخست میتریداتی (89/88)، میترادات بیتینیه و ایالت آسیا را اشغال کرد و با فرمانی که در افسوس داد، شهروندان رومی به‌طور گروهی کشته شدند. آتن نیز به سوی پونتوس گروید (آریستیون).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: روم به هم‌پیمانان ایتالیایی تابعیت داد (جنگ هم‌پیمانان)", "f72ba27d"], "d": ["پس از شورش هم‌پیمانان ایتالیایی روم (91-88)، Lex Iulia (90) و Lex Plautia Papiria (89) تابعیت رومی را به هم‌پیمانان وفادار و تسلیم‌شده شناختند. بدین‌سان شبه‌جزیرهٔ ایتالیا تا رود پو به یک جامعهٔ شهروندی بدل شد.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["سولا آریوبارزانس را بر تخت کاپادوکیه نشاند", "8bdd078c"], "d": ["در برابر آنکه میترادات ششم کاپادوکیه را با پادشاهی کودک در دست داشت، روم هنگام والی‌گری سولا در کیلیکیه، آریوبارزانس را پادشاه اعلام کرد. کاپادوکیه در سدهٔ بعد سپر کشمکش‌های روم، ایران و پونتوس بود.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["بطلمیوس آپیون کورنه را به روم وصیت کرد", "5edef477"], "d": ["بطلمیوس آپیون که بر کورنه فرمان می‌راند، هنگام مرگ بی‌فرزند پادشاهی خود را به مردم روم واگذاشت (96)؛ سنا شهرها را آزاد گذاشت و روم تبدیل آن را به ایالت تا 74 به تأخیر انداخت.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["بوکوس یوگورتا را به روم تسلیم کرد؛ باختر نومیدیا به موریتانیا پیوست", "7619ad15"], "d": ["بوکوس یکم، پادشاه موریتانیا و پدرزن یوگورتا، با تسلیم یوگورتا به سولا با روم سازش کرد؛ در برابر، بخش باختری نومیدیا به او واگذار شد. یوگورتا در 104 در زندان روم درگذشت.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["پایریسادس پنجم پادشاهی را به میترادات ششم واگذاشت: بوسپوروس به پونتوس پیوست", "835bbe74"], "d": ["پایریسادس پنجم که زیر فشار سکاها بود، با یاری دیوفانتوس، سردار میترادات، پادشاهی را به میترادات واگذاشت؛ بوسپوروس بدین‌سان امتداد شمالی پونتوس شد. تجارت غلهٔ دریای سیاه، به‌عنوان منبع میترادات، در این تاریخ به پونتوس رسید.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["دیوفانتوس، سردار میترادات، سکاها را در کریمه شکست داد", "d8d48c68"], "d": ["دیوفانتوس سپاه پالاکوس، پسر اسکیلوروس پادشاه سکاها، را شکست داد و پیرامون نئاپولیس را در تاوریکا گرفت؛ بوسپوروس و خرسونسوس به پونتوس پیوست.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["یوگورتا سیرتا را گرفت: روم در کار نومیدیا مداخله کرد", "660eb34a"], "d": ["یوگورتا در 112 پیش از میلاد سیرتا را محاصره کرد و آدرهبال را کشت؛ بازرگانان ایتالیایی که در شهر کشته شدند، روم را به اعلان جنگ بر ضد یوگورتا واداشتند. جنگ تا 105 ادامه یافت.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["نربو مارتیوس بنیان یافت: گل جنوبی (گالیا ترانسالپینا) ایالت رومی شد", "20c4bdfa"], "d": ["روم که به فراخوان یاری ماسالیا (125) به گل درآمده بود، با پیروزی‌های آکوا سکستیه (122) و آلوبروژها دره رون را گرفت؛ در 118 پیش از میلاد نربو مارتیوس به‌عنوان نخستین مستعمرهٔ رومی در گل بنیان یافت. ناحیه به ایالت گالیا ترانسالپینا بدل شد.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["میترادات ششم اوپاتور بر تخت پونتوس نشست", "c2d5fd41"], "d": ["میترادات ششم که با مرگ میترادات پنجم (120/119) در کودکی به تخت رسید، پس از چند سال سرپرستی، پونتوس را در پیرامون دریای سیاه به نیرویی رقیب روم بدل کرد.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["روم به فراخوان ماسالیا به گل درآمد", "eaf7eb0a"], "d": ["چون ماسالیا که زیر فشار سالوی‌ها و لیگوری‌ها بود از روم یاری خواست، روم در 125 سپاهی به گل جنوبی فرستاد. این مداخله به بنیان نربو مارتیوس (118) و گرفتن گالیا ترانسالپینا انجامید.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["آریستونیکوس شکست خورد؛ از سرزمین‌های پرگامون ایالت آسیا بنیان یافت", "7ccdc59e"], "d": ["آریستونیکوس که با نام اومنس سوم مدعی تخت بود، به دست سپاه روم شکست خورد و دستگیر شد (129)؛ با سامان مانیوس آکویلیوس، پادشاهی پیشین پرگامون ایالت آسیا شد. نظام مالیاتی ایالت (publicani) برای روم منبع درآمد بزرگی بود.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["نومانتیا سقوط کرد: کلتیبریا به روم پیوست", "ced07244"], "d": ["سکیپیو امیلیانوس پس از هشت ماه محاصره، نومانتیا را با گرسنگی به تسلیم واداشت (133)؛ شهر ویران شد. جنگ‌های کلتیبری پایان یافت و بخش درونی هیسپانیا سیتریور به روم پیوست.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["جنگ آخایا: اتحادیهٔ آخایا از روم شکست خورد، اتحادیه‌ها منحل شد", "e434cfe0"], "d": ["اتحادیهٔ آخایا که بر سر مناقشهٔ مرزی با اسپارت بر ضد روم برخاسته بود، در 146 در لئوکوپترا شکست خورد؛ کورنت ویران شد و اتحادیه عملاً منحل گشت، بخشی از یونان زیر نظارت ایالت مقدونیه درآمد.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["جنگ سوم پونی پایان یافت: کارتاژ ویران شد، ایالت آفریکا بنیان یافت", "522515b4"], "d": ["پ. کورنلیوس سکیپیو امیلیانوس پس از سه سال محاصره، در بهار 146 کارتاژ را گرفت؛ شهر سوزانده و ویران شد، سرزمین‌ها به روم پیوست. پس‌کرانهٔ کارتاژ ایالت آفریکا شد؛ نومیدیای ماسینیسا همسایهٔ باختری ماند.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["مقدونیه ایالت رومی شد", "dc6d2352"], "d": ["پس از سرکوب شورش آندریسکوس (148)، چهار ناحیهٔ مقدونیه به‌عنوان یک ایالت رومی یکی شد (146)؛ نظارت بر یونان در جنوب ایالت نیز به والی مقدونیه سپرده شد. راه اگناتیا در سال‌های بعد از آدریاتیک تا سالونیک ساخته شد.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["شورش آندریسکوس: پادشاهی مقدونیه کوتاه‌زمانی دوباره برپا شد، به دست متلوس سرکوب شد", "0119ff73"], "d": ["آندریسکوس که مدعی بود پسر پرسئوس است، در 150/149 مقدونیه را دوباره یکی کرد و نخستین نیروهای رومی را شکست داد؛ در 148 متلوس مقدونیه را بازپس گرفت. این شورش سبب شد مقدونیه مستقیماً به فرمان روم درآید.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["روم به کارتاژ اعلان جنگ کرد: جنگ سوم پونی آغاز شد", "2e34c235"], "d": ["دفاع کارتاژ از خود در برابر حملات ماسینیسا نقض پیمان شمرده شد؛ روم در 149 اعلان جنگ کرد و اوتیکا را به خود پیوست. شهر کارتاژ سه سال زیر محاصره ایستادگی کرد.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["ماسینیسا به سرزمین‌های کارتاژ حمله برد: جنگ نومیدیا و کارتاژ", "b47559a5"], "d": ["چون ماسینیسا سرزمین‌های کارتاژ را گرفت (151/150)، کارتاژ جنگ آغاز کرد و از ماسینیسا شکست خورد؛ روم این را نقض پیمان شمرد و در 149 اعلان جنگ کرد. ماسینیسا در 148 در نود سالگی درگذشت.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["روم به رودس فرمان داد والیان خود را از لیکیه و کاریه بازخواند؛ اتحادیهٔ لیکیه (پاتارا) از سلطهٔ رودس بیرون آمد", "6bbe2b54"], "d": ["پس از جنگ سوم مقدونیه، سنای روم به رودس فرمان داد والیانش را در لیکیه و کاریه تا روزی معین بازخواند؛ رودس این زیان‌ها را از تهدید جنگ سبک‌تر شمرد و پذیرفت. اتحادیهٔ لیکیه (به مرکزیت پاتارا) بدین‌سان از سلطهٔ رودس بیرون آمد و به‌عنوان اتحادیهٔ لیکیه زیر حمایت روم ادامه یافت.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["اپیروس به دست روم غارت شد: هفتاد شهر ویران گشت", "456fb461"], "d": ["پس از جنگ سوم مقدونیه، شهرهای مولوسی اپیروس که به پرسئوس نزدیک مانده بودند، به فرمان آمیلیوس پائولوس غارت شدند و حدود 150.000 تن به بردگی گرفته شدند. اپیروس در سدهٔ بعد زیر فرمان روم تنگدست ماند.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["مقدونیه به دست روم به چهار ناحیهٔ خودمختار (مریدس) تقسیم شد", "7a795ba0"], "d": ["با تصمیم سنا (167 پیش از میلاد) پادشاهی مقدونیه به چهار ناحیه با مرکزیت آمفیپولیس، تسالونیکه (سالونیک)، پلا و پلاگونیا تقسیم شد؛ ازدواج و تملک ملک میان ناحیه‌ها ممنوع شد و بهره‌برداری از معادن محدود گردید.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["روم لیکیه و کاریه را از رودس گرفت؛ دلوس بندر آزاد اعلام شد", "09c8143f"], "d": ["در جنگ سوم مقدونیه، کوشش رودس برای میانجی‌گری میان روم و پرسئوس کیفر داده شد: سنا لیکیه و کاریه را از رودس گرفت و آزاد اعلام کرد، دلوس را به آتن داد و به بندری بی‌گمرک بدل ساخت. درآمد تجاری رودس به‌سختی کاهش یافت.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["پیدنا: آمیلیوس پائولوس پرسئوس را شکست داد؛ پادشاهی آنتیگونی پایان یافت", "a59c5270"], "d": ["در 22 ژوئن 168 در پیدنا لژیون‌های روم فالانکس مقدونی را شکست دادند و جنگ سوم مقدونیه را پایان بخشیدند؛ پرسئوس در ساموتراکه تسلیم شد و به روم برای مراسم پیروزی برده شد. سلسلهٔ آنتیگونی پایان یافت.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["صلح آپامیا: اومنس دوم خرسونسوس تراکیه، فریگیه، لیدیه و بخش بزرگ میسیه را برای پرگامون به دست آورد", "f25ed9af"], "d": ["پس از شکست در مگنزیا، آنتیوخوس سوم در 188 با روم صلح امضا کرد: شمال کوه‌های توروس را رها کرد. بیشتر این سرزمین‌ها به پرگامونِ اومنس دوم، هم‌پیمان روم، داده شد (خرسونسوس تراکیه، فریگیهٔ بزرگ، لیدیه، میسیه، بخشی از ایونیه).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["صلح آپامیا: رودس جنوب لیکیه و کاریه را گرفت", "aa5173c6"], "d": ["پس از مگنزیا، روم به رودس، هم‌پیمان خود، لیکیه و بخش جنوب مئاندر در کاریه را داد. رودس این سرزمین‌ها را در 167 از دست داد.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["مانلیوس والسو قبایل گالات را شکست داد: استقلال گالات‌ها زیر نظارت روم درآمد", "30ae73d7"], "d": ["پس از مگنزیا، گنائوس مانلیوس والسو به سرزمین گالات‌ها تاخت و در المپوس و ماگابا تولیستوآگی‌ها و تکتوساگ‌ها را درهم شکست؛ با پیمان، گالات‌ها پذیرفتند به همسایگان حمله نکنند. گالاتیه تا حد زیادی مستقل ماند اما به توازن روم و پرگامون وابسته شد.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["آیتولیا با روم صلح کرد: آمبراکیا و اوئنیادای را از دست داد، سروری روم را شناخت", "f332c6bf"], "d": ["آیتولیا که در جنگ آنتیوخوس همراه آنتیوخوس بود، پس از محاصرهٔ آمبراکیا به دست فولویوس نوبیلیور با روم صلح کرد؛ «عظمت» روم را شناخت، غرامت پرداخت و شهرهایی چون آمبراکیا و اوئنیادای را رها کرد.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["مگنزیا در سیپیلوس: روم و پرگامون آنتیوخوس سوم را شکست دادند", "f650ef21"], "d": ["در زمستان 190/189 در مگنزیا ل. سکیپیو و اومنس دوم سپاه آنتیوخوس سوم را درهم شکستند. صلح آپامیا (188) که پس از پیروزی بسته شد، آنتیوخوس را به رهاکردن شمال توروس واداشت.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["اسپارت به اتحادیهٔ آخایا پیوست: فیلوپویمن پس از نابیس لاکونیا را به اتحادیه پیوست", "2629b6e1"], "d": ["پس از کشته‌شدن نابیس، ستمگر اسپارتی (192)، فیلوپویمن، استراتگوس آخایا، اسپارت را به زور به اتحادیهٔ آخایا پیوست. اسپارت استقلال خود را در 188 با ویرانی دیوارها کاملاً از دست داد.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["فلامینینوس در بازی‌های ایستمی آزادی یونانیان را اعلام کرد", "3d850bf2"], "d": ["پس از کینوسکفالای، فرمانده روم ت. کوئینکتیوس فلامینینوس در بازی‌های ایستمی 196 پیش از میلاد اعلام کرد که پادگان‌های مقدونی در کورنت، خالکیس و دمتریاس برچیده می‌شود و شهرهای یونانی «آزاد، بی‌مالیات و تابع قوانین خود»اند. روم بدین‌سان به‌عنوان داور در یونان جای گرفت.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["کینوسکفالای: روم فیلیپ پنجم را شکست داد؛ مقدونیه ناچار از یونان عقب نشست", "9cb44ca6"], "d": ["در ژوئن 197 لژیون‌های فلامینینوس در کینوسکفالای فالانکس مقدونی را درهم شکستند. در صلح 196 فیلیپ همهٔ مواضع خود در یونان (دمتریاس، خالکیس، کورنت) را رها کرد، ناوگانش را تسلیم نمود و 1000 تالنت پرداخت.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["در هیسپانیا دو ایالت رومی بنیان یافت: سیتریور و اولتریور", "1baa8383"], "d": ["سرزمین‌های هیسپانیا که از کارتاژ گرفته شده بود، در 197 نخستین بار به دو ایالت جداگانه تقسیم شد و هر یک را یک پرایتور اداره کرد. پس از این تاریخ، جنگ‌های کلتیبری و لوزیتانی در شبه‌جزیره برای گسترش نظام ایالتی روم انجام شد.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["صلح پس از زاما: کارتاژ هیسپانیا و جزایر مدیترانه و ناوگان خود را از دست داد، غرامت 10.000 تالنت را پذیرفت", "8654422d"], "d": ["پس از زاما (202)، روم کارتاژ را به سرزمین‌های خود در آفریقا محدود کرد: رهاکردن هیسپانیا و جزایر مدیترانه، تسلیم ناوگان (جز 10 کشتی)، پرداخت 10.000 تالنت در 50 سال و جنگ‌نکردن بدون اجازهٔ روم پذیرفته شد. نومیدیای ماسینیسا همسایهٔ مستقل شد.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["روم ماسینیسا را با پادشاهی سیفاکس پاداش داد", "54ba7a64"], "d": ["در صلح زاما، روم ماسینیسا را بر پادشاهی سیفاکس و سرزمین‌های مرزی گرفته‌شده از کارتاژ گماشت؛ مطالبات ماسینیسا دربارهٔ ناحیهٔ «امپوریا» و مرز کارتاژ بعدها سبب جنگ شد.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["زاما: سکیپیو و ماسینیسا هانیبال را شکست دادند", "52e188e6"], "d": ["در نبرد زاما که پس از فراخوانده‌شدن هانیبال به آفریقا رخ داد، لژیون‌های سکیپیو و سواره‌نظام نومیدی ماسینیسا سپاه کارتاژ را شکست دادند. جنگ دوم پونی با این نبرد قطعاً به سود روم پایان یافت.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["سیفاکس شکست خورد و اسیر شد؛ ماسینیسا نومیدیا را یکی کرد", "a42a3cb0"], "d": ["سکیپیو و ماسینیسا در 203 سپاه سیفاکس را شکست دادند و سیفاکس را اسیر کردند؛ ماسینیسا با پشتیبانی روم سیرتا و پادشاهی سیفاکس را گرفت. نومیدیا با پیوستن بخش‌های شرقی و باختری به پادشاهی‌ای نیرومند بدل شد.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["ایلیپا و گادس: هیسپانیا از کارتاژ به روم رسید", "31e5a50c"], "d": ["سکیپیو در 206 در ایلیپا سپاه هسدروبال گیسگو و ماگو را شکست داد و نظارت کارتاژ بر هیسپانیا را پایان بخشید؛ گادس نیز اندکی بعد به روم پیوست. کارتاژ معادن نقرهٔ هیسپانیا و منبع سرباز خود را از دست داد.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["فابیوس ماکسیموس تارنتوم را از هانیبال بازپس گرفت", "bd605091"], "d": ["تارنتوم که در 212 به هانیبال تسلیم شده بود، در 209 با خیانتی به ق. فابیوس ماکسیموس رسید. با سقوط شهر، ارزشمندترین بندر هانیبال در ایتالیای جنوبی از دستش رفت.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["کاپوآ به روم افتاد: پایگاه هانیبال در کامپانیا از دست رفت", "cfcb9c9a"], "d": ["روم که کاپوآی گرویده به هانیبال پس از کانه را دو سال محاصره کرده بود، با وجود حرکت هانیبال به سوی روم شهر را گرفت و سخت کیفر داد؛ خودمختاری کاپوآ برداشته شد. هانیبال در ایتالیای جنوبی به دفاع عقب نشست.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["کانه: هانیبال سپاه روم را محاصره و نابود کرد؛ ایتالیای جنوبی به سوی کارتاژ گرایید", "94f5110a"], "d": ["در 216 در کانه در آپولیا، آرایش محاصرهٔ هانیبال سپاه حدود هفتاد هزار نفری روم را نابود کرد. کاپوآ، تارنتوم و بسیاری از شهرهای ایتالیای جنوبی به صف کارتاژ پیوستند.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["سپاه روم در هیسپانیا پیاده شد: نخستین پایگاه رومی در امپوریون", "8cb47853"], "d": ["پس از حرکت هانیبال به ایتالیا، گنائوس کورنلیوس سکیپیو در 218 پیش از میلاد در امپوریون پیاده شد و حضور روم را در هیسپانیا، در کنار ابرو، آغاز کرد؛ شبه‌جزیره دومین جبههٔ جنگ دوم پونی شد.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["هانیبال از آلپ گذشت و وارد ایتالیا شد", "a1d3bf5a"], "d": ["هانیبال از ابرو، پیرنه و رون گذشت و در پاییز از آلپ عبور کرد و به ایتالیای شمالی فرود آمد؛ در تیکینوس و ترهبیا سپاهیان روم را شکست داد. بدین‌سان مرکز جنگ ایتالیایی کارتاژ به درون روم کشیده شد.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["هانیبال ساگونتوم را گرفت: جرقهٔ جنگ دوم پونی زده شد", "a497a334"], "d": ["هانیبال پس از هشت ماه محاصره، ساگونتوم، هم‌پیمان روم، را گرفت (219 پیش از میلاد)؛ روم سفیر فرستاد و تسلیم هانیبال را خواست و با رد آن، جنگ اعلام شد. جنگ هفده سال در ایتالیا، هیسپانیا و آفریقا ادامه یافت.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["سلاسیا: آنتیگونوس دوسون کلئومنس را شکست داد؛ اسپارت نخستین بار اشغال بیگانه را دید", "dc64a8db"], "d": ["در تابستان 222 در سلاسیا اتحاد مقدونی-آخایایی سپاه اسپارتی کلئومنس را شکست داد؛ کلئومنس به مصر گریخت. دوسون وارد اسپارت شد و آن را به نظام لیکورگوس بازگرداند؛ اسپارتیان در تاریخ خود نخستین بار اشغال سپاه بیگانه را تجربه کردند.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["مدیولانوم (میلان) به روم افتاد: اینسوبرها شکست خوردند، ایتالیای شمالی به روی روم گشوده شد", "d3ec639f"], "d": ["روم که در تلاموم (225) گالی‌ها را شکست داده بود، در 222 پیش از میلاد با پیروزی مارکلوس در کلاستیدیوم و گرفتن مدیولانوم، بخش بزرگ دشت پو را زیر نظارت گرفت. ناحیه به‌عنوان گل سیسالپین سازمان یافت.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["اتحادیهٔ آخایا آکروکورنت را به آنتیگونوس دوسون داد: کورنت به مقدونیه بازگشت", "c8ec9d0c"], "d": ["اتحادیهٔ آخایا که زیر فشار کلئومنس سوم بود، به دست آراتوس از مقدونیه یاری خواست و آکروکورنت و کورنت را به آنتیگونوس دوسون واگذار کرد؛ دوسون اتحادیهٔ هلنی (Hellenikos symmachia) را بنیان نهاد.", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["پیمان ابرو: کارتاژ پذیرفت از شمال ابرو نگذرد", "a199de0b"], "d": ["هسدروبال که فتح هیسپانیای آغازشده به دست هامیلکار را ادامه می‌داد، با روم پیمان ابرو را بست: کارتاژ به‌طور مسلحانه از ابرو نمی‌گذشت. حملهٔ هانیبال به ساگونتوم در 219 بر تفسیر این پیمان استوار شد.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["روم ساردینیا و کورسیکا را از کارتاژ گرفت", "4f7295ee"], "d": ["چون سربازان مزدور شورشی کارتاژ در ساردینیا از روم یاری خواستند، روم جزیره را اشغال کرد؛ کارتاژ زیر تهدید جنگ جزیره‌ها را رها کرد و ناچار شد 1200 تالنت دیگر بپردازد. روم ایالت دوم (ساردینیا و کورسیکا) را پدید آورد.", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["جزایر آگاتس: ناوگان کارتاژ نابود شد؛ سیسیل نخستین ایالت رومی شد", "8bd16e8f"], "d": ["لوتاتیوس کاتولوس در مارس 241 در برابر آگاتس ناوگان کارتاژی هانو را درهم شکست؛ سپس با صلح لوتاتیوس، کارتاژ سیسیل را تخلیه کرد و پذیرفت 3200 تالنت غرامت جنگی بپردازد. سیسیل (جز سیراکوز هیرون) نخستین ایالت روم شد.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["آراتوس بر آکروکورنت یورش برد: کورنت از مقدونیه به اتحادیهٔ آخایا رسید", "a88dfda6"], "d": ["آراتوس سیکیونی با شبیخونی پادگان آکروکورنت آنتیگونوس گوناتاس را بی‌اثر کرد و کورنت را به اتحادیهٔ آخایا پیوست؛ مگارا، تروزن و اپیداوروس نیز به اتحادیه گرویدند. مقدونیه کلید دژ خود را در پلوپونز از دست داد.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["آراتوس سیکیون را به اتحادیهٔ آخایا پیوست", "6f413f9c"], "d": ["آراتوس جوان ستمگر سیکیون را برانداخت و شهر را به اتحادیهٔ آخایا پیوست؛ این گام اتحادیه را به کرانه‌های شمالی و جنوبی خلیج کورنت گسترد و آراتوس را به برگزیده‌شدن در مقام استراتگوس رساند.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["هیرون دوم با روم متحد شد: سیسیل شرقی هم‌پیمان روم شد", "5e95a134"], "d": ["هیرون در آغاز جنگ نخست پونی به سبب مسئلهٔ مسانا با کارتاژ بر ضد روم متحد شده بود؛ در 263 با روم صلح و اتحاد بست و در سراسر عمر خود (تا 215) هم‌پیمان وفادار روم ماند. سیراکوز دولت هم‌پیمانی شد که بیرون از ایالت سیسیلِ روم ماند.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["نیکومدس یکم نیکومدیه (ازمیت) را بنیان نهاد", "a89ed42a"], "d": ["نیکومدس پس از ویرانی آستاکوس، در انتهای شرقی خلیج نیکومدیه را بنیان نهاد؛ شهر در سده‌های بعد مرکز بیتینیه و در دورهٔ دیوکلتیانوس پایتخت شرقی روم شد.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["جنگ نخست پونی آغاز شد: آپیوس کلاودیوس به مسانا گذشت", "636e1533"], "d": ["چون مامرتین‌ها در برابر هیرون، پادشاه سیراکوز، پس از کارتاژ از روم نیز برای مسانای خود یاری خواستند، کنسول روم آپیوس کلاودیوس کائودکس در 264 به سیسیل گذشت و مسانا را از پادگان کارتاژی گرفت. بدین‌سان روم نخستین بار بیرون از ایتالیا وارد جنگ شد.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["ولسینی سقوط کرد: واپسین شهر بزرگ مستقل اتروریا به روم رسید", "b6aed092"], "d": ["روم ولسینی را که بر اثر شورش بردگان از روم یاری خواسته بود، در 264 گرفت و ساکنان شهر را به جایی نو کوچاند. اتروریا از این پس عملاً زیر فرمان روم درآمد.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["پیروس در آرگوس درگذشت", "2b4996fa"], "d": ["پیروس در لشکرکشی پلوپونز، در نبرد خیابانی آرگوس با یک سفال زخمی شد و جان سپرد (272). اپیروس در برابر مقدونیه وزن خود را از دست داد و روابط خود را با روم از نو برقرار کرد.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["تارنتوم به روم تسلیم شد: ایتالیای جنوبی به روم پیوست", "6e87c924"], "d": ["پس از رفتن پیروس، پادگان اپیروسی تارنتوم عقب نشست و شهر به روم تسلیم شد (272). ایتالیای جنوبی، با بروتیوم و لوکانیا، شهرهای یونانی هم‌پیمان روم شدند؛ بدین‌سان روم بر شبه‌جزیرهٔ ایتالیا تا دشت پو چیره شد.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["مالونتوم (بنونتوم): پیروس از ایتالیا عقب نشست", "ab67e9f5"], "d": ["حملهٔ دوبارهٔ پیروس به روم پس از بازگشت از لشکرکشی سیسیل، در مالونتوم در برابر مانیوس کوریوس دنتاتوس ناکام ماند؛ پیروس در 275 به اپیروس بازگشت. او پادگانی کوچک در تارنتوم گذاشت؛ روم در ایتالیا بی‌رقیب ماند.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["آنتیوخوس یکم در «نبرد فیل‌ها» گالات‌ها را شکست داد", "1e88c2d0"], "d": ["آنتیوخوس یکم با فیل‌های خود گالات‌ها را شکست داد و لقب سوتر («نجات‌دهنده») گرفت؛ گالات‌ها به نظام اقامت، باج و غارت در آناتولی مرکزی بازگشتند. در سده‌های بعد کشمکش با پرگامون و بیتینیه ادامه یافت.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["آنتیگونوس گوناتاس پادشاه مقدونیه شد: سلسلهٔ آنتیگونی پایدار شد", "4b907dd6"], "d": ["گوناتاس در 277 در لیسیماخیه با شکست‌دادن گالات‌ها آوازه یافت و در 276 بر تخت مقدونیه نشست. سلسله تا 168 بر مقدونیه فرمان راند؛ دژهای کورنت، خالکیس و پیره را در یونان در دست داشت.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["نیکومدس یکم گالات‌ها را به آناتولی گذراند", "9e5ab10b"], "d": ["نیکومدس یکم، پادشاه بیتینیه، در برابر برادرش زیپویتس و فشار سلوکوس، قبایل گالات (کلت) را از بسفر گذراند و به خدمت گرفت؛ گالات‌ها بعدها در آناتولی مرکزی ساکن شدند؛ شاخهٔ تکتوساگ‌ها آنکارا (آنکیرا) را پایتخت کرد (TDV «Ankara»: «milattan önce 278-189 yılları arasında Trakya’dan gelen Galatlar’ın Tektosages kolunun başşehri oldu»). تاریخ گذر 278/277 است.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["اتحادیهٔ آیتولیا در برابر هجوم گالات‌ها از دلفی دفاع کرد", "5488966a"], "d": ["سپاه گالات به رهبری برنوس از ترموپیل گذشت و به دلفی پیش رفت؛ ایستادگی آیتولیایی‌ها و فوکیایی‌ها هجوم را پراکنده کرد. وزن آیتولیا در امفیکتیونی دلفی با این پیروزی افزون شد.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["پیروس به یاری تارنتوم به ایتالیا گذشت؛ در هراکلیا رومیان را شکست داد", "55f18e85"], "d": ["پیروس که با فراخوان تارنتوم بر ضد روم در 280 به ایتالیا پا نهاد، در هراکلیا سپاه والریوس لائوینوس را با فیل و سواره شکست داد اما تلفات سنگین داد. در 279 در آسکولوم دوباره پیروز شد و در 278-276 به سیسیل گذشت.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["اتحادیهٔ آخایا دوباره بنیان یافت: پاتراِی، دیمه، تریتایا، فارای", "81bba071"], "d": ["در آخایای زیر نظارت آنتیگونی‌ها، چهار شهر (دیمه، پاترای، تریتایا، فارای) در 280 پیش از میلاد اتحادیه‌ای فدرال را دوباره بنیان نهادند؛ در سال‌های بعد آیگیون و شهرهای دیگر پیوستند. اتحادیه به رهبری آراتوس به قدرت بزرگ پلوپونز بدل شد.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["فیلتایروس پس از کوروپدیون به سلوکوس پیوست؛ پرگامون عملاً سلسله‌ای مستقل بنیان نهاد", "ac6b3e31"], "d": ["پس از سقوط لیسیماخوس، فیلتایروس با خزانه به سلوکوس پیوست و پرگامون را نگه داشت و ثروتمند ساخت؛ با مرگ سلوکوس (281) عملاً مستقل شد. لیویوس می‌نویسد سلسلهٔ آتالی از 283 تا 129 بر پرگامون فرمان راند.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["لیسیماخوس پیروس را از مقدونیه راند و یگانه پادشاه مقدونیه شد", "a83e6c64"], "d": ["پس از زمستان 285 که دمتریوس به سلوکوس تسلیم شد، لیسیماخوس پیروس را از مقدونیه راند و کشور را به‌تنهایی اداره کرد. دولتش به ناحیه‌ای گسترده شامل تراکیه، مقدونیه و آناتولی باختری رسید.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["پیروس و لیسیماخوس مقدونیه را تقسیم کردند؛ دمتریوس پولیورکتس برافتاد", "63371ab8"], "d": ["در تابستان 287 با گذشتن دمتریوس به آسیا، پیروس و لیسیماخوس مقدونیه را میان خود به دو ناحیه تقسیم کردند؛ دمتریوس فرو افتاد. این تقسیم تنها دو سال ماند.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["سامنیوم به روم پیوست: جنگ سوم سامنی پایان یافت", "bede9942"], "d": ["مانیوس کوریوس دنتاتوس سامنی‌ها و سابین‌ها را قطعاً شکست داد؛ سامنیوم هم‌پیمان روم شد. روم بر ایتالیای میانه چیره شد و با شهرهای یونانی ایتالیای جنوبی (تارنتوم) رو در رو گشت.", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["دمتریوس پولیورکتس پادشاه مقدونیه اعلام شد", "a2b1eba3"], "d": ["دمتریوس که از کشمکش بر سر تخت در خاندان کاساندروس بهره برد، در پاییز 294 به دست سپاه پادشاه مقدونیه اعلام شد. این نخستین فرمانروایی تبار آنتیگونوس در مقدونیه است؛ در 288 فروپاشید و گوناتاس آن را در 276 پایدار کرد.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["سنتینوم: اتحاد اتروسک‌ها، اومبری‌ها، سامنی‌ها و گالی‌ها از روم شکست خورد", "b5affc1b"], "d": ["در جنگ سوم سامنی، نبرد سنتینوم واپسین اتحاد بزرگ ضدرومی در ایتالیا را نابود کرد؛ شهرهای اتروسک یکی‌یکی به هم‌پیمانی با روم واداشته شدند.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["پیروس با پشتیبانی بطلمیوس به تخت اپیروس بازگشت", "6288bf69"], "d": ["پیروس که پس از ایپسوس در مصر گروگان مانده بود، با یاری بطلمیوس به اپیروس بازگشت و تخت را بازپس گرفت. اپیروس از این پس در کار مقدونیه و ایتالیا صاحب‌سخن شد.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["لیسیماخوس خزانهٔ خود را در پرگامون نهاد؛ فیلتایروس نگهبان دژ شد", "e1b4ab77"], "d": ["پس از ایپسوس، لیسیماخوس خزانهٔ خود را در دژ فراز تپهٔ پرگامون نگه داشت و نگهبانی آن را به فیلتایروس خواجه سپرد. فیلتایروس در 281 به سلوکوس پیوست و پایهٔ سلسله را نهاد.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["میترادات یکم کتیستس سلسلهٔ پونتوس را بنیان نهاد", "490c338c"], "d": ["میترادات که به آنتیگونوس مونوفتالموس نزدیک شده بود، در 302 از خطر کشته‌شدن گریخت و در منطقهٔ کوهستانی پونتوس کاپادوکیه به کیمیاتا پناه برد و در آنجا هستهٔ پادشاهی پونتوس را شکل داد. سلسله تا 63 ادامه یافت.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["محاصرهٔ رودس به دست دمتریوس پولیورکتس با ناکامی پایان یافت", "dae6f4d6"], "d": ["دمتریوس رودس را که در برابر آنتیگونوس در کنار بطلمیوس مانده بود، در 305 با ماشین‌های محاصرهٔ عظیم دور زد؛ رودسی‌ها یک سال ایستادند و در تابستان 304 صلح شد. در شهر، کولوسوس هلیوس، خدای خورشید، با بهای این پیروزی برپا شد.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["سالامیس قبرس: دمتریوس بطلمیوس را شکست داد؛ آنتیگونوس و دمتریوس عنوان پادشاهی گرفتند", "cc308941"], "d": ["در بهار 306 دمتریوس پولیورکتس در برابر قبرس ناوگان بطلمیوس را شکست داد و قبرس را به دست آنتیگونوس سپرد؛ در تابستان آنتیگونوس و دمتریوس عنوان پادشاهی را گرفتند و دیادوخوی‌های دیگر نیز اندکی بعد همین عنوان را برگرفتند. بطلمیوس قبرس را در 294 بازپس گرفت.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["لیسیماخوس لیسیماخیه را بنیان نهاد: پایتخت در خرسونسوس تراکیه", "83b83160"], "d": ["لیسیماخوس لیسیماخیه را که در گلوگاه شبه‌جزیرهٔ گلی‌بولی بنا کرد، پایتخت پادشاهی تراکیه ساخت؛ گذرگاه تنگه و داردانل در دست او گرد آمد. شهر در سدهٔ 3 پیش از میلاد با زلزله ویران شد.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["صلح دیادوخوی‌ها: آنتیگونوس فرمانروایی آسیا، کاساندروس اروپا و بطلمیوس مصر را شناختند", "811c80f0"], "d": ["در صلح امضاشده در دسامبر 311، آنتیگونوس فرمانده آسیا، کاساندروس استراتگوس اروپا، لیسیماخوس فرمانروای تراکیه و بطلمیوس فرمانروای مصر و پیرامون آن شناخته شد؛ اصل آزادی شهرهای یونانی گنجانده شد. بابلِ سلوکوس بیرون از این صلح ماند.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["صور به آنتیگونوس رسید: فنیقیه از بطلمیوس گرفته شد", "30f78257"], "d": ["آنتیگونوس در 315 به سوریه درآمد، فنیقیه را گرفت و صور را محاصره کرد؛ شهر در 314 سقوط کرد. کرانهٔ فنیقیه و ساحل تا غزه به دست او افتاد (غزه در نبرد غزه در 312 به بطلمیوس بازگردانده شد).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["کاساندروس سالونیک را بنیان نهاد", "7043bd8a"], "d": ["کاساندروس بیش از بیست سکونتگاه شمال خلیج ترمایی را یکی کرد و به نام همسرش (دختر فیلیپ دوم) تسالونیکه شهری بنیان نهاد. سالونیک هزار سال بعد مهم‌ترین بندر مقدونیه بود.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["کاساندروس تِبای را دوباره بنا کرد", "0167e784"], "d": ["تبایی که اسکندر ویران کرده بود، با پشتیبانی کاساندروس و کمک‌های آتن و اوبویا، دیوارهایش بازسازی و شهر دوباره بنیان یافت. اتحادیهٔ بوئوتیا دوباره مرکز یافت.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["گابیِنه: آنتیگونوس اومنس را شکست داد و فرمانروای آسیا تا ایران شد", "d2990dfd"], "d": ["در زمستان 316/5 در گابینه سپاه اومنس درهم شکست؛ فرماندهٔ آن به دست سربازان خود به آنتیگونوس تسلیم و اعدام شد. آنتیگونوس یگانه فرمانروای ناحیه‌ای گسترده از فلات ایران تا آناتولی شد؛ سلوکوس به مصر گریخت.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["سامان تریپارادیسوس: آنتیگونوس مونوفتالموس استراتگوس آسیا شد", "69f6fafb"], "d": ["پس از کشته‌شدن پردیکاس در مصر (مه 320)، آنتیپاتروس در تریپارادیسوس ساتراپی‌ها را دوباره بخش کرد؛ آنتیگونوس به‌سرداری نیروهای آسیا رسید و سلوکوس بابل را گرفت. آنتیگونوس از این جایگاه به بنیان امپراتوری خود پرداخت.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["کرانون: جنگ لامیا باخته شد؛ پادگان مقدونی وارد آتن شد، دموکراسی به تعلیق درآمد", "6931c4f6"], "d": ["در 5 سپتامبر 322 در کرانون اتحاد یونانی از آنتیپاتروس و کراتروس شکست خورد؛ آتن پذیرفت پادگان مقدونی را در مونیخیا بپذیرد و معیار شهروندی را به مالکان محدود کند. دموستن خودکشی کرد؛ دموکراسی کلاسیک آتن عملاً پایان یافت.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["جنگ لامیا: شهرهای یونانی پس از مرگ اسکندر بر ضد هژمونی مقدونی برخاستند", "c31c7da4"], "d": ["با خبر مرگ اسکندر (ژوئن 323) آتن و اتحادیهٔ آیتولیا بر ضد آنتیپاتروس شورش کردند؛ آنتیپاتروس در لامیا محاصره شد. جنگ با پیروزی مقدونیه در کرانون (سپتامبر 322) پایان یافت و برتری مقدونی در چارچوب اتحادیهٔ کورنت دوباره برقرار شد.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["هیداسپس: پوروس شکست خورد؛ پنجاب به اسکندر پیوست", "abab206b"], "d": ["در مه 326 اسکندر با پشتیبانی آمبهی، راجای تاکسیلا، از جهلم گذشت و پوروس را شکست داد؛ پادشاهی پوروس به‌عنوان دست‌نشانده به اسکندر وانهاده شد. اسکندر از این نقطه به سوی شرق پیش رفت اما در هیفاسیس با اعتراض سپاه متوقف شد.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["در کرانهٔ هیفاسیس (بیاس) سپاه از پیشروی سر باز زد: مرز شرقی اسکندر", "17b23afc"], "d": ["به سبب بارش‌های موسمی و خستگی، سپاه مقدونی از گذشتن از هیفاسیس سر باز زد؛ اسکندر دوازده قربانگاه برپا کرد و ناچار بازگشت. هیفاسیس انتهای شرقی فتوحات مقدونی در هند شد.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["باختر و سغد به اسکندر گردن نهادند؛ اسکندر با روکسانه ازدواج کرد", "a050508d"], "d": ["در 329-327 ناحیهٔ آن‌سوی آمودریا با مبارزهٔ چریکی سخت گرفته شد؛ اسپیتامنس کشته شد و صخرهٔ سغد و دژ خورینس تسلیم شد. اسکندر با روکسانه، شاهدخت باختری، ازدواج کرد و اشراف محلی را به اداره پیوست.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["کرانهٔ آناتولی باختری به اسکندر رسید: افسوس، میلتوس و هالیکارناسوس", "f67084a4"], "d": ["افسوس با رژیم دموکراتیک دروازه‌ها را گشود، میلتوس در پایان محاصره (تابستان 334) گرفته شد؛ محاصرهٔ هالیکارناسوس در پاییز با سقوط شهر پایان یافت و ساتراپی کاریه به آدا داده شد. اسکندر بدین‌سان راهبرد گرفتن بندرهای ناوگان پارسی را از راه خشکی به کار بست.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["تبای به فرمان اسکندر ویران شد", "26c4193c"], "d": ["اسکندر تبایی را که با مرگ فیلیپ شورش کرده بود، در پاییز گرفت؛ در کادمئا پادگان مقدونی نهاد، شهر را ویران کرد و مردمش را به بردگی گرفت (جز خانهٔ پیندار). اتحادیهٔ بوئوتیا با این ویرانی عملاً پایان یافت (در 316 کاساندروس آن را دوباره بنا کرد).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["فیلیپ دوم در آیگای کشته شد؛ اسکندر بر تخت نشست", "417d909e"], "d": ["فیلیپ در جشن عروسی دخترش کلئوپاترا در تئاتر به دست نگهبان خود پاوزانیاس کشته شد و به جای او پسرش اسکندر به دست سپاه پادشاه اعلام شد. لشکرکشی به ایران و نظارت بر یونان به اسکندر ماند.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["اتحادیهٔ کورنت بنیان یافت: شهرهای یونانی زیر هژمونی فیلیپ دوم یکی شدند", "c38074dc"], "d": ["پس از خایرونیا، فیلیپ شهرهای یونانی را در کورنت زیر صلح همگانی (koine eirene) و پیمان دفاع مشترک گرد آورد؛ دربارهٔ سرباز برای لشکرکشی به ایران و فرماندهی هگمون تصمیم گرفته شد. تنها اسپارت شرکت نکرد.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["خایرونیا: فیلیپ سپاه آتن و تبای را شکست داد و نظارت بر یونان را به دست گرفت", "5e5d77e7"], "d": ["در اوت 338 در دشت خایرونیا با حملهٔ سواره‌نظام که اسکندر جوان فرمان می‌داد، سپاه آتن و تبای درهم شکست؛ در تبای پادگان مقدونی نهاده شد، آتن با گذشت بخشوده شد. این پیروزی استقلال شهرهای یونانی را پایان داد و راه اتحادیهٔ کورنت را گشود.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["اتحادیهٔ لاتین منحل شد: لاتیوم به روم پیوست", "58849f84"], "d": ["در پایان جنگ لاتین (340-338)، روم اتحادیهٔ لاتین را فسخ کرد؛ شهرها یا به تابعیت رومی پیوستند یا یک‌یک به روم وابسته شدند و پیمان میان خودشان ممنوع شد. این شالودهٔ الگوی گسترش روم در ایتالیاست.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["فیلیپ دوم آتئاس، پادشاه سکاها، را شکست داد", "e4dee658"], "d": ["نبرد آتئاس با فیلیپ در کرانه‌های ایستروس (دانوب) با کشته‌شدن آتئاس پایان یافت؛ فیلیپ در بازگشت از تریبالی‌ها هجوم دید. نیروی سکایی به باختر، آن‌سوی دانوب، جابه‌جا شد.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["فیلیپ تراکیه را همراه با سلسلهٔ اودریس به زیر یوغ گرفت", "b543427a"], "d": ["فیلیپ در لشکرکشی‌های 342-341 پیش از میلاد به درون تراکیه پیش رفت، کرسوبلپتس، پادشاه اودریس، را باج‌گزار کرد و شهرهایی چون فیلیپوپولیس (فیلیبه) بنیان نهاد. تراکیه امتداد شرقی مقدونیه شد.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["ویرانی اولینتوس: اتحادیهٔ خالکیدیکی به مقدونیه پیوست", "89d77301"], "d": ["با آنکه اولینتوس از آتن یاری خواست، فیلیپ شهر را با خیانت گرفت و ویران کرد؛ شبه‌جزیرهٔ خالکیدیکی به مقدونیه پیوست. سخنرانی‌های اولینتیاکای دموستنس بر همین فراخوان استوار است.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["جنگ هم‌پیمانان پایان یافت: بیزانس، خیوس، رودس و کوس از اتحادیهٔ دوم آتن جدا شدند", "856a9763"], "d": ["شورشی که در 357 پیش از میلاد آغاز شده بود، با شکست فرماندهان آتنی در خیوس و رویارویی پشتیبانی ایران با آتن، به پذیرش صلح از سوی آتن انجامید؛ چهار عضو مهم استقلال یافتند. اتحادیه ناتوان شد و در برابر مقدونیه بی‌دفاع ماند.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["فیلیپ آمفیپولیس را از آتن گرفت", "2c793bc6"], "d": ["فیلیپ که آمفیپولیس آتن را در دهانهٔ استریمون محاصره کرد و گرفت، به معادن طلا و نقره و منابع چوب شهر دست یافت و به کرانهٔ تراکیه گشوده شد. این فتح کشمکش آتن و مقدونیه را آغاز کرد.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["فیلیپ دوم پادشاه مقدونیه شد", "d557268d"], "d": ["با مرگ پردیکاس سوم در جنگ با ایلیری‌ها (360/359 پیش از میلاد)، فیلیپ نخست نایب و سپس پادشاه شد؛ تهدیدهای ایلیریا، پایونیا و تراکیه را دفع کرد و اصلاح سپاه (فالانکس ساریسا) را انجام داد. برآمدن مقدونیه با این پادشاهی آغاز می‌شود.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["مانتینیا: اپامینونداس درگذشت، هژمونی بوئوتیا پایان یافت", "94be8d5c"], "d": ["سپاه تبای جنگ را برد اما اپامینونداس زخمی شد و درگذشت؛ گزنفون با این سخن پایان می‌دهد: «ناپایداری و آشفتگی در یونان بیش از پیش شد». هژمونی کوتاه تبای در همان سال پایان یافت، توازن آتن-اسپارت-تبای ماند.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["اتحادیهٔ آرکادیا بنیان یافت: این بخش از اتحادیهٔ پلوپونز فروپاشید", "42fdc676"], "d": ["پس از لئوکترا، شهرهای آرکادیا با پشتیبانی تبای اتحادیه‌ای فدرال بنیان نهادند و پایتخت تازهٔ مگالوپولیس را ساختند. بدین‌سان اتحادیهٔ پلوپونزِ اسپارت عملاً فروپاشید؛ اسپارت تنها به لاکونیا عقب نشست.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["مسنیا از اسپارت جدا شد؛ مسنه بنیان یافت", "e4ef9302"], "d": ["در لشکرکشی اپامینونداس به پلوپونز پس از لئوکترا (زمستان 370/69)، هلوت‌های مسنیا آزاد شدند و شهر استوارِ دیوارداری به نام مسنه در دامنهٔ کوه ایتومه بنا شد. اسپارت پس از سده‌ها نخستین بار سرزمین‌های مسنیا را که پایهٔ اقتصادی‌اش بود از دست داد.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["لئوکترا: سپاه تبای اسپارتی‌ها را شکست داد؛ اسپارت برتری زمینی را از دست داد", "e7829597"], "d": ["آرایش انباشت عمیق جناح راست اپامینونداس، نیروی اسپارتی پادشاه کلئومبروتوس را در لئوکترا درهم شکست؛ با مرگ حدود 400 اسپارتیات، اسپارت دیگر نتوانست کاهش جمعیت را جبران کند. دورهٔ هژمونی به رهبری تبای آغاز شد.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["اتحادیهٔ دوم آتن بنیان یافت (فرمان ارسطو)", "0e5dcaf2"], "d": ["آتن بر ضد اسپارت با اصل خودمختاری و باج‌نگرفتن شهرهای اژه را به اتحادیه فراخواند؛ فرمان با پیشنهاد ارسطو صادر شد و فهرست شهرهای عضو بر سنگ نوشته شد. بنیان اتحادیه آتن را دوباره قدرت دریایی ساخت.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["پلوپیداس تبای را رهانید؛ پادگان اسپارت از کادمئا رانده شد", "eb15a9d7"], "d": ["کادمئای تبای که اسپارت در 382 پیش از میلاد گرفته و پادگان در آن نهاده بود، با شبیخون تبعیدیان بازپس گرفته شد؛ تبای دوباره مرکز اتحادیهٔ بوئوتیا شد. این رویداد آغاز از هم‌پاشیدن هژمونی اسپارت است.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["آلیا: گالی‌ها سپاه روم را شکست دادند و شهر را غارت کردند", "db864bc9"], "d": ["گالی‌های سنون در کرانهٔ آلیا، از شاخه‌های تیبر، سپاه روم را درهم شکستند؛ روم جز کاپیتولیوم اشغال و غارت شد. لیویوس می‌نویسد «روز آلیا» (18 ژوئیه) نزد رومیان شوم شمرده شد.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["کورنت با آرگوس یکی شد (ایزوپولیتیای آرگوس-کورنت)", "135a3d3a"], "d": ["کورنت در جنگ کورنت (395-387 پیش از میلاد) با آرگوس اتحاد شهروندی مشترک بنیان نهاد؛ پادگان آرگوسی در کورنت ماند. اسپارت با صلح شاه (386) این یکی‌شدن را برهم زد.", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["وئی به روم افتاد: نخستین شهر بزرگ اتروریا در جنوب از دست رفت", "0d1c4fe4"], "d": ["پس از ده سال محاصره، کامیلوس وئی را گرفت (در سنت 396 پیش از میلاد)؛ مردم شهر به بردگی رفتند، سرزمین‌هایش به روم پیوست و ager Romanus روم تقریباً دو برابر شد. نیروی شهرهای اتروسک در جنوب تیبر شکست.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["آتن به اسپارت تسلیم شد؛ امپراتوری دریایی آتن و اتحادیهٔ دلوس پایان یافت", "43f2ddf9"], "d": ["آتن که در آیگوسپوتامی ناوگان خود را از دست داده بود، از گرسنگی تسلیم شد؛ دیوارهای بلند ویران شد، امپراتوری دریایی فروپاشید و در شهر حکومت سی تن که اسپارتی‌ها برپا کردند آمد. در جزایر و کرانه‌های تراکیه که پیشتر عضو اتحادیه بودند، حکومت‌های دکارکی که لیساندروس بنیان نهاد و پادگان‌های اسپارت جای گرفت.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["دیونیسیوس یکم در سیراکوز ستمگر شد", "1ad10305"], "d": ["دیونیسیوس در سال‌هایی که کارتاژ آکراگاس و گلا را گرفت، در 405 استراتگوس و سپس ستمگر سیراکوز شد؛ با کارتاژ صلح کرد (405) و شهرهای یونانی سیسیل را به خود پیوست. قدرت دیونیسیوس که 38 سال ادامه یافت، سیسیل را به یکی از قدرت‌های بزرگ مدیترانه بدل کرد.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["آیگوسپوتامی: ناوگان آتن نابود شد؛ اتحادیهٔ دلوس در آستانهٔ فروپاشی", "ce62187c"], "d": ["در سپتامبر 405 لیساندروس ناوگان آتن را که در آیگوسپوتامی لنگر انداخته بود، با شبیخون گرفت؛ تقریباً همهٔ ناوگان و هزاران اسیر از دست رفت. راه هلسپونت بسته شد و رسانش غلهٔ آتن قطع گشت؛ چند ماه بعد آتن تسلیم شد.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["شهر رودس بنیان یافت: لیندوس، یالیسوس و کامیروس یکی شدند", "2de55901"], "d": ["در 408 پیش از میلاد سه شهر جزیرهٔ رودس دولتی مشترک بنیان نهادند و در شهر تازهٔ رودس یکی شدند؛ شهری که با طرح هیپودامُس ساخته شد، از مهم‌ترین پایگاه‌های دریایی و مراکز تجاری جهان هلنی گشت.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["هانیبال ماگو سلینوس و هیمرا را ویران کرد: کارتاژ در سیسیل باختری جای گرفت", "358f4417"], "d": ["هانیبال ماگو که با فراخوان یاری سگستا به سیسیل پا نهاد، در 409 پیش از میلاد سلینوس و هیمرا را گرفت؛ ناحیه به epikratia کارتاژ بدل شد. کشمکش کارتاژ و سیراکوز دو سده ادامه یافت.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["لشکرکشی سیسیل به فاجعه انجامید: سپاه آتن در برابر سیراکوز نابود شد", "b363df0d"], "d": ["لشکرکشی سیسیل که آتن در 415 پیش از میلاد آغاز کرده بود، پس از ناتوانی در محاصرهٔ سیراکوز، در عقب‌نشینی نیکیاس و دموستنس در کرانهٔ رود آسیناروس با تسلیم (پاییز 413 پیش از میلاد) پایان یافت. آتن سپاه و بخش بزرگ ناوگان خود را از دست داد.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["سیتالکس با آتن متحد شد: پادشاهی اودریس به جنگ پلوپونز پیوست", "4562f13d"], "d": ["آتن پسر سیتالکس را شهروند آتن کرد و با او اتحاد بست؛ سیتالکس در 429 به مقدونیه حمله برد. قدرت اودریس در این دوره به اوج رسید.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["جنگ پلوپونز آغاز شد: اتحادیهٔ پلوپونز بر ضد آتن بسیج شد", "2adee4a1"], "d": ["با شبیخون شبانهٔ تبای به پلاتایا (بهار 431) صلح عملاً شکسته شد؛ در آغاز تابستان سپاه اتحادیهٔ پلوپونز به فرماندهی پادشاه آرخیداموس به آتیکا هجوم برد. جنگ میان امپراتوری دریایی آتن و اتحادیهٔ زمینی اسپارت 27 سال ادامه یافت.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["سیبوتا: جنگ کورنت و کورکیرا آتن را به مداخله کشاند", "dc07b0ac"], "d": ["در نبرد دریایی کورنت و مستعمرهٔ آن کورکیرا بر سر اپیدامنوس، آتن از کورکیرا پشتیبانی کرد. خشم کورنت از آتن یکی از علل مستقیم جنگ پلوپونز شد.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["اسپارتوکوس در بوسپوروس آرخون شد: سلسلهٔ اسپارتوکیدها", "ddc76f79"], "d": ["اسپارتوکوس با ریشهٔ تراکیایی جای سلسلهٔ آرخه‌آناکتیدها را در پانتیکاپایون گرفت (438/7)؛ سلسلهٔ اسپارتوکیدها پادشاهی بوسپوروس را بنیان نهاد و صادرات غله به آتن را اداره کرد. سلسله تا 109 پیش از میلاد ادامه یافت.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["صلح سی ساله: آتن امپراتوری زمینی خود (بوئوتیا، مگارا، آخایا) را از دست داد", "4f33ff13"], "d": ["پس از شکست آتن از بوئوتیایی‌ها در کورونیا (447)، سپس شورش‌های اوبویا و مگارا و هجوم اسپارت به آتیکا، آتن صلح سی ساله را امضا کرد. آتن مگارا، نیسایا، پگای و ترُزن و آخایا در پلوپونز را رها کرد؛ تنها امپراتوری دریایی را نگه داشت.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["ترِس پادشاهی اودریس را بنیان نهاد: نخستین دولت بزرگ تراکیه", "83caf189"], "d": ["توکودیدس می‌نویسد ترس نخستین پادشاهی بزرگ را در تراکیه بنیان نهاد؛ پسرش سیتالکس پادشاهی را از دانوب تا اژه رساند. پادشاهی اودریس میان آتن، مقدونیه و ایران سیاست توازن پیش گرفت.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["خزانهٔ اتحادیه از دلوس به آتن برده شد", "173f2e5b"], "d": ["به بهانهٔ شکست در لشکرکشی مصر و هراس از ناوگان ایران، خزانهٔ مشترک از دلوس به آتن برده شد؛ فهرست‌های سهم «یک‌شصتم» که به ایزدبانوی آتن داده می‌شد از این سال آغاز می‌شود. این گام نشانهٔ بدل‌شدن عملی اتحادیه به امپراتوری آتن تفسیر می‌شود.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["شورش تاسوس سرکوب شد؛ اتحادیهٔ دلوس به امپراتوری‌ای بدل شد که اعضایش نمی‌توانستند از آن جدا شوند", "d24bd124"], "d": ["تاسوس بر سر معادن با آتن درگیر شد و کوشید از اتحادیه جدا شود؛ پس از محاصرهٔ دو ساله (463 پیش از میلاد) دیوارهایش را ویران کرد، ناوگانش را تسلیم نمود و ناحیهٔ معدنی کرانهٔ تراکیه را از دست داد. این رویداد نخستین نمونه‌ای است که نشان می‌دهد عضویت در اتحادیه را نمی‌توان رها کرد.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["نبرد دریایی کومه (کوماى): سیراکوز ناوگان اتروسک را شکست داد، قدرت دریایی اتروسک شکست", "2e81670b"], "d": ["به فراخوان یاری کومه، هیرون یکم، ستمگر سیراکوز، ناوگان اتروسک را در برابر کومه درهم شکست؛ هیرون پیروزی را با پیشکش کلاهخودی به دلفی جشن گرفت (کلاهخود اتروسکی که لیویوس یاد می‌کند). چیرگی اتروسک‌ها در کامپانیا لرزید.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["اتحادیهٔ دلوس بنیان یافت: اتحاد اژه به ریاست آتن", "f0de153a"], "d": ["پس از شیوهٔ فرمانروایی پاوزانیاس، شهرهای ایونی از آتن رهبری خواستند؛ با باجی که آریستیدس تعیین کرد (460 تالنت) در دلوس خزانهٔ مشترک بنیان یافت. اتحادیه به آتن ناوگان پیوسته و پایهٔ مالیاتی بر اژه داد.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["سالامیس (29 سپتامبر 480) و پلاتایا: هجوم ایران پس زده شد", "479b17e6"], "d": ["پس از آنکه خشایارشا آتن را گرفت و سوزاند، با دام تمیستوکلس ناوگان ایران در تنگهٔ سالامیس درهم شکست (29 سپتامبر 480)؛ سال بعد در پلاتایا سپاه زمینی یونانیان به فرماندهی پاوزانیاس مردونیوس را شکست داد و هجوم را پایان بخشید. بدین‌سان یونان اژه‌ای از سلطهٔ ایران رها شد.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["هیمرا: یونانیان سیسیل سپاه کارتاژ را شکست دادند", "ece09580"], "d": ["اتحاد گلون و ترون سپاه کارتاژی هامیلکار را در برابر هیمرا درهم شکست؛ کارتاژ نیم سده نتوانست دوباره لشکرکشی بزرگی به سیسیل کند. به گفتهٔ هرودوت و دیودوروس، سالامیس همان روز پیروز شد (سنت).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["ماراتن: آتن یورش ایرانیان را متوقف کرد", "0967ce7c"], "d": ["هوپلیت‌های آتن و پلاتایا به فرماندهی میلتیادس در دشت ماراتن نیروی ایران را شکست دادند و از پیاده‌شدن در آتیکا جلوگیری کردند. این پیروزی به اعتمادبه‌نفس دموکراسی آتن و سیاست دریایی‌ای که به اتحادیهٔ دلوس رسید دامن زد.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["مردونیوس مقدونیه را تابع ایران کرد", "7bde569c"], "d": ["مردونیوس، داماد داریوش، از تراکیه گذشت و مقدونیه را زیر فرمان ایران درآورد؛ پادشاه مقدونیه به ایران خاک و آب داد. مقدونیه این وابستگی را پس از پلاتایا (479) رها کرد.", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: روم با اتحادیهٔ لاتین متحد شد", "56db407d"], "d": ["با پیمانی که نام اسپوریوس کاسیوس را دارد، روم و اتحادیهٔ لاتین بر پایهٔ دفاع متقابل، تقسیم غنیمت و سپاه مشترک اتحاد بستند. این پیمان تا جنگ لاتین (340-338) چارچوب روابط روم و لاتیوم است.", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["با عقب‌نشینی کورنت، لشکرکشی اتحادیهٔ پلوپونز به آتن از هم پاشید", "b44adf6b"], "d": ["اسپارت سپاه اتحادیهٔ پلوپونز را بر ضد آتنِ دموکراتیک کلایستنس به آتیکا راند؛ عقب‌نشینی سپاه کورنت در الئوسیس و اختلاف دو پادشاه اسپارت لشکرکشی را فروریخت. این رویداد نخستین نمونهٔ شناخته‌شده از آغاز کارآمدشدن حق رأی هم‌پیمانان در مجمع اتحادیه شمرده می‌شود.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["اصلاحات کلایستنس: شالودهٔ نهادی دموکراسی آتن نهاده شد", "b2421c86"], "d": ["پس از سقوط هیپیاس، کلایستنس شهروندان را بر پایهٔ دموس‌ها که واحد سکونت بودند و ده قبیلهٔ نو سازمان داد؛ شورای پانصد نفری محور این نظم شد. این سامانی است که مفاهیم ایزونومیا و دموکراتیا در آن زاده شد.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["واپسین پادشاه تارکوینیوس سوپربوس رانده شد؛ پادشاهی پایان یافت، جمهوری آغاز شد", "5a4a9061"], "d": ["به گفتهٔ لیویوس، تارکوینیوس سوپربوس و خانواده‌اش در 509 پیش از میلاد از شهر رانده شدند و نخستین کنسول‌ها (بروتوس، کولاتینوس) برگزیده شدند. پولیبیوس نخستین پیمان روم و کارتاژ را به سال نخستین کنسول‌ها می‌بندد؛ این تاریخ در تاریخ‌نگاری نوین «سنت» شمرده می‌شود، هرچند به پایان سدهٔ 6 پیش از میلاد می‌نشیند.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["نخستین پیمان میان روم و کارتاژ (پولیبیوس 3.22)", "cdef940f"], "d": ["پولیبیوس پیمانی را که در سال نخستین کنسول‌ها میان روم و کارتاژ بسته شد و کرانه‌های لاتیوم را به روم و باختر سیسیل و لیبی را به کارتاژ جدا می‌کرد، با متن آن نقل می‌کند. روم به‌عنوان سرور لاتیوم یاد می‌شود.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["نبرد دریایی آلالیا: اتروسک‌ها و کارتاژی‌ها فوکایی‌ها را از کورسیکا راندند", "25efbea8"], "d": ["یونانیان فوکایی در آلالیا بر کاغذ پیروز شدند اما بیشتر ناوگان خود را از دست دادند؛ کورسیکا را رها کردند و به الئا در ایتالیای جنوبی عقب نشستند. در جزیره، فرمانروایی اتروسک (کایره) برقرار شد.", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["پیمان اسپارت-تگئا: هستهٔ اتحادیهٔ پلوپونز شکل گرفت", "57098e47"], "d": ["اسپارت تگئا را در آرکادیا شکست داد و او را به پذیرش اتحادی جاودان (symmachia) در برابر دست‌نزدن به سرزمین‌هایش واداشت؛ همین الگو به شهرهای پلوپونز گسترد و اتحادیهٔ پلوپونز به ریاست اسپارت زاده شد. اتحادیه در درون خود به‌صورت مجمع اسپارت و هم‌پیمانان (زیر فرماندهی اسپارت) کار می‌کرد.", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["فوکایی‌ها ماسالیا (مارسی) را بنیان نهادند", "5d46bdf2"], "d": ["مستعمره‌نشینان فوکایی در حدود 600 پیش از میلاد در دهانهٔ رون ماسالیا را بنیان نهادند؛ شهر در مدیترانهٔ باختری مرکز تجارت یونانی و تماس با جهان کلت شد.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["باتوس تراایی کورنه را بنیان نهاد", "67fd477f"], "d": ["مستعمره‌نشینان آمده از ترا بر پایهٔ پیشگویی دلفی به رهبری باتوس کورنه را بنیان نهادند؛ سلسلهٔ باتیادها تا 440 فرمان راند. لیویوس تاریخ بنیان را «حدود 630» می‌دهد.", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["اسپارت جنگ نخست مسنیا را برد: مسنیا به اسپارت پیوست", "74ad461c"], "d": ["در سنتی که پاوسانیاس نقل می‌کند، جنگ نخست مسنیا بیست سال ادامه یافت و با سقوط ایتومه دشت مسنیا به اسپارت رسید؛ مردم به جایگاه هلوت فروکاسته شدند. این فتح رویداد بنیادینی شمرده شد که نیروی کشاورزی و جامعهٔ نظامی اسپارت را تعیین کرد.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["سیراکوز به دست آرخیاس کورنتی بنیان نهاده شد", "10217104"], "d": ["به گفتهٔ توکودیدس، آرخیاس کورنتی یک سال پس از ناکسوس سیراکوز را بنیان نهاد. شهر بزرگ‌ترین شهر یونانی سیسیل شد.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["بنیان سنتی کارتاژ (تیمایوس: 814/813 پیش از میلاد)", "908099b5"], "d": ["به گفتهٔ تیمایوس، کارتاژ در 814/813 پیش از میلاد به دست مستعمره‌نشینان صوری بنیان یافت؛ یوستینوس 825 می‌دهد. لایه‌های باستان‌شناختی به پایان سدهٔ 8 پیش از میلاد اشاره دارند.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["مراکز کاخی میکنی ویران شد: نظام کاخی در پلوپونز فروپاشید", "d2c79152"], "d": ["در پایان هلادیک متأخر IIIB / آغاز IIIC، مراکز کاخی در پیلوس، تیرینس و میکنه لایهٔ ویرانی یا ترک نشان می‌دهند؛ اقتصاد کاخی مبتنی بر خط خطی ب پایان می‌یابد. علت ویرانی (زلزله، کشمکش داخلی، اقوام دریایی، خشکسالی) محل بحث است؛ لایه‌های ویرانی به یک سال محدود نیستند و به چند دهه گسترده‌اند.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["ویرانی کاخ‌های مینوسی در کرت؛ نظارت میکنی در کنوسوس آغاز شد", "1a7f7f2b"], "d": ["در پایان مینوسی متأخر IB (میانهٔ سدهٔ 15 پیش از میلاد) مراکز کاخی و ویلاهای کرت ویران می‌شوند؛ در مرحلهٔ بعدی در کنوسوس، لوح‌های خط خطی ب که به یونانی نوشته شده‌اند، اداره‌ای کاخی، یعنی نظارت میکنی، را نشان می‌دهند. بدین‌سان فرمانروایی مینوسی در کرت پایان می‌یابد.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["جنگل توتوبورگ: سه لژیون وارُس نابود شد؛ روم خط البه را رها کرد", "1684ae43"], "d": ["در 9 میلادی ائتلاف ژرمن‌ها به رهبری آرمینیوس لژیون‌های هفدهم، هجدهم و نوزدهم پ. کوینکتیلیوس وارُس را در جنگل توتوبورگ نابود کرد. آگوستوس از فتوحات آن‌سوی راین دست کشید و مرز راین پایدار شد.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["آگوستوس درگذشت؛ تیبریوس امپراتور شد", "0221344d"], "d": ["آگوستوس در 19 اوت 14 در نولا درگذشت؛ تیبریوس جانشین او شد. بدین‌سان اصل جانشینی (فرزندخواندگی از خاندان) در پرینکیپات پایدار شد.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["پادشاه بطلمیوس به دست کالیگولا کشته شد؛ استقلال موریتانیا پایان یافت", "11337627"], "d": ["بطلمیوس، پسر یوبا دوم، در 40 میلادی در لوگدونوم به فرمان کالیگولا کشته شد؛ سپس در موریتانیا شورش آیدمون برخاست و کلاودیوس در 44 کشور را به دو ایالت تینگیتانا و کایساریِنسیس تقسیم کرد.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["کلاودیوس بریتانیا را اشغال کرد", "f42ba7f7"], "d": ["در 43 میلادی چهار لژیون به فرماندهی آولوس پلائوتیوس در کرانهٔ کنت پیاده شدند؛ کامولودونوم (کولچستر) گرفته شد و کلاودیوس اندکی در شهر ماند. جنوب بریتانیا ایالت تازهٔ روم شد.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["روم تراکیه را ایالت کرد: سلسلهٔ اودریس پایان یافت", "af2ba1b2"], "d": ["پس از کشته‌شدن رویمتالکس سوم، پادشاه تراکیه، به دست همسرش و آشوب پس از آن، کلاودیوس در 46 تراکیه را به ایالت رومی بدل کرد. این از واپسین گام‌های تکمیل نظام ایالتی روم در شرق بالکان است.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["تراژان داکیه را فتح کرد: سارمیزگتوسا سقوط کرد، دکبالوس درگذشت، ایالت داکیا بنیان یافت", "a9277172"], "d": ["در جنگ دوم داکیه (105-106) تراژان سارمیزگتوسا را گرفت؛ دکبالوس برای فرار از دستگیری خودکشی کرد. داکیه ایالت روم شد و معادن طلای آن به اقتصاد روم پیوست. مراحل پیشین جنگ (101-105) در گاه‌شمار در مواد جداگانه‌اند..", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["هادریانوس در بریتانیا ساخت دیوار مرز شمالی را آغاز کرد", "f4a886ec"], "d": ["هادریانوس پس از دیدار از بریتانیا در 122 میلادی دیواری مرزی در خط تاین-سولوی ساخت. دیوار نمادی از سیاست مرزی دفاعی روم است؛ پیشروی با دیوار آنتونینوس (142) آزموده شد اما پایدار نماند.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["سپتیمیوس سوروس بین‌النهرین را ایالت کرد؛ تیسفون غارت شد", "df466924"], "d": ["سوروس در جنگ اشکانی (195-198) نصیبین را گرفت و تیسفون را غارت کرد و بین‌النهرین بالا را به‌عنوان ایالت رومی سامان داد. ایالت دورترین پیشروی شرقی روم را به سدهٔ 3 برد.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: تابعیت رومی به همهٔ ساکنان آزاد امپراتوری داده شد", "dd4e4024"], "d": ["کاراکالا در 212 میلادی ساکنان آزاد ایالت‌ها را شهروند رومی کرد؛ تمایز شهروند و بیگانه در امپراتوری برداشته شد. این مقرره پایهٔ مالیاتی را نیز گسترد.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["پستومووس در گل امپراتوری جدایی‌طلب گل را بنیان نهاد", "4dcda41d"], "d": ["با اسارت والریانوس نزد اشکانی/ایران (260)، پستومووس با سپاه‌های راین در گل امپراتوری اعلام کرد؛ گل، بریتانیا و بخش بزرگ هیسپانیا تا 274 از روم جدا شد. گالیئنوس نتوانست این جدایی را بردارد.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["آورلیانوس داکیا را تخلیه کرد: شمال دانوب رها شد", "db2ca714"], "d": ["به سبب فشار گوت‌ها، آورلیانوس ایالت داکیا را تخلیه کرد و لژیون‌ها و مردم غیرنظامی را به جنوب دانوب (داکیا ریپنسیس) کشاند. روم پس از 165 سال نخستین سرزمین بزرگ خود را در شمال دانوب رها کرد.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["آورلیانوس امپراتوری پالمیرا را شکست داد: سرزمین‌های شرقی زنوبیا به روم بازگشت", "0a358790"], "d": ["آورلیانوس در 272 در انطاکیه و حمص (امسا) سپاه زنوبیا را شکست داد و پالمیرا را محاصره کرد؛ زنوبیا اسیر شد. سوریه، مصر و جنوب آناتولی دوباره به روم پیوست.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["آورلیانوس امپراتوری گل را شکست داد: روم دوباره یکی شد", "c1a6a642"], "d": ["آورلیانوس در 274 در کاتالائونوم تتریکوس را شکست داد؛ گل، بریتانیا و هیسپانیا به روم بازگشت. امپراتوری پس از 14 سال جدایی یکپارچه شد و آورلیانوس عنوان «Restitutor Orbis» («بازسازندهٔ جهان») را گرفت.", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["یولیانوس فرانک‌های سالی را در توکساندریا به‌عنوان foederati رومی اسکان داد", "0fb618fe"], "d": ["سزار یولیانوس در 358 فرانک‌های سالی را شکست داد و به آنان اجازه داد در خاک روم، در توکساندریا (مرز کنونی هلند و بلژیک)، ساکن شوند. این آغاز استقرار زیر حمایت روم در ناحیه‌ای است که پادشاهی فرانک در آن زاده خواهد شد.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["هون‌ها از دن گذشتند و به آلان‌ها و استروگوت‌ها حمله کردند: آغاز مهاجرت بزرگ", "659eb875"], "d": ["به گفتهٔ آمیانوس، هون‌ها در 375 از دن گذشتند و آلان‌ها را شکست دادند، سپس پادشاهی هرمانریک، پادشاه استروگوت، را ویران کردند؛ ویزیگوت‌ها (ترووینگی) از این رو به دانوب رسیدند. عصر چیرگی هون‌ها در اروپا بدین‌سان آغاز شد.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["گوت‌های ترووینگی از دانوب گذشتند و در خاک روم ساکن شدند", "3e9de0e6"], "d": ["با فشار هون‌ها، گوت‌های ترووینگیِ فریتیگرن در 376 از والنس اجازه گرفتند از دانوب بگذرند و در خاک روم ساکن شوند؛ مشکلات رسانش و اداره به شورش بدل شد. نتیجه، شکست ادریانوپل (ادرنه) در 378 بود.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["وندال‌ها، آلان‌ها و سوئوها از راین گذشتند و به گل درآمدند", "2b3354ba"], "d": ["در تاریخ سنتی 31 دسامبر 406 (بر راین یخ‌زده) وندال‌ها، آلان‌ها و سوئوها به گل رومی درآمدند؛ دفاع راین فروریخت. گذر آنان به اسپانیا (409) ایالت‌های بنیادین روم باختری را برکند.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["وندال‌ها، آلان‌ها و سوئوها به اسپانیا گذشتند: هیسپانیا تقسیم شد", "b7036608"], "d": ["در پاییز 409 گروه‌های وندال، آلان و سوئو که از گل از پیرنه گذشته بودند، در 411 شبه‌جزیره را میان خود بخش کردند: هسدینگ‌ها و سوئوها گالایکیا، سیلینگ‌ها بایتیکا و آلان‌ها لوزیتانیا و کارتاژنسیس را گرفتند. ویزیگوت‌ها (416-418) با درهم‌کوبیدن سیلینگ‌ها و آلان‌ها گذر وندال‌ها به آفریقا را آماده کردند.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["روم ویزیگوت‌ها را در آکیتانیا سکوندا اسکان داد: پادشاهی ویزیگوتی به مرکزیت تولوز", "38a7699e"], "d": ["روم به فرماندهی کنستانتیوس، پس از آنکه ویزیگوت‌های والیا را در هیسپانیا بر ضد وندال-آلان‌ها به کار برد، در 418 آنان را به‌عنوان foederati در آکیتانیا سکوندا در دره گارون اسکان داد. پادشاهی ویزیگوتی به مرکزیت تولوز نخستین پادشاهی ژرمنی در خاک روم شمرده می‌شود.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["پیمان مارگوس: هون‌ها سالانه 700 لیبرا طلا از روم گرفتند", "833d8854"], "d": ["پس از مرگ روآ، پادشاه هون (433/4)، آتیلا و بلدا در مارگوس با روم شرقی پیمان بستند: باج سالانه از 350 به 700 لیبرا طلا رسید و پناهندگان هون بازگردانده شدند. هون‌ها حق تجارت در مرز دانوب به دست آوردند.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["پیمان هیپو: روم وندال‌ها را در بخشی از نومیدیا و موریتانیا به‌عنوان foederati شناخت", "f7dba59f"], "d": ["پس از گذر گایسریک، پادشاه وندال، به آفریقا در 429، در 435 پیمان هیپو را با روم بست؛ وندال‌ها بخشی از نومیدیا و موریتانیا را به‌عنوان foederati نگه داشتند. پیمان با گرفته‌شدن کارتاژ در 439 شکسته شد.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["آتیلا دژهای دانوب را گرفت: ویمیناکیوم و سینگیدونوم (بلگراد) به هون‌ها رسید", "0abb2c54"], "d": ["چون سپاه روم شرقی در لشکرکشی سیسیل و وندال بود، آتیلا در 441 از دانوب گذشت؛ مارگوس، ویمیناکیوم و سینگیدونوم گرفته شد. سیرمیوم نیز در این لشکرکشی‌ها سقوط کرد و هون‌ها به درون بالکان رسیدند.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["روم و وندال‌ها پیمان تازه بستند: آفریکا پروکنسولاریس، بیزاکنا و بخشی از نومیدیا به وندال‌ها ماند", "e5700ddc"], "d": ["گایسریک که کارتاژ را گرفته بود (439)، با پیمانی که در 442 با والنتینیانوس سوم بست، آفریکا پروکنسولاریس، بیزاکنا، آباریتانا و بخشی از نومیدیا را به‌طور حقوقی سرزمین وندال کرد؛ روم تنها موریتانیا و باختر نومیدیا را نگه داشت.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["صلح آناتولیوس: نواری گسترده در جنوب دانوب به هون‌ها واگذار شد", "ee8ad838"], "d": ["پس از شکست روم شرقی در اوتوس، آناتولیوس در 447 با آتیلا صلح کرد: روم نواری به پهنای پنج روز راه را در جنوب دانوب، از سینگیدونوم تا نوواه، به هون‌ها واگذاشت و باج سالانه به 2100 لیبرا طلا رسید.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["نبرد کاتالائونوم (شالون): آئتیوس و تئودوریک یکم آتیلا را از گل راندند", "80f10e32"], "d": ["در 451 آتیلا به گل درآمد و اورلئان را محاصره کرد؛ ائتلاف آئتیوس و تئودوریک یکم، پادشاه ویزیگوت، او را در دشت کاتالائونوم بازگرداند (تئودوریک در این نبرد درگذشت). پیشروی هون‌ها در اروپای باختری بدین‌سان متوقف شد.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["آتیلا به ایتالیا درآمد؛ آکوئیلیا ویران شد", "1349c67a"], "d": ["در 452 آتیلا از آن‌سوی آلپ به ایتالیای شمالی درآمد، آکوئیلیا را با خاک یکسان کرد و دشت پو را غارت نمود؛ با بیماری و ضدحملهٔ روم شرقی عقب نشست. مردم گریختهٔ آکوئیلیا در تالاب‌ها هستهٔ ونیز را شکل دادند.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["آتیلا درگذشت؛ دولت هون از هم پاشید", "47009384"], "d": ["آتیلا در 453 در شب عروسی درگذشت؛ تقسیم میان پسرانش و شورش رعایای ژرمن یک سال بعد در ندائو (454) به برتری هون‌ها پایان داد. هون‌ها به اروپای شرقی عقب نشستند.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["پادشاهی ویزیگوتی اوریک عملاً از روم جدا شد: اورنی به ویزیگوت‌ها واگذار شد", "4bbe7b0c"], "d": ["اوریک از 466 با فتح در هیسپانیا و گل پادشاهی خود را گسترد؛ در 475 یولیوس نپوس با واگذاری اورنی فرمانروایی مستقل او را عملاً شناخت. پادشاهی ویزیگوتی از لوار تا مدیترانه سرزمین‌های روم باختری را زیر نظارت داشت.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["یولیوس نپوس در دالماسیا کشته شد: واپسین امپراتور مشروع روم باختری", "3b965f33"], "d": ["نپوس که پس از سرنگونی رومولوس به دالماسیا عقب نشسته بود، در 480 کشته شد؛ پس از مرگ او کسی برای ادعای تخت روم باختری نماند و اودوآکر قدرت واقعی خود را در ایتالیا با نام زنون ادامه داد.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["تئودوریک استروگوت‌ها را به ایتالیا برد: اودوآکر در ایزونتسو و ورونا شکست خورد", "6a998bf8"], "d": ["تئودوریک با تأیید زنون، امپراتور روم شرقی، در 489 به ایتالیا درآمد و اودوآکر را در ایزونتسو و ورونا شکست داد؛ اودوآکر در راونا پناه گرفت. محاصرهٔ سه‌ساله در 493 با تسلیم راونا پایان یافت.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["تئودوریک اودوآکر را در راونا کشت؛ ایتالیا از آنِ پادشاهی استروگوت شد", "5a2db0ed"], "d": ["پایان پادشاهی ایتالیایی اودوآکر: سراسر ایتالیا (از جمله شهرهایی چون جنوا، برندیزی، آریچا) به پادشاهی گوت شرقی (استروگوت) رسید. پس از محاصرهٔ سه‌ساله راونا، در مارس 493 اودوآکر و تئودوریک بر سر فرمانروایی مشترک سازش کردند؛ سپس تئودوریک اودوآکر را در ضیافتی کشت. ایتالیا با تأیید روم شرقی پادشاهی استروگوت شد و پایتختش راونا است.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["صلح ساموس: سفیران کوش از آگوستوس صلح گرفتند؛ روم خراجی را که از کوش گرفته بود برداشت، مرز در نوبهٔ سفلی (Hiera Sykaminos) کشیده شد", "c3c4c20d"], "d": ["سفیران کندکه، با راهنمایی پترونیوس، به ساموس، جایی که آگوستوس را یافتند، رفتند؛ آگوستوس همهٔ خواسته‌های آنان را پذیرفت و خراج‌هایی را هم که پترونیوس بر کوش نهاده بود برداشت. در پی این صلح مرز روم-کوش در جنوب فیله بر خط Hiera Sykaminos (Maharraqa) قرار گرفت و نزدیک به سیصد سال درگیری جدی رخ نداد.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["پترونیوس به کوش لشکر کشید و Pselkis، Premnis و نپاتا را گرفت؛ در ابریم پادگان نهاد", "4884ed51"], "d": ["پترونیوس، پرفکت، با نزدیک به ده هزار پیاده و هشت صد سوار سی هزار سرباز کوش را شکست داد، Pselkis را گرفت، قلعهٔ Premnis (Qasr İbrim) را در نخستین یورش گرفت و نپاتا، که کاخ کندکه در آن بود، را با خاک یکسان کرد. چون پیشروی بیشتر را دشوار یافت، هنگام بازگشت در Premnis با ذخیرهٔ دوساله پادگان چهارصدنفره‌ای گذاشت. چون کندکه کوشید Premnis را بازپس گیرد، پترونیوس رسید و قلعه را نگه داشت.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["کوش به رهبری کندکه الفانتین، Syene و فیله را گرفت؛ مجسمه‌های آگوستوس را فروریخت", "aa665fad"], "d": ["هنگامی که برای لشکرکشی آلیوس گالوس به عربستان بخشی از یگان‌های رومی در مصر برداشته شد، کوشی‌ها وارد Thebais شدند؛ پادگان سه‌کوهورتی Syene را شکست دادند و Syene، الفانتین و فیله را گرفتند، مردم را اسیر کردند و مجسمه‌های سزار را فروانداختند. استرابون می‌نویسد ملکه‌ای که در آن زمان بر کوش فرمان می‌راند زنی یک‌چشم با عنوان «کندکه» بود.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["کورنلیوس گالوس نخستین پرفکت مصر شد؛ شورش‌های Heroonpolis و طیبه را سرکوب کرد، مرز با کوش تضمین شد", "9f688855"], "d": ["اکتاویانوس مصر را ایالتی ویژه و مشمول مالیات کرد و اداره‌اش را نه به سناتور، بل به پرفکتی از طبقهٔ سواران سپرد؛ نخستین پرفکت کورنلیوس گالوس شد. استرابون می‌نویسد گالوس شهرکی را که در Heroonpolis شورید با شمار اندکی سرباز گرفت و شورش بر سر مالیات را در طیبه در مدتی کوتاه سرکوب کرد. لوح گالوس در فیله آگاه می‌کند که سفیران فرمانروای کوش در آنجا پذیرفته شدند و منطقهٔ Triakontaschoinos زیر حمایت درآمد.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["اکتاویانوس وارد اسکندریه شد؛ دولت بطلمیوسی پایان یافت، مصر به روم رسید", "553804ca"], "d": ["پس از آنکه ناوگان و سواره‌نظام آنتونیوس به اکتاویانوس پیوست، اکتاویانوس وارد اسکندریه شد؛ آنتونیوس خودکشی کرد، کلئوپاترا نیز اندکی بعد مرد. اکتاویانوس مردم اسکندریه را بخشید، با گفتن «می‌خواستم پادشاهی ببینم، مردگانی را نه» از آرامگاه‌های بطلمیوسیان دیدن نکرد و مصر را به‌عنوان سرزمینی مشمول مالیات به کورنلیوس گالوس سپرد. با این تاریخ پادشاهی سیصدسالهٔ بطلمیوسی پایان یافت.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["نبرد دریایی آکتیوم: اکتاویانوس آنتونیوس و کلئوپاترا را شکست داد", "7e46cc73"], "d": ["ناوگان اکتاویانوس در آکتیوم ناوگان آنتونیوس و کلئوپاترا را شکست داد؛ آن دو به مصر عقب نشستند. دیو، نویسنده‌ای که از دادن تاریخ پرهیز می‌کند، این روز را به‌ویژه یاد می‌کند، زیرا اکتاویانوس از آن پس امپراتوری را به‌تنهایی در دست داشت و سال‌های قدرت او از این روز شمرده شد.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["بخشش‌های اسکندریه: آنتونیوس کلئوپاترا و فرزندانش را فرمانروای پادشاهی‌های شرق اعلام کرد", "24e24981"], "d": ["آنتونیوس که در برابر انبوه گردآمده در Gymnasion تخت‌های زرین برپا کرده بود، کلئوپاترا را ملکهٔ مصر، قبرس، لیبی و کوئله‌سوریه، Kaisarion را فرمانروای همتای او و فرزندانش را پادشاه ارمنستان، ماد، پارت و فینیقیه-سوریه-کیلیکیه اعلام کرد. در روم این مراسم به تبلیغات علیه آنتونیوس بدل شد و جنگ داخلی را شتاب داد.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["آنتونیوس قبرس، فینیقیه، کوئله‌سوریه و بخشی از کیلیکیه را به کلئوپاترا بخشید", "cf19a357"], "d": ["بر پایهٔ پلوتارک، آنتونیوس هنگامی که به سوریه آمد فینیقیه، کوئله‌سوریه، قبرس، بیشتر کیلیکیه، سوی بلسان‌خیز یهودیه و بخش دریاییِ نبطیه را به کلئوپاترا داد. بدین‌سان دولت بطلمیوسی، برای نخستین بار از زمان بطلمیوس سوم، (با وجود خشم روم) بر گسترهٔ وسیعی از شرق مدیترانه نظارت یافت.", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["جنگ اسکندریه: سزار بطلمیوس سیزدهم را شکست داد و مصر را به کلئوپاترا واگذاشت", "96c9b516"], "d": ["چون سزار به اسکندریه آمد و خواست میان کلئوپاترا و بطلمیوس سیزدهم داوری کند، نیروهای کاخ او را محاصره کردند؛ در جنگ خیابانی که سراسر زمستان ادامه یافت به سزار کمک رسید و در نبرد نیل بطلمیوس سیزدهم غرق شد. سزار مصر را به کلئوپاترا و برادر کوچکش بطلمیوس چهاردهم داد؛ لژیون‌های رومی در اسکندریه ماندند.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["گابینیوس بطلمیوس دوازدهم را با سپاه روم دوباره بر تخت مصر نشاند؛ پادگان رومی در اسکندریه ماند", "41d8f47d"], "d": ["بطلمیوس دوازدهم (آولتس) که بیرون رانده شده بود، با رشوهٔ بزرگ به گابینیوس، والی سوریه، ورود به مصر را خرید؛ گابینیوس لشکرکشی پارتی را رها کرد و از Pelusium وارد مصر شد و آولتس را به تخت بازگرداند. این لحظه‌ای است که استقلال مصر عملاً به تضمین روم بسته شد. گابینیوس بعدها در روم محاکمه شد.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["روم قبرس را از بطلمیوس گرفت و ضمیمه کرد؛ کاتو به جزیره فرستاده شد", "678b2115"], "d": ["پادشاه قبرس، که برادر بطلمیوس دوازدهم بود، در برابر گرفتن جزیره به‌دست روم به پیشنهاد کلودیوس مقاومت نکرد؛ کاتو برای تحویل گرفتن جزیره فرستاده شد. دولت بطلمیوسی قبرس را از دست داد و واپسین پایگاه دریایی ساحلی را از کف داد. پلوتارک «فرستاده شدن» کاتو به قبرس را در زندگینامهٔ پومپه یاد می‌کند.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«روز الئوسیس»: فرستادهٔ روم پوپیلیوس لائناس آنتیوخوس چهارم را به عقب‌نشینی از مصر واداشت", "e6883e6a"], "d": ["بلافاصله پس از نبرد پیدنا (22 ژوئن 168 پیش از میلاد)، فرستادهٔ روم گایوس پوپیلیوس لائناس فرمان مجلس سنا را برای دست کشیدن از جنگ به آنتیوخوس، که اسکندریه را محاصره کرده بود، رساند؛ برای آنکه شاه پاسخش را بیندیشد، پیرامون او دایره‌ای کشید. آنتیوخوس عقب نشست. مصر استقلال خود را بدون از دست دادنش، زیر حمایت روم، ادامه داد.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["آنتیوخوس چهارم به مصر حمله برد؛ در جنگ ششم سوریه تا ممفیس و Naukratis پیش رفت", "b85e6712"], "d": ["آنتیوخوس چهارم، در برابر تدارک بطلمیوس ششم برای بازپس‌گیری کوئله‌سوریه، وارد مصر شد و از Pelusium به نیل فرود آمد؛ از حق خود بر کوئله‌سوریه دفاع کرد و در Naukratis با مردم نیکو رفتار کرد. جنگ بی‌آنکه مصر را ویران کند، اما دولت را تضعیف کرد، با میانجی‌گری روم یک سال بعد پایان یافت.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["شورش طیبه سرکوب شد: Komanos مصر علیا را دوباره زیر سلطهٔ بطلمیوسیان آورد", "4c0e4f10"], "d": ["پس از حدود بیست سال حکومت جدایی‌طلب، Komanos، فرمانده بطلمیوسی، طیبه را از فرعون بومی Ankhwennefer بازپس گرفت و مصر علیا دوباره به دولت بطلمیوسی پیوست.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["سینود ممفیس فرمان رزتا را صادر کرد: بطلمیوس پنجم بخشودگی مالیاتی معابد را پذیرفت", "5643b91f"], "d": ["سینودی که کاهنان مصری در ممفیس گرد آوردند، بر تخت نشستن بطلمیوس پنجم را تأیید کرد و بخشودگی‌های مالیاتی شاه برای معابد، سرکوب شورش‌ها و بنیان آیین پرستش شاه را اعلام نمود. فرمان به یونانی، دموتیک و هیروگلیف نوشته شد؛ سنگ رزتا همین متن سه‌زبانه است. متن همچنین به سرکوب شورشیان دلتا (Lykopolis) اشاره دارد.", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["نبرد Panion: آنتیوخوس سوم Skopas را شکست داد؛ کوئله‌سوریه از بطلمیوسیان به سلوکیان رسید", "97e30e58"], "d": ["در جنگ پنجم سوریه آنتیوخوس سوم Skopas آیتولیایی، فرمانده بطلمیوسی، را در Paneion درهم شکست؛ بنا بر یوسفوس، آنتیوخوس شهرهای کوئله‌سوریه را که Skopas گرفته بود بازپس گرفت و سامره را نیز گرفت، یهودیان با رضایت خود به آنتیوخوس پیوستند. کوئله‌سوریه (سوریه-فلسطین) از آن پس به اداره‌ٔ سلوکیان درآمد؛ دولت بطلمیوسی از منطقه عقب نشست.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["فرعون‌های بومی جدایی‌طلب در طیبه پدید آمدند: مصر علیا از سلطهٔ بطلمیوسیان جدا شد", "d10abb36"], "d": ["مصریان بومی که پس از پیروزی Raphia مسلح شده بودند، به تعبیر پولیبیوس، از پیروزی باد کردند و دیگر فرمان شاه را نشنیدند؛ در دلتا و مصر علیا شورش‌ها برخاست. در طیبه فرعون‌های بومی (Horwennefer و سپس Ankhwennefer) حدود بیست سال مصر علیا را علیه بطلمیوسیان در دست داشتند.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["نبرد Raphia: بطلمیوس چهارم آنتیوخوس سوم را شکست داد؛ کوئله‌سوریه نزد بطلمیوس ماند", "34362178"], "d": ["در Raphia سپاه بطلمیوس چهارم، با ساختاری که شمار بزرگی فالانکس (هوپلیت) مصری بومی را در بر داشت، سپاه آنتیوخوس سوم را شکست داد؛ آنتیوخوس از کوئله‌سوریه عقب نشست و منطقه تا 200 در دست بطلمیوسیان ماند. مسلح کردن مصریان بومی بعدها شورش‌های جدایی‌طلب مصر علیا را تغذیه کرد.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["آنتیوخوس سوم Seleukeia Pieria را از بطلمیوسیان بازپس گرفت", "39ee3a52"], "d": ["آنتیوخوس سوم Seleukeia Pieria را، که در دست بطلمیوسیان بود، محاصره کرد و با رشوه دادن به افسران گرفت؛ پولیبیوس می‌نویسد که شهر از زمان بطلمیوس سوم به‌دست پادگانی متعلق به شاهان مصر نگه داشته می‌شد. با این پیروزی سلوکیان به بندر انطاکیه دست یافتند و برای لشکرکشی به کوئله‌سوریه آماده شدند (جنگ چهارم سوریه).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["بطلمیوس سوم در جنگ Laodike سوریه و بین‌النهرین را اشغال کرد؛ Seleukeia Pieria به دست بطلمیوسیان افتاد", "04472253"], "d": ["بطلمیوس دوم در 28 ژانویه 246 پیش از میلاد درگذشت؛ بطلمیوس سوم برای حمایت از خواهرش Berenike به دولت سلوکی حمله برد. در Seleukeia Pieria و انطاکیه از او استقبال شد؛ تاریخ‌نگاری بابلی (BCHP 11) گزارش می‌دهد که سپاهش از دسامبر 246 پیش از میلاد به بابل رسیده بود. کتیبهٔ Adulis ادعا می‌کند غرب فرات، کیلیکیه، پامفیلیا و تراکیه را فتح کرده است. Seleukeia Pieria سال‌های بسیار در دست بطلمیوسیان ماند.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["پس از ایپسوس بطلمیوس کوئله‌سوریه را اشغال کرد؛ سلوکوس اعتراض کرد (ریشهٔ جنگ‌های سوریه)", "a109388f"], "d": ["پس از نبرد ایپسوس (301 پیش از میلاد) سلوکوس، لیسیماکوس و کاساندروس توافق کردند و همهٔ سوریه را به سلوکوس دادند؛ اما بطلمیوس کوئله‌سوریه را با سپاه اشغال کرد و نگه داشت. این اختلاف در دو سدهٔ بعد شش جنگ سوریه را پدید آورد. آنتیوخوس سوم بعدها از این ادعا، چنان‌که پولیبیوس نقل می‌کند، دفاع کرد.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["بطلمیوس خود را پادشاه اعلام کرد؛ خاندان بطلمیوسی رسماً بنیان نهاده شد", "008c723a"], "d": ["پس از آنکه آنتیگونوس و دمتریوس عنوان پادشاهی گرفتند (306 پیش از میلاد)، بطلمیوس نیز عنوان پادشاهی را گرفت؛ مصر به‌عنوان پادشاهی هلنیستی مستقل یاد شد. عرضهٔ خاندان به‌عنوان فرعون مصر، سازش با طبقهٔ کاهنان بومی را نیز شتاب داد.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["نبرد غزه: بطلمیوس و سلوکوس دمتریوس را شکست دادند (سوریه مدتی کوتاه نزد بطلمیوس)", "ea0d264f"], "d": ["دمتریوس، پسر آنتیگونوس، در برابر غزه از سپاه متحد بطلمیوس و سلوکوس شکست خورد؛ بطلمیوس وارد کوئله‌سوریه شد. با ضدحملهٔ آنتیگونوس منطقه اندکی بعد دوباره از دست رفت، صلح (311 پیش از میلاد) این را تثبیت کرد.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["لشکرکشی پردیکاس به مصر در گذر از نیل ناکام ماند؛ پردیکاس به‌دست سپاه خود کشته شد", "c1792117"], "d": ["در جنگ دیادوخی‌ها، پردیکاس، نایب اسکندر، علیه بطلمیوس، که کاروان تشییع اسکندر را ربوده بود، وارد مصر شد، اما نتوانست از نیل بگذرد، شمار بسیاری از مردانش را از دست داد و به‌دست افسرانش کشته شد. بطلمیوس مصر را نگه داشت.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["بطلمیوس Kirene (Kyrenaika) را به مصر افزود", "65316c50"], "d": ["بطلمیوس با دخالت در کشمکش درونی Kirene، با فرماندهی Ophellas، منطقهٔ Kyrenaika در لیبی را به مصر پیوست. بدین‌سان مصر بطلمیوسی به سوی غرب نیز گسترش یافت؛ Kyrenaika در سده‌های بعد در دست شاخه‌ای از خاندان بطلمیوسی ماند.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["اسکندر در واحهٔ سیوه از کاهن آمون پرسید", "c437ced0"], "d": ["اسکندر از ساحل به صحرا گذشت و به واحهٔ سیوه، که معبد آمون در آن است، رفت و از غیب‌گو پرسید؛ آریان می‌نویسد پاسخی را که او را خشنود کند گرفت. این دیدار مشروعیت اسکندر در مصر و روایت‌های بعدی دربارهٔ پسر خدا شمرده شدن او را تغذیه کرد.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["اسکندر وارد مصر شد؛ مازاکس، ساتراپ پارسی، تسلیم شد، مصر به اداره‌ٔ مقدونی درآمد", "c4a5f014"], "d": ["اسکندر که از غزه راه افتاده بود روز هفتم به Pelusium رسید و ناوگانش نیز به آنجا رسیده بود. مازاکس، ساتراپی که پس از ایسوس پشتیبانی پارسی نداشت، مقاومت نکرد و اسکندر را در شهرها دوستانه پذیرفت. اسکندر در Pelusium پادگان نهاد و به ممفیس پیش رفت؛ اداره‌ٔ امور را به دو والی بومی (Doloaspis، Petisis) سپرد و در ممفیس و Pelusium فرماندهان مقدونی گماشت. مصر از سلطهٔ پارسی بیرون آمد و به امپراتوری اسکندر پیوست.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["اردشیر سوم مصر را دوباره فتح کرد؛ نختانبو دوم به نوبه گریخت", "55d78a8d"], "d": ["در لشکرکشی اردشیر سوم به مصر پس از گرفتن صیدا، دفاع Pelusium فروپاشید؛ نختانبو دوم بی‌آنکه منتظر محاصره در ممفیس بماند به مصر علیا و نوبه گریخت. مصر برای بار دوم ساتراپی پارسی شد؛ سرنوشت واپسین فرعون بومی معلوم نیست.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Takhos به لشکرکشی سوریه رفت؛ نختانبو دوم با کودتا تخت را گرفت، آگسیلائوس صف عوض کرد", "4e1e9804"], "d": ["Takhos برای حمله به سوریهٔ پارسی سربازان مزدور یونانی (آگسیلائوس، شاه اسپارت، و Khabrias آتنی) گرد آورد؛ هنگامی که در لشکرکشی بود، برادرزاده‌اش نختانبو دوم خود را شاه اعلام کرد. آگسیلائوس در کنار نختانبو قرار گرفت؛ پلوتارک می‌نویسد که جنگیدن آگسیلائوس در پیری برای یک «شورشی بربر» در برابر مزد، در یونان نکوهش شد.", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["نختانبو یکم تهاجم پارسی (فرنابازوس-ایفیکراتس) را دفع کرد", "0a8bc67d"], "d": ["نختانبو یکم، بنیان‌گذار سلسلهٔ XXX، فرود سپاه پارسی به فرماندهی Farnabazos و ایفیکراتس آتنی را در دلتا با سیلاب نیل و اختلاف میان فرماندهان بازگرداند. این موفقیت استقلال مصر را 30 سال دیگر طولانی کرد.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["شورش ایناروس: قیام مصری با پشتیبانی آتن پارسیان را در ممفیس به تنگنا انداخت، در 454 در Prosopitis فروپاشید", "0cd93c33"], "d": ["ایناروس لیبیایی علیه اردشیر تقریباً سراسر مصر را به شورش واداشت و از آتنی‌ها یاری خواست؛ ناوگان آتن وارد نیل شد و دو سوم ممفیس را گرفت و «دژ سفید» باقی‌مانده را محاصره کرد. فرمانده پارسی Megabyzos آتنی‌ها را در جزیرهٔ Prosopitis یک سال و شش ماه محاصره کرد (با خشکاندن کانال) و نابود نمود؛ ایناروس دستگیر و بر صلیب کشیده شد. اما Amyrtaios در باتلاق‌های دلتا گرفته نشد.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["مصر علیه سلطهٔ پارسی شورید؛ خشایارشا یکم شورش را سرکوب کرد و مصر را سخت‌تر اداره کرد", "9d3d7462"], "d": ["شورش مصر که پیش از مرگ داریوش یکم آغاز شده بود، در نخستین سال‌های خشایارشا یکم سرکوب شد؛ خشایارشا برادرش هخامنش را ساتراپ گماشت و مصر را سخت‌تر از دورهٔ داریوش اداره کرد.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["لشکرکشی کمبوجیه به کوش به سبب تشنگی و نبود آذوقه ناکام ماند؛ مرز جنوبی مصر در الفانتین ماند", "4ebbad8c"], "d": ["کمبوجیه پس از مصر علیه «حبشیان درازعمر» (کوش) لشکرکشی را برنامه‌ریزی کرد؛ بنا بر هرودوت، شاه کوش کمانی برای سفیران پارسی فرستاد و گفت هنگامی که «به‌آسانی بتوانند کمان را بکشند» حمله کنند. سپاه در صحرا بی‌آذوقه ماند و بازگشت. استرابون نیز جایی را که سپاه کمبوجیه در طوفان صحرا هلاک شد یاد می‌کند. کوش مستقل ماند؛ مرز جنوبی پارسیان در الفانتین ایستاد.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["آماسیس آپریس را شکست داد و بر تخت مصر نشست؛ بازرگانان یونانی در Naukratis اسکان یافتند", "75a24b0b"], "d": ["آپریس که با سربازان مزدور یونانی از لشکرکشی لیبی بازمی‌گشت، در Momemphis از آماسیس، که در رأس یگان‌های بومی سپاه قرار گرفته بود، شکست خورد؛ آماسیس از سائیس بر مصر فرمان راند و Naukratis را تنها بندر بازرگانی یونانیان قرار داد. در پایان فرمانروایی او (526 پیش از میلاد) تهدید پارسی بزرگ شد.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["پسامتیک دوم به نوبه لشکر کشید: فشار کوش بر مرز مصر شکسته شد", "8f0aaf9d"], "d": ["لشکرکشی نوبهٔ پسامتیک دوم در هرودوت «لشکرکشی به حبشه» یاد می‌شود؛ سپاه مصر و سربازان مزدور یونانی/کاری نوشته‌هایی به یونانی در Abu Simbel بر جا گذاشتند. لوح سال 3 در طیبه (Karnak) از شکست سنگین پادشاهی کوش خبر می‌دهد و لوح پیروزی Kalabsha آن را یاد می‌کند؛ گفته می‌شود لشکرکشی تا آبشار سوم یا چهارم پیش رفت. بنا بر منابع، مرکز سیاسی کوش در دورهٔ بعد (Aspelta، حدود 591 پیش از میلاد) به جنوب، به Meroe، منتقل شد.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["نبوکدنصر به مرز مصر حمله برد؛ در نبرد آشکار دو طرف تلفات سنگین دادند، بابل عقب نشست", "45655313"], "d": ["نبوکدنصر، شاه بابل، در سال 4 خود به مصر لشکر کشید؛ شاه مصر سپاهش را گرد آورد و روبه‌رو شد، در نبرد میدانی هر دو طرف یکدیگر را سخت فرسودند. نبوکدنصر به بابل بازگشت و برای تجهیز دوبارهٔ سپاه عقب نشست. مصر مرز خود را پاسداری کرد، اما سوریه-فلسطین به بابل رسیده بود.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["نبرد کارکمیش: نبوکدنصر سپاه مصر را شکست داد؛ مصر سوریه را از دست داد", "ba486ac1"], "d": ["نبوکدنصر، ولیعهد، با سپاه بابل علیه سپاه مصر که در کارکمیش بود از فرات گذشت و آن را درهم شکست، گریزندگان را در منطقهٔ Hamat نابود کرد و سراسر منطقهٔ Hamat را گرفت. مصر از سوریه عقب نشست و پشت مرز سینا بازگشت؛ بابل صاحب سوریه-فلسطین شد.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["نکو دوم وارد سوریه-فلسطین شد؛ در مجدو یوشیا را شکست داد و به سوی فرات پیش رفت", "f887d6fd"], "d": ["نکو دوم که می‌خواست ایالت‌های غربی آشور فروپاشیده را بگیرد، به سوریه لشکر کشید؛ یوشیا، شاه یهودا، را که سر راهش بود در مجدو کشت. هرودوت می‌گوید «نکو در Magdolos سوری‌ها را شکست داد و شهر بزرگ سوریه Kadytis را گرفت». بدین‌سان مصر مدتی کوتاه سوریه-فلسطین را تا فرات زیر نظارت گرفت.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["پسامتیک یکم با فرزندخواندگی دخترش نیتوکریس نزد «همسر خدا»ی طیبه، مصر علیا را زیر نظارت گرفت", "bf768452"], "d": ["پسامتیک یکم در سال 9 خود ترتیبی داد که دخترش نیتوکریس به‌عنوان فرزندخواندهٔ Shepenwepet، دختر Taharka، شاه کوش (همسر خدای طیبه)، به طیبه فرستاده شود؛ Shepenwepet املاک خود را به نیتوکریس واگذاشت و دارایی معبد طیبه بدین‌سان به دست سائیسی‌ها افتاد. لوح فرزندخواندگی نشان می‌دهد که پسامتیک در سال 9 خود نظارت کامل بر طیبه را به دست آورد و Tantamani تا آن تاریخ مصر علیا را از دست داده بود.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["سپاه آشور طیبه را غارت کرد؛ Tantamani به جنوب عقب نشست، سلطهٔ کوش در مصر فروپاشید", "777fc1a5"], "d": ["سپاهیان آشوربانیپال Tantamani را از ممفیس راندند و تا طیبه پیش رفتند و شهر را غارت کردند؛ گنجینه‌های معبد طیبه به نینوا برده شد. Tantamani به نوبه عقب نشست؛ سلطهٔ کوش در مصر علیا گسسته شد. این غارت در عهد عتیق با نام «No-Amon» (ناحوم 3:8) یاد شده است.", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["سلسلهٔ XXVI آغاز شد: پسامتیک یکم در سائیس به‌عنوان دست‌نشانده آشور در مصر سفلی به قدرت رسید", "f270eac3"], "d": ["پسامتیک یکم، فرمانروای سائیس، از میان شاهزادگان دلتا که آشور در مصر نهاده بود، سلسلهٔ XXVI (سائیسی) را آغاز کرد. بنا بر هرودوت، پسامتیک از میان «دوازده شاه» جدا شد و به باتلاق رانده شد، دلتا را دوباره به دست آورد. پس از آشور و کوش، مصر دوباره به دست خاندانی بومی افتاد؛ به دست آوردن طیبه و مصر علیا چند سال طول کشید.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Tantamani از کوش فرود آمد و طیبه و ممفیس را دوباره گرفت؛ دست‌نشاندگان آشور را محاصره کرد", "f84c87a4"], "d": ["Tantamani، جانشین Taharka، بنا بر لوح رؤیا، پس از آنکه در نپاتا تاج گذاشت از رود به شمال فرود آمد: در الفانتین برای Khnum پیشکش کرد، به طیبه و ممفیس آمد و در آنجا مخالفانش را قتل‌عام کرد و شهر را گرفت؛ بیگ‌های دلتا نهان شدند یا سر فرود آوردند. این کوشش نظم دلتا را برای پسامتیک یکم و آشور تهدید کرد و لشکرکشی تنبیهی آشور را به دنبال آورد.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["آسارحدون وارد مصر شد و ممفیس را گرفت؛ Taharka به جنوب عقب نشست", "a138bcac"], "d": ["آسارحدون، شاه آشور، در سال 10 خود به مصر لشکر کشید؛ سپاه آشور در مصر قتل‌عام بزرگی کرد و Taharka، شاه کوش، به جنوب گریخت. شاهزاده‌نشین‌های دلتا دست‌نشانده آشور شدند، ممفیس و مصر شمالی موقتاً به دست آشور افتاد. آسارحدون دو سال بعد هنگام رفتن به لشکرکشی تازه در راه درگذشت.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["سنحاریب در لشکرکشی یهودا در Eltekeh با سپاه کوش-مصر روبه‌رو شد", "7f423351"], "d": ["در لشکرکشی سنحاریب، شاه آشور، به کنعان، سپاه مصر کوشی به یاری یهودا آمد و در Eltekeh با آشور نبرد کرد؛ سپاه آشور بی‌آنکه اورشلیم را بگیرد عقب نشست. یوسفوس روایت می‌کند که سنحاریب با رسیدن خبر آمدن Tirhaka، شاه کوش، با سپاهی بزرگ، از Pelusium رفت. این نخستین درگیری مستقیم کوش-مصر با آشور است.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Piye (Pankhi) به مصر فرود آمد: ائتلاف Tefnakht را شکست داد و فرمانروایان ممفیس و دلتا را مطیع ساخت", "bb36f7c4"], "d": ["Tefnakht از سائیس ائتلافی از دلتا تا ممفیس و مصر میانه ساخته و Herakleopolis را محاصره کرده بود. Piye که از نپاتا لشکر کشید، در سال 21 خود به شمال فرود آمد و با گرفتن شهرهای متحد (Hermopolis، ممفیس، Heliopolis) تسلیم شاهزادگان دلتا را پذیرفت؛ سپس به نپاتا بازگشت. بدین‌سان کوش سرور سراسر مصر شد (سلسلهٔ 25).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["Kashta، پادشاه کوش (نپاتا)، به مصر علیا پیش رفت؛ در الفانتین و طیبه نفوذ کرد", "b0f5be7f"], "d": ["پادشاهان کوش در نپاتا از پراکندگی مصر در دورهٔ میانی سوم سود جستند و به سوی شمال نیرو گرفتند. از بناها پیداست که Kashta تا الفانتین در مصر علیا نفوذ برقرار کرد؛ Amenirdis I (خواهر Piye) از خاندان کوش با عنوان «همسر خدا»ی آمون در طیبه مستقر شد و این مقام ابزار کوش بر طیبه شد. بدین‌سان زمینهٔ بنیان سلسلهٔ 25 فراهم آمد.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["شوشنق به کنعان لشکر کشید: اورشلیم و شهرهای اسرائیل-یهودا در فهرست Karnak درآمد", "1607ae3a"], "d": ["لشکرکشی شوشنق به کنعان با روایت تورات که می‌گوید در سال 5 شاه رحبعام از اورشلیم خراج گرفت (1 پادشاهان 14:25) هم‌خوان است؛ در دروازهٔ Bubastite در Karnak حدود 150 نام شهر ردیف شده است (تقریباً پنجاه-شصت از اسرائیل، صد از یهودا). یوسفوس نیز روایت می‌کند که Shishak اورشلیم را گرفت و خزانه را برد. این لشکرکشی طولانی‌ترین عملیات خارجی مصر در دورهٔ میانی سوم است.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["شوشنق یکم (از تبار Meshwesh/لیبی) سلسلهٔ XXII را بنیان نهاد؛ پایتخت Bubastis", "dae122c7"], "d": ["سرداران Meshwesh با ریشهٔ لیبیایی پس از پادشاهی نو در دلتا مستقر شده بودند؛ از میان آنان شوشنق یکم پس از سلسلهٔ XXI در Tanis مصر را دوباره یکی کرد. با گماردن پسرش به‌عنوان کاهن اعظم آمون، طیبه را نیز به خاندان بست. این دوره بهبودی کوتاهی پدید آورد که مصر را دوباره متوجه سیاست خارجی (لشکرکشی کنعان) کرد.", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["پادشاهی نو پایان یافت: در سال‌های پایانی رامسس یازدهم، در دلتا Smendes (Tanis) و در طیبه کاهن اعظم آمون عملاً مستقل شدند", "1828ceb0"], "d": ["در دورهٔ پایانی رامسس یازدهم، دولت مرکزی فروپاشید: در طیبه Herihor، کاهن اعظم آمون، بر مصر علیا نظارت می‌کند، در دلتا در Tanis Nesubenebded (Smendes) فرمان می‌راند؛ «داستان Wenamon» این تقسیم را (سفر Wenamon از Herihor تا Smendes) ثبت کرده است. Smendes سرانجام سلسلهٔ XXI را بنیان نهاد؛ نوبه نیز در این آشوب از نظارت مصر بیرون رفت.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["رامسس سوم اقوام دریایی را در خشکی (Djahy) و در دلتا در دریا شکست داد", "9068ae7b"], "d": ["در سال 8 رامسس سوم، Peleset، Tjeker، Denyen، Sherden و دیگر اقوام دریایی از خشکی و دریا به سوی مرز مصر آمدند؛ سپاه مصر نخست در مرز کنعان، سپس در نبرد دریایی در دهانه‌های دلتا آنان را بازداشت. نقش‌برجسته‌های Medinet Habu این را مستند می‌کند. مصر کنعان را دوباره نگه داشت، اما نفوذش در شرق مدیترانه پس از این دوره رو به فرسایش نهاد.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["مرنپتاح اتحاد لیبیایی‌ها و اقوام دریایی را در دلتای غربی شکست داد؛ نام «اسرائیل» در کنعان نخستین بار یاد شد", "e512311e"], "d": ["در سال 5 مرنپتاح، Meshwesh به رهبری Libu و «اقوام دریاآمده» (Ekwesh، Teresh، Lukka، Shardana، Shekelesh) دلتای غربی را اشغال کردند؛ سپاه مصر در نبردی شش‌ساعته در Perire آنان را پراکند. لوح پیروزی که همین رویدادها را روایت می‌کند، در کنعان Ashkelon، Gezer، Yenoam و «اسرائیل» را برمی‌شمارد؛ این کهن‌ترین یادکرد شناخته‌شدهٔ نام اسرائیل است.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["«پیمان ابدی» میان رامسس دوم و هاتوسیلی سوم: جنگ مصر-هیتی پایان یافت", "100f2a75"], "d": ["در سال 21 رامسس دوم، سفیران هیتی لوح پیمان را به Pi-Ramesse آوردند. پیمان جنگ حدود پانزده‌سالهٔ سوریه را پایان داد: دو طرف از طرح فتوحات بیشتر در سوریه چشم پوشیدند، اتحاد دفاعی بستند و تحویل گریزندگان و یاری متقابل را پذیرفتند. بر پایهٔ خلاصهٔ Breasted مرز در متن معین نشده؛ قلمرو نفوذ دو دولت در وضع موجود (کمربند قادش-Amurru در دست Hatti، کنعان در دست مصر) ماند.", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["رامسس دوم در قادش با هیتی‌های موواتالی دوم روبه‌رو شد؛ نتیجه مساوی ماند", "f5ad96db"], "d": ["رامسس دوم در برابر قادش در کرانهٔ Orontes با سپاه هیتی روبه‌رو شد؛ با کمین ارابه‌های جنگی هیتی، سپاه مصر در آستانهٔ درهم‌پاشیدن قرار گرفت، رامسس با نگهبانان خود ضدحمله کرد و بازگرداند. جنگ نتیجهٔ قطعی نداد؛ قادش و Amurru در نظارت هیتی ماند، مرز شمالی مصر نیز باز در کرانهٔ کنعان ماند.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["ستی یکم از کنعان جنوبی تا کرانهٔ فینیقیه لشکر کشید: مصر دوباره بر کنعان و کرانهٔ لبنان چیره شد، قادش را گرفت", "ad7bf1cd"], "d": ["بر پایهٔ نقش‌برجسته‌های Karnak، لشکرکشی سال 1 ستی یکم نخست بدویان Shasu، سپس از راه فلسطین به شمال رفت و Peher و Beth-Shean، Yenoam، صور و بیگ‌های لبنان را مطیع ساخت. در ردیف بالای نقش‌برجسته‌ها گرفتن قادش نیز نشان داده می‌شود. Breasted یادآور می‌شود که مرز شمالی پایدار در امتداد کرانهٔ فینیقیه از خط شرقی-غربی فراتر نرفت و قدرت هیتی شکسته نشد؛ این زمینهٔ پشت نبرد قادش رامسس دوم است.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["در عصر Amarna سلطهٔ مصر در سوریهٔ شمالی گسسته شد؛ Amurru و قادش به حوزهٔ نفوذ هیتی رفتند", "90d00c5a"], "d": ["نامه‌های Amarna (EA) نشان می‌دهند که دست‌نشاندگان سوریهٔ شمالی (Aziru از Amurru، فرمانروایان قادش) میان مصر، میتانی و Hatti بازی می‌کردند و مصر نمی‌توانست در منطقه دخالت کند. در پی لشکرکشی‌های شوپی‌لولیوما یکم، شاه هیتی، که میتانی را فرسود، Amurru و قادش به نفوذ هیتی درآمد؛ بدین‌سان مرز شمالی مصر در سوریه به کنعان عقب نشست.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["آمنهوتپ چهارم (آخناتون) پایتخت مصر را به Akhetaton (Amarna) منتقل کرد", "53cadac3"], "d": ["آخناتون پرستش آتون را دین دولت کرد و شهر تازه‌ای را که در مصر میانه بر صحرا گشوده شده بود (Akhetaton) پایتخت اعلام کرد؛ «لوح‌های مرزی» که مرزهای شهر را معین می‌کند به سال‌های 4-5 تاریخ‌گذاری می‌شود. نامه‌های Amarna نشان می‌دهند که در این دوره دست‌نشاندگان سوریه یاری می‌خواستند اما مصر پاسخ نمی‌داد.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["آمنهوتپ دوم در نوبه به نپاتا رسید و لوح مرز جنوبی برافراشت: جنوبی‌ترین نقطهٔ مصر", "2f61f824"], "d": ["آمنهوتپ دوم هنگام بازگشت از لشکرکشی سوریه (ژوئیه) به نوبه گذشت؛ بر پایهٔ نوشته‌های معبد الفانتین و Amada، از هفت شاهزاده‌ای که از سوریه آورده شده بود شش تن را بر باروهای طیبه و هفتمی را بر باروهای نپاتا آویخت. به گفتهٔ Breasted شاه در نپاتا یا درست بالاتر از آن لوحی برافراشت که مرز جنوبی را نشان می‌داد: سلطهٔ عملی مصر در نوبه بدین‌سان فراتر از Tombos (آبشار سوم) تا منطقهٔ آبشار چهارم امتداد یافت.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["توتموس سوم از فرات گذشت و به سرزمین‌های میتانی درآمد؛ در Naharin لوح مرزی برافراشت", "ebdbeebe"], "d": ["در سال 33 توتموس سوم از Retenu پیش رفت و از فرات گذشت، شهرک‌های Naharin را غارت کرد و در شرق رود لوح مرزی برافراشت؛ دومین لوح را در کنار لوح پدرش نهاد. این لشکرکشی دورترین نقطهٔ شمالی نفوذ مصر است و آستانهٔ درگیری مستقیم با میتانی را نشان می‌دهد.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["توتموس سوم در مجدو ائتلاف کنعانی به رهبری قادش را شکست داد؛ کنعان-سوریه زیر سلطهٔ مصر درآمد", "439dc6e8"], "d": ["در سال 23، ماه 1 Shemu، روز 21 توتموس سوم در برابر مجدو ائتلاف کنعانی را که فرمانروای قادش در رأس آن بود شکست داد؛ دشمن به شهر گریخت و مجدو پس از محاصره‌ای طولانی تسلیم شد. این لشکرکشی که در Karnak Annals ثبت شده، وابستگی کنعان و سوریهٔ جنوبی به مصر را پایدار ساخت و آغاز گسترش امپراتوری بود.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["توتموس یکم لشکرکشی آسیایی تا کرانهٔ فرات (Naharin) کرد", "50ce0679"], "d": ["بر پایهٔ کتیبه‌های Ahmose-Pennekhbet و Ahmose-Ebana، توتموس یکم پس از لشکرکشی نوبه لشکرکشی بزرگی به Naharin کرد؛ توتموس سوم بعدها در کنار لوح مرزی‌ای که پدرش در فرات برافراشته بود لوح خود را می‌افزاید. این نخستین دورهٔ ثبت‌شده‌ای است که نفوذ مصر تا فرات امتداد می‌یابد.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["آهموس به نوبهٔ سفلی لشکر کشید و کوچ‌نشینان نوبه را سرکوب کرد", "dbbd94b7"], "d": ["آهموس پس از شکست دادن آسیایی‌ها از رود به جنوب، به Khent-hen-nefer، رفت و کوچ‌نشینان نوبه را سرکوب کرد. این لشکرکشی نخستین گام روند پیوستن نوبهٔ سفلی، که از خط دژهای پادشاهی میانه تا آن زمان در دست Kerma بود، به مصر است.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["آهموس Avaris، پایتخت هیکسوس‌ها، را گرفت و Sharuhen را محاصره و سرنگون کرد", "b7bb3099"], "d": ["آهموس Avaris را در دلتای شرقی محاصره کرد و گرفت؛ هیکسوس‌ها به آسیا گریختند و او آنان را تا Sharuhen در کنعان جنوبی دنبال کرد. کتیبهٔ آهموس، پسر Ebana، محاصرهٔ 6 سالهٔ Sharuhen را گزارش می‌دهد. بدین‌سان دلتای مصر از نظارت هیکسوس‌ها بیرون آمد و مصر در موقعیتی قرار گرفت که بتواند نفوذ سیاسی بر کنعان اعمال کند.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["آهموس یکم در طیبه بر تخت نشست؛ سلسلهٔ XVIII و دورهٔ پادشاهی نو آغاز شد", "0798cfa3"], "d": ["آهموس، برادر Kamose، واپسین پادشاه سلسلهٔ XVII در طیبه، در کودکی بر تخت نشست؛ در طول سلطنتش هیکسوس را از مصر راند و سلطه بر نوبه و کنعان را دوباره برقرار کرد و سلسلهٔ XVIII و دورهٔ پادشاهی نو را آغاز نمود. بر تخت نشستن پایان هیکسوس نیست، آغاز واپسین مرحلهٔ نبرد است.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["مصر دو پاره شد: هیکسوس‌ها (سلسلهٔ XV) از Avaris بر مصر سفلی و میانه، و سلسلهٔ XVII در طیبه بر مصر علیا فرمان راندند", "cd743737"], "d": ["«فرمانروایان بیگانه» (هیکسوس) با ریشهٔ کنعانی که در Avaris در دلتای شرقی ساکن شده بودند، سلسلهٔ XV را بنیان نهادند و مصر سفلی و میانه را تا Cusae (Kusiye) اداره کردند؛ سلسلهٔ بومی XVII در طیبه مصر علیا را در دست داشت. در جنوب طیبه پادشاهی Kerma به‌عنوان نیرویی مستقل ماند. اینکه Avaris پایتخت هیکسوس بود، با روایت محاصرهٔ آهموس در Breasted تأیید می‌شود.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["سنوسرت سوم در Semne مرز جنوبی مصر را به آبشار دوم کشاند؛ گذر نوبیان را ممنوع کرد", "753ef5fd"], "d": ["لوح Semne، مورخ سال 8 سنوسرت سوم، «مرز جنوبی» را معین می‌کند: نوبیان، جز آنان که برای تجارت به Iken می‌آیند، از راه خشکی یا رود حق گذشتن از این خط را ندارند. شاه در نوبهٔ سفلی زنجیره‌ای از دژها (Buhen، Semne، Kumme، Uronarti و جز آن) ساخت و گشایش Kerma به سوی شمال را متوقف کرد. این جنوبی‌ترین مرز پایدار پادشاهی میانه در نوبه است.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["آمنمحات یکم سلسلهٔ XII را بنیان نهاد؛ پایتخت به Itj-tawy منتقل شد", "26c43dad"], "d": ["آمنمحات یکم که وزیر بود و شاه شد، سلسلهٔ XII را بنیان نهاد و پایتخت را از طیبه به شهر تازه‌ای میان ممفیس و Fayum (Itj-tawy) برد. این سلسله باثبات‌ترین دورهٔ پادشاهی میانه و نظام دژها در نوبه را بنیان نهاد.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["منتوحتپ دوم Herakleopolis را شکست داد و مصر را دوباره یکی کرد (Sematawy)", "dbc6136f"], "d": ["منتوحتپ دوم نزدیک سال 39 سلطنتش با از میان برداشتن Herakleopolis مصر علیا و سفلی را در یک اداره گرد آورد و نام «یکی‌کنندهٔ دو سرزمین» (Sematawy) را به عنوان خود افزود. اداره‌ٔ مرکزی به طیبه منتقل شد؛ اختیارات nomarkها کاسته شد.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["منتوحتپ دوم در طیبه بر تخت نشست؛ دورهٔ پادشاهی میانه آغاز شد و جنگ علیه Herakleopolis شدت گرفت", "edde038d"], "d": ["سلطنت طولانی منتوحتپ دوم (51 سال) آغاز پادشاهی میانه شمرده می‌شود. در نیمهٔ نخست سلطنتش طیبه با Herakleopolis در جنگ بود؛ در سال 14 او، پس از آنکه نیروهای Herakleopolis گورستان مقدس Abydos را پایمال کردند، شاه سپاه به شمال فرستاد. یکی شدن عملی مصر بسیار دیرتر، در سال‌های 39 سلطنتش، رخ داد (مدخل زیر).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["در طیبه سلسلهٔ XI آغاز شد: خاندان Intef در مصر علیا پادشاهی مستقل بنیان نهاد", "0e021743"], "d": ["nomarkهای طیبه از تبار Intef عنوان پادشاهی گرفتند و در جنوبی‌ترین انتهای مصر علیا (از الفانتین تا Abydos) پادشاهی خود را بنیان نهادند. Intef بعدی در کتیبه‌اش می‌گوید nomos Tinis، که Abydos در آن است، را گرفت و «همهٔ دژهایش را گشود»؛ بدین‌سان مرز طیبه-Herakleopolis پیرامون Abydos کشیده شد.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["در Herakleopolis (Henen-nesut) سلسله‌های IX-X: خاندان Kheti بر مصر شمالی فرمان راند", "9dde2d0c"], "d": ["در دورهٔ میانی نخست، خلأ ممفیس را خاندان Herakleopolis پر کرد؛ nomarkهای وفادار، مانند Tefibi والی Siut در مصر میانه، علیه جنوب (طیبه) در کنار این پادشاهی جنگیدند. کتیبهٔ آرامگاه Siut از پیشروی جنوبی‌ها از الفانتین به شمال و راندن آنان تا «مرز جنوبی» حکایت می‌کند. مصر بدین‌سان میان دو نیروی اصلی، Herakleopolis (شمال) و طیبه (جنوب)، تقسیم شد.", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["پادشاهی کهن فروپاشید: پس از پپی دوم دولت مرکزی از هم پاشید، دورهٔ میانی نخست آغاز شد", "0339e96b"], "d": ["پس از سلطنت بسیار طولانی پپی دوم سلسلهٔ VI پایان یافت؛ پادشاهی به مناطقی که nomarkها (والیان ایالت‌ها) عملاً مستقل ماندند تقسیم شد. کتیبه‌های آرامگاه (Siut، الفانتین و جز آن) نشان می‌دهند والیان محلی به نام خود تاریخ می‌دادند و سپاه خود را بسیج می‌کردند. سلسله‌های کوتاه‌عمر VII-VIII در ممفیس نتوانستند بر همهٔ کشور نظارت کنند.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["لشکرکشی‌های Harkhuf، والی الفانتین، به سرزمین Yam: پیوند دیپلماتیک-تجاری فراتر از نوبه", "705b9808"], "d": ["Harkhuf، والی الفانتین، برای Merenre و پپی دوم چند بار به جنوب، به سرزمین Yam، رفت؛ در کتیبه‌اش راهی که بر آن چیره بود و فرآورده‌هایی که آورد شرح داده می‌شود. نامه‌ای که پپی دوم، شاه کودک، به او نوشت نیز در کتیبهٔ آرامگاه حفظ شده است. این لشکرکشی‌ها ثبت پیوند با جوامع پیش از Kerma/Kerma کهن در مرز جنوبی پادشاهی کهن است.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["در سلسلهٔ VI به فرماندهی Weni لشکرکشی بزرگ به مرز کنعان و با یگان‌های نوبی", "69c94c55"], "d": ["بر پایهٔ زندگی‌نامهٔ Weni، شاه علیه «ساکنان شن آسیایی» سپاهی ده‌ها هزار نفری گرد آورد؛ سپاه از یگان‌های جنوب مصر (تا الفانتین)، شمال و نیز از طایفه‌های نوبه (Irtjet، Medja، Yam، Wawat، Kau) تشکیل شده بود. متن نشان می‌دهد که پادشاهی کهن از نوبه به‌عنوان مخزن سرباز بهره می‌برد و می‌توانست تا کنعان جنوبی لشکر بکشد.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["هرم بزرگ خوفو (خئوپس) در جیزه ساخته شد", "282359fc"], "d": ["هرم خوفو، فرمانروای سلسلهٔ IV، در جیزه نماد بسیج نیروی کار و منابع پادشاهی کهن است. روایت کاهنان مصری که هرودوت نقل می‌کند، خوفو را ستمگری می‌نمایاند که معابد را می‌بست و مردم را به حمل سنگ وامی‌داشت؛ این دیدگاه دوره‌ای بعدتر است، نه سند هم‌روزگار.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["جوسر (سلسلهٔ III) بر تخت نشست؛ دورهٔ پادشاهی کهن و هرم پله‌ای سقاره", "23e99ef4"], "d": ["با قدرت جوسر (Netcherikhet) پادشاهی کهن به مرکزیت ممفیس آغاز می‌شود؛ هرم پله‌ای، نخستین نمونهٔ بزرگ معماری سنگی، برای او ساخته شد. در این دوره دولت دره نیل و دلتا را از مرکز اداره می‌کند؛ معادن سینا و مرز نوبه (الفانتین) زیر نظارت دولت است.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["نارمر (منس) مصر علیا و سفلی را یکی کرد؛ سلسلهٔ I و ممفیس پایتخت شد", "cd3fadb1"], "d": ["نارمر، فرمانروای مصر علیا (پیرامون Tinis/Abydos)، به گفتهٔ بیشتر مصرشناسان با منس یک تن است. با افزودن مصر سفلی به قلمرو خود، دره نیل و دلتا برای نخستین بار یک دولت شد. بنا بر روایت کهن، منس با منحرف کردن بستر نیل جایگاه ممفیس را بنیان نهاد؛ یکی شدن یک رویداد نیست، نتیجهٔ روندی طولانی است که از Naqada III ادامه داشت.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["وسپاسیانوس در اسکندریه امپراتور اعلام شد: غلهٔ مصر سرنوشت جنگ داخلی را تعیین کرد", "02b78348"], "d": ["تیبریوس اسکندر، پرفکت مصر، از لژیون‌های اسکندریه به نام وسپاسیانوس سوگند وفاداری گرفت؛ سوگند در 1 ژوئیه انجام شد و وسپاسیانوس این روز را روز بر تخت نشستن خود شمرد. سپاه یهودی دو روز بعد در برابر وسپاسیانوس سوگند خورد. تولید غلهٔ مصر پشتوانهٔ راهبردی این اقدام شمرده می‌شود.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["شورش یهودیان در مصر، Kirene و قبرس: روم در دورهٔ تراژان با دشواری منطقه را سرکوب کرد", "54787782"], "d": ["در حالی که لشکرکشی پارتی تراژان ادامه داشت، در Kirene یهودیان به رهبری آندریاس رومیان و یونانیان را کشتند؛ بنا بر دیو در مصر و قبرس نیز رویدادهای مشابه رخ داد و شمار کشته‌ها به صدها هزار بیان شد. Lusius Quietus که تراژان فرستاد شورش را سرکوب کرد؛ ورود یهودیان به قبرس ممنوع شد.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["قیام Bukoli: شورشی در دلتا اسکندریه را تهدید کرد، آویدیوس کاسیوس سرکوب کرد", "5f94e6bf"], "d": ["مردم دلتا که Bukoli (چوپانان) نامیده می‌شدند، به رهبری کاهنی به نام ایزیدوروس شوریدند؛ بنا بر دیو، شورشیان یک یگان رومی را شکست دادند و چیزی نمانده بود اسکندریه را بگیرند. کاسیوس که از سوریه فرستاده شد با از هم پاشاندن یگان شورشیان قیام را سرکوب کرد.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["آویدیوس کاسیوس در سوریه و مصر خود را امپراتور اعلام کرد؛ سه ماه بعد کشته شد", "ce33ca9d"], "d": ["کاسیوس، فرمانده ایالت‌های شرقی، با خبر مرگ مارکوس اورلیوس امپراتوری اعلام کرد؛ شورش به سوریه و مصر گسترش یافت (در دیو آمده که والی مصر، Flavius Calvisius، به سبب پیوند با شورش بعدها کشته نشد و به جزیره‌ای تبعید گشت). کاسیوس بنا بر دیو پس از «رؤیای امپراتوری»ای که سه ماه و شش روز ادامه یافت به‌دست یکی از افسران خود کشته شد؛ مارکوس اورلیوس از مصر و سوریه دیدن کرد و کسی را مجازات نکرد.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["پالمیرا (زنوبیا) مصر را اشغال کرد؛ سردار رومی پروبوس شکست خورد", "54568441"], "d": ["Zabdas، سردار پالمیرایی که به نام زنوبیا عمل می‌کرد، با سپاه هفتادهزارنفری‌اش وارد مصر شد؛ سردار رومی Tenagino Probus مدتی اسکندریه را بازپس گرفت، اما شکست خورد و در دژ Babylon پناه گرفت و چون اسیر شد خودکشی کرد. مصر یکی دو سال به نام زنوبیا بخشی از دولت پالمیرا شمرده شد.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Domitius Domitianus در مصر امپراتور اعلام شد؛ دیوکلتیانوس با محاصرهٔ طیبه و سپس اسکندریه شورش را سرکوب کرد", "3c765005"], "d": ["در واکنش به اصلاح مالیاتی و کشیده شدن یگان‌های رومی به جبههٔ اشکانی، در مصر Domitius Domitianus در ژوئیه-اوت 297 آگوستوس اعلام شد؛ بیشتر مصر، از جمله اسکندریه، او را شناخت. دیوکلتیانوس در پاییز شورشیان طیبه را سرکوب کرد و اسکندریه را محاصره نمود؛ Domitianus در دسامبر 297 درگذشت، دفاع شهر را Aurelius Achilleus ادامه داد و شهر پس از محاصره‌ای حدود هشت‌ماهه به احتمال زیاد در مارس 298 تسلیم شد.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["دیوکلتیانوس مرز جنوبی مصر را به خط الفانتین/فیله کشاند؛ نوبهٔ سفلی به Nobatae واگذار شد", "725574bb"], "d": ["پروکوپیوس روایت می‌کند که دیوکلتیانوس هزینهٔ نگه داشتن صحرای پهناور جنوبی‌ترین بخش مصر (Dodekaschoinos) را دید و جنوب الفانتین را به Nobatae و Blemmyes واگذاشت و مرز را در الفانتین ثابت کرد (گفته می‌شود در برابر آن پرداخت سالانه بسته شد). اداره‌ٔ روم بدین‌سان از مرز Hiera Sykaminos که آگوستوس کشیده بود عقب نشست.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["عزانا، پادشاه اکسوم، کوش را شکست داد؛ پادشاهی Meroe پایان یافت (حدود 350 میلادی)", "7c9d95d7"], "d": ["عزانا، پادشاه اکسوم، به پادشاهی کوش که زیر فشار Noba و Blemmyes ضعیف شده بود حمله برد؛ کتیبه‌های عزانا لشکرکشی او را علیه مردم Noba و Kasu (کوش) روایت می‌کنند، در Meroe دو کتیبهٔ پاره‌پارهٔ یونانی متعلق به پیروزی اکسوم یافت شده است. واپسین هرم‌های Meroe به میانهٔ سدهٔ 4 تاریخ‌گذاری می‌شود؛ دولت کوش از هم پاشید و به پادشاهی‌های Nobatia، Makuria و Alodia تقسیم شد.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["تئوفیلوس Serapeum اسکندریه را ویران کرد: مرکز پرستش بت‌پرستان در مصر بسته شد", "119a26c7"], "d": ["پس از فرمان‌های تئودوسیوس یکم که آیین‌های بت‌پرستی را ممنوع می‌کرد، تئوفیلوس، اسقف اسکندریه، معبد Serapis (Serapeum) را ویران کرد؛ تنش میان مسیحیان و بت‌پرستان در شهر در این رویداد به اوج رسید. سرنوشت متن‌های مقدس و مجموعه‌های کتاب مورد مناقشه است.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["تئودوسیوس یکم درگذشت؛ امپراتوری برای همیشه دو پاره شد، مصر در روم شرقی (آرکادیوس) ماند", "54a12472"], "d": ["با مرگ تئودوسیوس پسرانش آرکادیوس شرق و هونوریوس غرب را گرفتند؛ مصر، با آنکه تأمین‌کنندهٔ اصلی نیاز روم به غله بود، ایالت امپراتوری شرقی (بیزانس) ماند و در سده‌های بعد منبع غلهٔ قسطنطنیه شد.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["شورای خلقدون: دیوسکوروس، پاتریارک اسکندریه، محکوم شد؛ کلیسای مصر از کلیسای امپراتوری جدا شد", "5d2d05c6"], "d": ["هنگامی که شورای خلقدون دیوسکوروس، پاتریارک اسکندریهٔ مصر، را محکوم کرد، بیشتر مسیحیان مصر تصمیم‌ها را نپذیرفتند؛ بدین‌سان در مصر کلیسای قبطی (مصری) از کلیسای امپراتوری (ملکیان) جدا شد. این شکاف در سده‌های بعد زمینهٔ دوری سیاسی مصر از بیزانس را فراهم کرد.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["پیمان آگوستوس و فرهاد چهارم: درفش‌های رومی کراسوس بازگردانده شد", "be5f8bda"], "d": ["درفش‌های گم‌شدهٔ رومی کراسوس و آنتونیوس به‌دست فرهاد چهارم با ژستی دیپلماتیک به آگوستوس بازگردانده شد. پیمان فرات را مرز روم-اشکانی استوار کرد و ارمنستان را حائل گذاشت.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["پاکور و Labienus سوریه و فلسطین را اشغال کردند", "68669aa1"], "d": ["شاهزادهٔ اشکانی پاکور و Labienus، که از روم گریخته و به اشکانیان پناه برده بود، ایالت‌های سوریهٔ روم را اشغال کردند و انطاکیه و فلسطین را گرفتند. Ventidius، سردار آنتونیوس، در 38 اشکانیان را در Gindaros شکست داد و منطقه را بازپس گرفت.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["نبرد Carrhae (حران): سورنا سپاه رومی کراسوس را نابود کرد", "3a91cd75"], "d": ["لژیون‌های رومی کراسوس نزدیک حران از سواره‌نظام و کمانداران سواره اشکانی شکست خوردند؛ کراسوس کشته شد. این نبرد یکی از سنگین‌ترین شکست‌های روم در شرق است و مرز فرات را به سود اشکانیان استوار کرد.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["سولا با فرستادهٔ اشکانی Orobazos در فرات دیدار کرد؛ نخستین تماس دیپلماتیک روم-اشکانی", "f8913f2b"], "d": ["سولا، والی کاپادوکیه، با Orobazos، فرستادهٔ مهرداد دوم، شاه اشکانی، در کرانهٔ فرات دیدار کرد؛ روم و اشکانیان برای نخستین بار تماس رسمی برقرار کردند. فرات بعدها مرز دو دولت خواهد بود.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["آنتیوخوس هفتم سیدتس در لشکرکشی علیه اشکانیان کشته شد؛ سلوکیان بین‌النهرین را بازپس نگرفتند", "e5897112"], "d": ["آنتیوخوس هفتم سیدتس در 130-129 بین‌النهرین و ماد را از اشکانیان بازپس گرفت، اما در اردوی زمستانی با شورش و حملهٔ اشکانی سپاه و جان خود را از دست داد. این ناکامی ادعای شرقی سلوکیان را پایان داد.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["اشکانیان دمتریوس دوم نیکاتور را اسیر کردند؛ سلوکیان بابل و بین‌النهرین را قطعاً از دست دادند", "94a764ce"], "d": ["سپاه اشکانی مهرداد یکم دمتریوس دوم، شاه سلوکی، را گرفت و او را در دربار اشکانی نگه داشت. مهرداد بین‌النهرین را به امپراتوری اشکانی افزود؛ دولت سلوکی به ساحل تنگ شد و به سوریه عقب نشست.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["قیام مکابیان: در یهودیه علیه ممنوعیت‌های دینی آنتیوخوس چهارم قیام آغاز شد", "41c25b76"], "d": ["چون آنتیوخوس چهارم اپیفانس معبد اورشلیم را به زئوس المپی اهدا کرد و آیین‌های دینی یهودی را ممنوع ساخت، در Modein متتیاهو و پسرانش شوریدند. یهودا مکابی در 164 معبد را بازپس گرفت و پاک کرد (حنوکا)؛ دولت حشمونایی پدید آمد.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["مهرداد یکم بر تخت اشکانی نشست؛ دورهٔ گسترش امپراتوری اشکانی آغاز شد", "cc77639b"], "d": ["مهرداد یکم اشکانیان را به امپراتوری بدل کرد: ماد (147)، بابل و Seleukeia (141) را گرفت، بر Elymais و پارس سلطه برقرار کرد. تیسفون بعدها پایتخت زمستانی خواهد بود.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["پیمان Apameia: سلوکیان از غرب توروس عقب نشستند، غرامت پرداختند", "f5197a70"], "d": ["پیمان میان روم و آنتیوخوس سوم آناتولی غرب توروس را به متحدان روم (پرگامون، رودس) داد؛ ناوگان و شمار فیل‌های سلوکی محدود شد، 15.000 تالنت غرامت پرداخت شد. سلوکیان دیگر به دولت سوریه-بین‌النهرین بدل شدند.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["لشکرکشی شرقی آنتیوخوس سوم (209-204): شاهان اشکانی و باختری مشمول خراج سلوکی شدند", "5c81f302"], "d": ["آنتیوخوس سوم برای بازپس‌گیری سرزمین‌های شرقی ازدست‌رفتهٔ سلوکیان به ماد، اشکانیان و باختر لشکر کشید: اشک دوم و Euthydemos مشمول خراج شدند. پس از این لشکرکشی آنتیوخوس عنوان «بزرگ» را گرفت.", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["اشک یکم و تیرداد Parthava را گرفتند و دولت اشکانی را بنیان نهادند", "2cd572ca"], "d": ["اشک، رهبر قبیلهٔ کوچ‌نشین Parni، Andragoras، ساتراپ سلوکی، را برانداخت و Parthava را گرفت و نخستین پادشاه پادشاهی اشکانی شد؛ پایتختش Hekatompylos است. دولت اشکانی در سه سدهٔ بعد فرمانروای بین‌النهرین و ایران خواهد بود.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["دیودوتوس، ساتراپ باختر، از سلوکیان جدا شد؛ پادشاهی یونانی-باختری پدید آمد", "52faafa6"], "d": ["دیودوتوس، ساتراپ باختر و سغد، از ضعف آنتیوخوس دوم سود جست و استقلال خود را اعلام کرد. یونانی-باختری مرز شرقی دولت سلوکی را به عقب‌نشینی از Parthava و باختر واداشت.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["جنگ نخست سوریه (274-272): نیروهای سلوکی دمشق را بازپس گرفتند؛ صلح بسته شد", "0c17ee3d"], "d": ["آنتیوخوس یکم، پس از آنکه با «جنگ فیل‌ها» (275) گالاتی‌ها را شکست داد و ایمن شد، دوباره با بطلمیوس دوم جنگید: سردار سلوکی دمشق را بازپس گرفت، Magas به مصر حمله برد و سرانجام در 272 صلح بسته شد. جنگ آغاز کشمکش بطلمیوسی-سلوکی بر کوئله‌سوریه است.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["جنگ Karia: بطلمیوس دوم یونیه، Karia، لوکیه، پامفیلیا و بخشی از کیلیکیه را از آنتیوخوس یکم گرفت", "afe190ca"], "d": ["بطلمیوس دوم در لشکرکشی کوتاه و موفقی کرانهٔ جنوب و غرب آناتولی را گرفت و به دمشق رسید؛ چون دید نیروی آنتیوخوس کم‌تر از پدرش نیست آتش‌بس کرد. آنتیوخوس زیان را پذیرفت، زیرا باید فتوحات پدرش را در درون آناتولی سامان می‌داد.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["سلوکوس یکم به‌دست بطلمیوس کرائونوس کشته شد؛ آنتیوخوس یکم بر تخت نشست", "4703b674"], "d": ["سلوکوس که در Kuropedion لیسیماکوس را شکست داده و آناتولی را گرفته بود، هنگام گذر به اروپا به‌دست بطلمیوس کرائونوس با خنجر کشته شد. پسرش آنتیوخوس یکم دولت را بر عهده گرفت، اما در آناتولی غربی دشواری خواهد دید.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["سلوکوس یکم انطاکیه را بنیان نهاد", "f4b98967"], "d": ["سلوکوس پس از ایپسوس در سوریه در کرانهٔ Orontes به نام پدر خود انطاکیه را بنیان نهاد؛ شهر پایتخت غربی پادشاهی سلوکی و یکی از بزرگ‌ترین شهرهای عهد باستان شد. Seleukeia در دجله پیش‌تر به‌عنوان پایتخت شرقی بنیان نهاده شده بود.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["نبرد ایپسوس: سلوکوس و لیسیماکوس آنتیگونوس را شکست دادند؛ سوریه به سلوکوس رسید", "93bf2aa9"], "d": ["در نبرد تعیین‌کنندهٔ جنگ‌های دیادوخی‌ها، سلوکوس و لیسیماکوس آنتیگونوس را شکست دادند (آنتیگونوس در نبرد کشته شد). همهٔ شرق و سوریه به سهم سلوکوس رسید؛ بطلمیوس اما با اشغال کوئله‌سوریه سبب نخستین جنگ‌های سوریه را فراهم آورد.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["سلوکوس یکم Seleukeia را بر دجله بنیان نهاد", "032efabd"], "d": ["سلوکوس در نزدیکی بابل، در کرانهٔ دجله، Seleukeia را بنیان نهاد و آغاز به انتقال جمعیت بابل به آنجا کرد. Seleukeia با جمعیتی حدود 300 هزار نفر بزرگ‌ترین شهر هلنیستی شرق و سپس همسایهٔ پایتخت امپراتوری اشکانی شد.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["سلوکوس یکم در هند با چاندراگوپتا موریا پیمان بست؛ Arakosya، Gedrosya و Paropamisadai به موریا واگذار شد", "3ef3bdee"], "d": ["سلوکوس برای بازپس‌گیری ساتراپی‌های هندی اسکندر به هند لشکر کشید، اما با چاندراگوپتا توافق کرد و بخشی از سرزمین‌های شرقی را با 500 فیل جنگی معاوضه کرد. پیمان مرز غربی امپراتوری موریا را به هندوکش برد و برای غرب فیل‌ها را به سلوکوس رساند.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["اسکندر چهارم همراه مادرش رکسانه کشته شد؛ خاندان Argead پایان یافت", "3be9d974"], "d": ["پس از صلح 311، به فرمان کاساندروس (بنا بر دیودور جلاد Glaukias) اسکندر چهارم دوازده‌ساله و مادرش رکسانه کشته شدند. از امپراتوری اسکندر فرمانروای اسمی‌ای نماند؛ دیادوخی‌ها به اعلام پادشاهی‌های خود روی آوردند (306-305 پیش از میلاد).", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["اسکندر به تخت جمشید رسید؛ شهر و خزانه به دست مقدونیان افتاد", "c1dbaada"], "d": ["اسکندر که پس از شوش از دروازه‌های پارس گذشت، در پایان ژانویهٔ 330 به تخت جمشید رسید؛ شهر بی‌مقاومت تسلیم شد. مالکیت هخامنشی بر تخت جمشید در این سال پایان می‌یابد (کاخ در مه 330 سوزانده شد).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["سوزاندن کاخ‌های تخت جمشید (آوریل)", "6e6cdfe0"], "d": ["اسکندر در آوریل 330 در تخت جمشید چند ساختمان کاخ را سوزاند؛ دلایل «نیفتادن خزانه به دست دشمن» و «هنوز پادشاه یگانه نبودن» آورده می‌شود. سوختن کاخ خشایارشا نیز از نظر باستان‌شناختی دیده می‌شود؛ سراسر شهر رها شد.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["داریوش سوم به‌دست مردان بسوس، ساتراپ باختر، کشته شد؛ خاندان هخامنشی پایان یافت", "bedcca87"], "d": ["داریوش سوم که از هگمتانه به شرق گریخته بود، در ژوئیهٔ 330 در پارت به‌دست بسوس و همراهانش زخمی و رها شد و مرد؛ اسکندر پیکر را به تخت جمشید فرستاد. پایان عملی امپراتوری هخامنشی.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["نبرد گوگمل: اسکندر سپاه داریوش سوم را قطعاً شکست داد", "a5b082d7"], "d": ["در گوگمل سپاه داریوش، که شمار بسیاری ارابهٔ جنگی و سواره‌نظام داشت، در حمله‌ای که اسکندر با دفاع جناح چپ شکافت و به درون آن راه یافت، پراکنده شد؛ داریوش باز گریخت. نبرد پایان امپراتوری پارس را معین کرد؛ بابل و شوش دروازه‌های خود را گشودند.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["اسکندر وارد بابل شد؛ Mazaios شهر را تسلیم کرد و ساتراپی بابل به اسکندر رسید", "c8d2afb3"], "d": ["پس از گوگمل، Mazaios، ساتراپ بابل، دروازه‌ها را به روی اسکندر گشود؛ اسکندر فرمان بازسازی معبد مردوک را داد و 34 روز از شهر بهره برد. بابل از اداره‌ٔ پارسی به اداره‌ٔ مقدونی درآمد.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["اسکندر شوش را گرفت؛ خزانهٔ پارس به دست افتاد", "fbf417db"], "d": ["اسکندر که از بابل رفت وارد شوش شد؛ ساتراپ Abulites شهر و خزانهٔ بزرگ را تسلیم کرد. شوش پایهٔ مالی لشکرکشی شرقی مقدونیه شد.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["محاصرهٔ صور: اسکندر شهر جزیره‌ای را با ساختن خاک‌ریز گرفت و ویران کرد", "89ede146"], "d": ["اسکندر جزیرهٔ صور، پایگاه ناوگان پارس، را در هفت ماه با ساختن گذرگاهی مصنوعی گرفت؛ شهر غارت شد، بخش بزرگی از مردم کشته یا برده شدند. قدرت دریایی پارس بدین‌سان فروپاشید و راه مصر گشوده شد.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["نبرد ایسوس: اسکندر داریوش سوم را شکست داد؛ داریوش خانواده را رها کرد و گریخت", "3803fc30"], "d": ["در دشت ساحلی تنگی سپاه بزرگ داریوش سوم از اسکندر شکست خورد؛ شاه پارس خانواده و خزانه‌اش را رها کرد و گریخت. پیروزی ایسوس سبب شد سوریه و کرانهٔ فینیقیه و سپس مصر به اسکندر برسد.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["نبرد گرانیکوس: اسکندر ساتراپ‌های پارس را شکست داد", "1aae30d4"], "d": ["اسکندر، پادشاه مقدونیه، در مه 334 به آسیا گذشت و در آغاز ژوئن در گرانیکوس ساتراپ‌های پارس را شکست داد. دروازه‌های آناتولی غربی گشوده شد؛ سارد و شهرهای ایونیا به اسکندر تسلیم شدند.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["داریوش سوم بر تخت پارس نشست (کشته شدن Arses)", "706f8a9f"], "d": ["بگواس، کارگزار دربار، اردشیر چهارم را کشت؛ ساتراپ ارمنستان Artašata با نام داریوش سوم (Codomannus) شاه شد. در اکتبر 336 در مقدونیه فیلیپ کشته شد و اسکندر بر تخت نشست.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["اردشیر سوم درگذشت؛ اردشیر چهارم (Arses) بر تخت نشست", "d38e2edc"], "d": ["اردشیر سوم در تابستان 338 به سبب‌های طبیعی (با وجود روایت مسموم‌سازی در دیودور) درگذشت؛ Arses بر تخت نشست. شورش‌های مصر و بابل و تدارک‌های آناتولیایی فیلیپ، شاه مقدونیه، در همین دوره قرار می‌گیرد.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["اردشیر سوم صیدا را گرفت و ویران کرد؛ شورش Tennes سرکوب شد", "d1b533cc"], "d": ["در جریان شورش ضدپارسی Tennes، شاه صیدا، که مصر پشتیبان آن بود، اردشیر سوم شهر را گرفت؛ Tennes به پارسیان خیانت کرد، شهر خود را سوزاند و شمار بسیاری کشته شدند. شهرهای فینیقیه دوباره زیر نظارت پارس درآمدند و راه فتح مصر گشوده شد.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["صلح شاه (Antalkidas): شهرهای یونانی آناتولی و قبرس به پارس واگذار شد", "17e871ad"], "d": ["با صلحی که اردشیر دوم، شاه پارس، دیکته کرد، شهرهای یونانی آسیا و قبرس از آنِ پارس شمرده شد و به شهرهای یونانی خودمختاری داده شد. اسپارت به‌عنوان سخنگوی پارس صلح را اجرا کرد.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["نبرد کوناکسا: کوروش کوچک از برادر بزرگ‌ترش اردشیر دوم شکست خورد و کشته شد", "90346087"], "d": ["کوروش کوچک با ده‌هزار تن، که سربازان مزدور یونانی بودند، به بابل لشکر کشید و در کوناکسا از برادر بزرگ‌ترش اردشیر دوم شکست خورد و در نبرد کشته شد. لشکرکشی بازگشت ده‌هزار تن به دریای سیاه در آناباسیس گزنفون روایت شده است.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["خشایارشا از هلسپونت گذشت؛ ترموپیل و گرفتن آتن", "9bf22df1"], "d": ["خشایارشا با سپاه بزرگش در ترموپیل یگان اسپارتی-متحد لئونیداس را شکست داد و وارد آتیکا شد؛ آتن تخلیه شد و همراه با آکروپولیس سوزانده شد. سپاه پارس تا میانهٔ یونان پیش رفت.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["نبرد دریایی سالامیس: ناوگان یونان ناوگان پارس را درهم شکست", "010e3aab"], "d": ["ناوگان یونان به فرماندهی تمیستوکلس در سالامیس ناوگان پارس را در تنگه شکست داد و برتری دریایی را به دست آورد. خشایارشا با بیشتر سپاه زمینی به آسیا بازگشت، ماردونیوس در یونان ماند.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["شورش‌های Bêl-šimânni و Šamaš-eriba در بابل به‌دست خشایارشا یکم سرکوب شد", "ebcef5a9"], "d": ["در آغاز سلطنت خشایارشا یکم در بابل دو شورش برخاست (Bêl-šimânni، Šamaš-eriba). خشایارشا شورش‌ها را سرکوب کرد؛ ساتراپی بابل را تقسیم کرد و امتیازات شهر را کاست.", "015c253c"]}
});
